export default CustomersView;

import React, { useState } from 'react';
import { 
  ShoppingCart, 
  Plus, 
  Trash2, 
  User, 
  Package, 
  CheckCircle2, 
  Clock, 
  ArrowRight,
  Search,
  X
} from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';

interface OrdersViewProps {
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  products: Product[];
  customers: Customer[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, setOrders, products, customers, setProducts }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [productSearch, setProductSearch] = useState('');

  const addToCart = (product: Product) => {
    if (product.stock <= 0) return alert('Produto sem estoque!');

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) {
          alert('Quantidade máxima atingida para o estoque disponível.');
          return prev;
        }
        return prev.map(item => 
          item.productId === product.id 
            ? { ...item, quantity: item.quantity + 1 } 
            : item
        );
      }
      return [...prev, { 
        productId: product.id, 
        quantity: 1, 
        priceAtTime: product.price,
        nameAtTime: product.name
      }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.productId !== productId));
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.priceAtTime * item.quantity), 0);

  const finalizeOrder = () => {
    if (!selectedCustomerId) return alert('Selecione um cliente!');
    if (cart.length === 0) return alert('O carrinho está vazio!');

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      customerId: selectedCustomerId,
      items: [...cart],
      total: cartTotal,
      status: 'PAID',
      createdAt: new Date().toISOString()
    };

    // Update stock
    setProducts(prev => prev.map(p => {
      const itemInCart = cart.find(i => i.productId === p.id);
      if (itemInCart) {
        return { ...p, stock: p.stock - itemInCart.quantity };
      }
      return p;
    }));

    setOrders([...orders, newOrder]);
    setCart([]);
    setSelectedCustomerId('');
    setIsCreating(false);
  };

  const getCustomerName = (id: string) => customers.find(c => c.id === id)?.name || 'Cliente Removido';

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-300">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Vendas e Pedidos</h2>
          <p className="text-gray-500 text-sm">Controle sua movimentação financeira.</p>
        </div>
        {!isCreating && (
          <button 
            onClick={() => setIsCreating(true)}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-xl font-semibold flex items-center gap-2 transition-all shadow-md shadow-indigo-100"
          >
            <Plus size={20} />
            Nova Venda
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Product Selection */}
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-3">
              <Search className="text-gray-400" size={20} />
              <input 
                type="text" 
                placeholder="Buscar produto por nome..."
                value={productSearch}
                onChange={(e) => setProductSearch(e.target.value)}
                className="bg-transparent border-none outline-none flex-1 text-sm text-gray-700"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {products
                .filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase()))
                .map(product => (
                  <button 
                    key={product.id}
                    onClick={() => addToCart(product)}
                    className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm hover:border-indigo-300 hover:bg-indigo-50/30 transition-all text-left group"
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div className="p-2 rounded-lg bg-indigo-50 text-indigo-600">
                        <Package size={18} />
                      </div>
                      <span className="text-xs font-bold text-gray-400">ESTOQUE: {product.stock}</span>
                    </div>
                    <h4 className="font-bold text-gray-800 truncate">{product.name}</h4>
                    <p className="text-lg font-bold text-indigo-600 mt-1">R$ {product.price.toFixed(2)}</p>
                    <div className="mt-3 flex items-center gap-1 text-xs font-semibold text-indigo-500 opacity-0 group-hover:opacity-100 transition-opacity">
                      <span>ADICIONAR AO CARRINHO</span>
                      <ArrowRight size={14} />
                    </div>
                  </button>
                ))}
            </div>
          </div>

          {/* Cart / Checkout */}
          <div className="bg-white rounded-3xl shadow-xl border border-gray-100 flex flex-col h-fit sticky top-4">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50 rounded-t-3xl">
              <h3 className="font-bold text-gray-800 flex items-center gap-2">
                <ShoppingCart size={20} className="text-indigo-600" />
                Carrinho
              </h3>
              <button onClick={() => { setIsCreating(false); setCart([]); }} className="text-gray-400 hover:text-gray-600">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-6 flex-1 overflow-y-auto max-h-[60vh]">
              {/* Customer Select */}
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Cliente</label>
                <select 
                  className="w-full bg-gray-50 border border-gray-100 px-4 py-2.5 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                  value={selectedCustomerId}
                  onChange={(e) => setSelectedCustomerId(e.target.value)}
                >
                  <option value="">Selecionar cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>

              {/* Cart Items */}
              <div className="space-y-4">
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider">Itens</label>
                {cart.length > 0 ? (
                  cart.map(item => (
                    <div key={item.productId} className="flex justify-between items-center group">
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-semibold text-gray-800 truncate">{item.nameAtTime}</p>
                        <p className="text-xs text-gray-500">{item.quantity}x R$ {item.priceAtTime.toFixed(2)}</p>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="font-bold text-gray-800 text-sm">R$ {(item.quantity * item.priceAtTime).toFixed(2)}</span>
                        <button onClick={() => removeFromCart(item.productId)} className="text-gray-300 hover:text-red-500 transition-colors">
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="text-center text-gray-400 text-sm py-4 italic">Carrinho vazio.</p>
                )}
              </div>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100 rounded-b-3xl">
              <div className="flex justify-between items-center mb-6">
                <span className="text-gray-500 font-medium">Total</span>
                <span className="text-2xl font-black text-indigo-600">R$ {cartTotal.toFixed(2)}</span>
              </div>
              <button 
                onClick={finalizeOrder}
                className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-4 rounded-2xl font-bold shadow-lg shadow-indigo-100 transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                <CheckCircle2 size={20} />
                Finalizar Venda
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
           <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider">
                  <th className="px-6 py-4 font-semibold">ID Pedido</th>
                  <th className="px-6 py-4 font-semibold">Data</th>
                  <th className="px-6 py-4 font-semibold">Cliente</th>
                  <th className="px-6 py-4 font-semibold">Total</th>
                  <th className="px-6 py-4 font-semibold">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {orders.length > 0 ? (
                  orders.slice().reverse().map((order) => (
                    <tr key={order.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 font-mono text-sm text-indigo-600 font-bold">#{order.id}</td>
                      <td className="px-6 py-4 text-sm text-gray-600">{new Date(order.createdAt).toLocaleString()}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] font-bold text-gray-500">
                            {getCustomerName(order.customerId).charAt(0)}
                          </div>
                          <span className="text-sm font-medium text-gray-800">{getCustomerName(order.customerId)}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 font-bold text-gray-800">R$ {order.total.toFixed(2)}</td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase px-2 py-1 rounded-md bg-green-100 text-green-700">
                          <CheckCircle2 size={12} />
                          Efetuada
                        </span>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} className="px-6 py-12 text-center text-gray-400 italic">
                      Nenhuma venda registrada ainda.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState, useEffect } from 'react';
