    e.preventDefault();
    setIsSaving(true);

    const productData = {
      name: formData.name,
      price: parseFloat(formData.price),
      stock: parseInt(formData.stock),
      category: formData.category || 'Geral'
    };

    try {
      if (editingProduct) {
        await dbService.update('products', editingProduct.id, productData);
      } else {
        await dbService.add('products', productData);
      }
      setIsModalOpen(false);
      setEditingProduct(null);
      setFormData({ name: '', price: '', stock: '', category: '' });
    } catch (err) {
      alert("Erro ao salvar produto no Firebase.");
    } finally {
      setIsSaving(false);
    }
