import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, CheckCircle2, Search, X, Loader2 } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [productSearch, setProductSearch] = useState('');

  const addToCart = (product: Product) => {
    if (product.stock <= 0) return alert('Produto sem estoque!');
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name }];
    });
  };

  const finalizeOrder = async () => {
    if (!selectedCustomerId || cart.length === 0) return alert('Selecione cliente e adicione itens!');
    setIsProcessing(true);

    try {
      const orderData = {
        customerId: selectedCustomerId,
        items: cart,
        total: cart.reduce((sum, item) => sum + (item.priceAtTime * item.quantity), 0),
        status: 'PAID'
      };

      // 1. Salvar pedido
      await dbService.add('orders', orderData);

      // 2. Atualizar estoque de cada produto
      for (const item of cart) {
        const product = products.find(p => p.id === item.productId);
        if (product) {
          await dbService.update('products', product.id, {
            stock: product.stock - item.quantity
          });
        }
      }

      setCart([]);
      setSelectedCustomerId('');
      setIsCreating(false);
    } catch (err) {
      alert("Erro ao processar venda no Firebase.");
    } finally {
      setIsProcessing(false);
    }
  };

  const getCustomerName = (id: string) => customers.find(c => c.id === id)?.name || 'Cliente';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Vendas</h2>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-semibold flex items-center gap-2">
            <Plus size={20} /> Nova Venda
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white p-4 rounded-2xl border flex items-center gap-3">
              <Search className="text-gray-400" size={20} />
              <input type="text" placeholder="Buscar produto..." value={productSearch} onChange={(e) => setProductSearch(e.target.value)} className="flex-1 outline-none" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(product => (
                <button key={product.id} onClick={() => addToCart(product)} className="bg-white p-4 rounded-2xl border hover:border-indigo-300 text-left">
                  <h4 className="font-bold text-gray-800">{product.name}</h4>
                  <p className="text-indigo-600 font-bold">R$ {product.price.toFixed(2)}</p>
                  <p className="text-xs text-gray-400 mt-2">ESTOQUE: {product.stock}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-3xl border flex flex-col h-fit sticky top-4 shadow-xl">
            <div className="p-6 border-b flex justify-between items-center">
              <h3 className="font-bold flex items-center gap-2"><ShoppingCart size={20} className="text-indigo-600" /> Carrinho</h3>
              <button onClick={() => setIsCreating(false)}><X size={20} /></button>
            </div>
            <div className="p-6 space-y-6">
              <select className="w-full border p-2.5 rounded-xl" value={selectedCustomerId} onChange={(e) => setSelectedCustomerId(e.target.value)}>
                <option value="">Selecionar cliente...</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
              <div className="space-y-3">
                {cart.map(item => (
                  <div key={item.productId} className="flex justify-between text-sm">
                    <span className="font-medium">{item.nameAtTime} x{item.quantity}</span>
                    <span className="font-bold">R$ {(item.quantity * item.priceAtTime).toFixed(2)}</span>
                  </div>
                ))}
              </div>
              <div className="pt-4 border-t flex justify-between items-center">
                <span className="text-gray-500">Total</span>
                <span className="text-2xl font-black text-indigo-600">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
              </div>
              <button onClick={finalizeOrder} disabled={isProcessing} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg hover:bg-indigo-700 transition-all">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={20} />}
                {isProcessing ? 'Gravando no Firebase...' : 'Finalizar Venda'}
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-2xl border overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-xs text-gray-500 uppercase">
              <tr>
                <th className="px-6 py-4">Data</th>
                <th className="px-6 py-4">Cliente</th>
                <th className="px-6 py-4">Total</th>
                <th className="px-6 py-4">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {orders.map(order => (
                <tr key={order.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 text-sm">{new Date((order as any).createdAt?.seconds * 1000 || Date.now()).toLocaleDateString()}</td>
                  <td className="px-6 py-4 font-medium">{getCustomerName(order.customerId)}</td>
                  <td className="px-6 py-4 font-bold">R$ {order.total.toFixed(2)}</td>
                  <td className="px-6 py-4"><span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-bold rounded-lg uppercase">Paga</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default OrdersView;

