import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  onSnapshot,
  query,
  orderBy,
  where,
  serverTimestamp
} from "firebase/firestore";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

export const collections = {
  products: collection(db, "products"),
  customers: collection(db, "customers"),
  orders: collection(db, "orders")
};

// Funções de Banco de Dados Scoped por Usuário (Multi-tenant)
export const dbService = {
  subscribe: (collectionName: keyof typeof collections, userId: string, callback: (data: any[]) => void) => {
    // Regra Crítica: Só retorna dados onde userId é igual ao dono
    const q = query(
      collections[collectionName], 
      where("userId", "==", userId),
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      callback(data);
    });
  },

  add: async (collectionName: keyof typeof collections, userId: string, data: any) => {
    return await addDoc(collections[collectionName], {
      ...data,
      userId, // Associa o dado ao dono único
      createdAt: serverTimestamp()
    });
  },

  update: async (collectionName: keyof typeof collections, id: string, data: any) => {
    // No backend (Firestore Rules), garantiremos que o usuário só edita o que é dele
    const docRef = doc(db, collectionName, id);
    return await updateDoc(docRef, data);
  },

  delete: async (collectionName: keyof typeof collections, id: string) => {
    const docRef = doc(db, collectionName, id);
    return await deleteDoc(docRef);
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  Users, 
  ShoppingCart, 
  Sparkles, 
  Menu,
  X,
  LogOut,
  Loader2
} from 'lucide-react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { Product, Customer, Order, ViewState } from './types';
import DashboardView from './views/DashboardView';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import AIInsightsView from './views/AIInsightsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Monitorar Estado de Autenticação
  useEffect(() => {
    const unsubAuth = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      if (!user) {
        setIsLoading(false);
        setProducts([]);
        setCustomers([]);
        setOrders([]);
      }
    });
    return () => unsubAuth();
  }, []);

  // Sincronização em tempo real isolada por Usuário
  useEffect(() => {
    if (!currentUser) return;

    setIsLoading(true);
    const uid = currentUser.uid;

    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => {
      setOrders(data as Order[]);
      setIsLoading(false);
    });

    return () => {
      unsubProducts();
      unsubCustomers();
      unsubOrders();
    };
  }, [currentUser]);

  const handleLogout = () => {
    if (confirm("Deseja realmente sair?")) {
      signOut(auth);
    }
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const navItems = [
    { id: 'DASHBOARD', label: 'Painel', icon: <LayoutDashboard size={20} /> },
    { id: 'PRODUCTS', label: 'Produtos', icon: <Package size={20} /> },
    { id: 'CUSTOMERS', label: 'Clientes', icon: <Users size={20} /> },
    { id: 'ORDERS', label: 'Vendas', icon: <ShoppingCart size={20} /> },
    { id: 'AI_INSIGHTS', label: 'AI Insights', icon: <Sparkles size={20} /> },
  ];

  if (isLoading && currentUser) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 text-indigo-600">
        <Loader2 className="animate-spin mb-4" size={48} />
        <p className="font-semibold animate-pulse">Carregando seus dados exclusivos...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <LoginView />;
  }

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={toggleSidebar} />
      )}

      <aside className={`
        fixed lg:static inset-y-0 left-0 z-50 w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="flex flex-col h-full">
          <div className="p-6 flex items-center justify-between">
            <h1 className="text-2xl font-bold text-indigo-600 tracking-tight flex items-center gap-2">
              <ShoppingCart className="text-indigo-600" />
              VendaPro
            </h1>
            <button onClick={toggleSidebar} className="lg:hidden text-gray-500"><X size={24} /></button>
          </div>

          <nav className="flex-1 px-4 space-y-2 overflow-y-auto">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }}
                className={`
                  w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200
                  ${view === item.id 
                    ? 'bg-indigo-50 text-indigo-600 font-semibold shadow-sm' 
                    : 'text-gray-600 hover:bg-gray-50'}
                `}
              >
                {item.icon}
                {item.label}
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-gray-100">
            <div className="bg-gray-50 rounded-2xl p-4 border border-gray-100">
              <p className="text-[10px] text-gray-400 uppercase font-bold mb-2">Conta Ativa</p>
              <p className="text-xs font-semibold text-gray-700 truncate mb-3">{currentUser.email}</p>
              <button 
                onClick={handleLogout}
                className="w-full flex items-center justify-center gap-2 py-2 text-xs font-bold text-red-500 bg-white border border-red-100 rounded-lg hover:bg-red-50 transition-colors"
              >
                <LogOut size={14} /> Sair do App
              </button>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 shrink-0">
          <button onClick={toggleSidebar} className="lg:hidden p-2 text-gray-600"><Menu size={24} /></button>
          <div className="flex-1 flex justify-end items-center gap-4">
            <span className="text-xs font-bold text-gray-400 hidden sm:block">ID: {currentUser.uid.slice(0, 8)}</span>
            <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold border-2 border-white shadow-sm">
              {currentUser.email?.charAt(0).toUpperCase()}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="animate-fade-in">
            {view === 'DASHBOARD' && <DashboardView orders={orders} products={products} />}
            {view === 'PRODUCTS' && <ProductsView products={products} userId={currentUser.uid} />}
            {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={currentUser.uid} />}
            {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={currentUser.uid} />}
