import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, CheckCircle2, Search, X, Loader2 } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [productSearch, setProductSearch] = useState('');

  const addToCart = (product: Product) => {
    if (product.stock <= 0) return alert('Produto sem estoque!');
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev;
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name }];
    });
  };

  const finalizeOrder = async () => {
    if (!selectedCustomerId || cart.length === 0) return alert('Selecione cliente e adicione itens!');
    setIsProcessing(true);

    try {
      const orderData = {
        customerId: selectedCustomerId,
        items: cart,
        total: cart.reduce((sum, item) => sum + (item.priceAtTime * item.quantity), 0),
        status: 'PAID'
      };

      // 1. Salvar pedido com userId
      await dbService.add('orders', userId, orderData);

      // 2. Atualizar estoque (FireStore Rules protegerá o acesso via ID do documento)
      for (const item of cart) {
        const product = products.find(p => p.id === item.productId);
        if (product) {
          await dbService.update('products', product.id, {
            stock: product.stock - item.quantity
          });
        }
      }

      setCart([]);
      setSelectedCustomerId('');
      setIsCreating(false);
    } catch (err) {
      alert("Erro ao processar venda no Firebase.");
    } finally {
      setIsProcessing(false);
    }
  };

  const getCustomerName = (id: string) => customers.find(c => c.id === id)?.name || 'Cliente';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Vendas</h2>
          <p className="text-sm text-gray-500 font-medium">Movimentação privada da sua conta.</p>
        </div>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black flex items-center gap-2 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">
            <Plus size={20} /> Nova Venda
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white p-5 rounded-2xl border border-gray-100 flex items-center gap-4 shadow-sm">
              <Search className="text-gray-400" size={24} />
              <input type="text" placeholder="Qual item deseja vender hoje?" value={productSearch} onChange={(e) => setProductSearch(e.target.value)} className="flex-1 outline-none font-medium text-gray-700" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(product => (
                <button key={product.id} onClick={() => addToCart(product)} className="bg-white p-5 rounded-[1.5rem] border border-gray-100 hover:border-indigo-500 hover:bg-indigo-50/10 transition-all text-left group shadow-sm">
                  <h4 className="font-black text-gray-800 text-lg group-hover:text-indigo-600 transition-colors">{product.name}</h4>
                  <p className="text-indigo-600 font-black text-xl mt-1">R$ {product.price.toFixed(2)}</p>
                  <div className="mt-4 pt-4 border-t border-gray-50 flex justify-between items-center">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Estoque Atual: {product.stock}</span>
                    <div className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg group-hover:bg-indigo-600 group-hover:text-white transition-all"><Plus size={16} /></div>
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2rem] border border-gray-100 flex flex-col h-fit sticky top-4 shadow-2xl">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50 rounded-t-[2rem]">
              <h3 className="font-black flex items-center gap-3 text-gray-800">
                <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                  <ShoppingCart size={20} />
                </div>
                Checkout
              </h3>
              <button onClick={() => setIsCreating(false)} className="p-2 text-gray-400 hover:bg-gray-100 rounded-xl transition-all"><X size={20} /></button>
            </div>
            <div className="p-6 space-y-6">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Cliente Vinculado</label>
                <select className="w-full bg-gray-50 border border-gray-100 px-4 py-3 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-semibold text-gray-700" value={selectedCustomerId} onChange={(e) => setSelectedCustomerId(e.target.value)}>
                  <option value="">Selecione quem está comprando...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div className="space-y-4 max-h-[30vh] overflow-y-auto pr-2">
                {cart.length > 0 ? cart.map(item => (
                  <div key={item.productId} className="flex justify-between items-center animate-fade-in group">
                    <div className="flex-1">
                      <p className="text-sm font-black text-gray-800">{item.nameAtTime}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.quantity} unidades x R$ {item.priceAtTime.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="font-black text-indigo-600">R$ {(item.quantity * item.priceAtTime).toFixed(2)}</span>
                      <button onClick={() => setCart(cart.filter(i => i.productId !== item.productId))} className="text-gray-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><Trash2 size={14} /></button>
                    </div>
                  </div>
                )) : <p className="text-center text-gray-400 text-sm font-medium italic py-4">O carrinho está pronto para itens...</p>}
              </div>
              <div className="pt-6 border-t border-gray-100 flex justify-between items-end">
                <div>
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total da Venda</span>
                  <div className="text-3xl font-black text-indigo-600 tracking-tighter">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</div>
                </div>
              </div>
              <button onClick={finalizeOrder} disabled={isProcessing} className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50 mt-4">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24} />}
                {isProcessing ? 'Sincronizando Firebase...' : 'Efetivar Venda'}
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[1.5rem] border border-gray-100 overflow-hidden shadow-sm">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-[10px] text-gray-400 font-black uppercase tracking-widest">
              <tr>
                <th className="px-6 py-5">Data & Hora</th>
                <th className="px-6 py-5">Cliente</th>
                <th className="px-6 py-5">Total Bruto</th>
                <th className="px-6 py-5">Status Cloud</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {orders.map(order => (
                <tr key={order.id} className="hover:bg-indigo-50/10 transition-colors group">
                  <td className="px-6 py-4 text-xs font-bold text-gray-500">{new Date((order as any).createdAt?.seconds * 1000 || Date.now()).toLocaleString()}</td>
                  <td className="px-6 py-4 font-black text-gray-800">{getCustomerName(order.customerId)}</td>
                  <td className="px-6 py-4 font-black text-indigo-600">R$ {order.total.toFixed(2)}</td>
                  <td className="px-6 py-4">
                    <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black rounded-full border border-green-100 shadow-sm uppercase">
                      <CheckCircle2 size={12} />
                      Concluída
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <div className="py-20 text-center text-gray-400 font-bold italic">Nenhuma movimentação registrada na sua conta.</div>}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

