import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  onSnapshot,
  query,
  orderBy,
  where,
  serverTimestamp
} from "firebase/firestore";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

export const collections = {
  products: collection(db, "products"),
  customers: collection(db, "customers"),
  orders: collection(db, "orders"),
  expenses: collection(db, "expenses")
};

export const dbService = {
  subscribe: (collectionName: keyof typeof collections, userId: string, callback: (data: any[]) => void) => {
    const q = query(
      collections[collectionName], 
      where("userId", "==", userId),
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      callback(data);
    });
  },

  add: async (collectionName: keyof typeof collections, userId: string, data: any) => {
    return await addDoc(collections[collectionName], {
      ...data,
      userId,
      createdAt: serverTimestamp()
    });
  },

  update: async (collectionName: keyof typeof collections, id: string, data: any) => {
    const docRef = doc(db, collectionName, id);
    return await updateDoc(docRef, {
      ...data,
      updatedAt: serverTimestamp()
    });
  },

  delete: async (collectionName: keyof typeof collections, id: string) => {
    const docRef = doc(db, collectionName, id);
    return await deleteDoc(docRef);
  }
};

