      setCurrentUser(user);
      if (!user) setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser) return;
    setIsLoading(true);
    const uid = currentUser.uid;

    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => {
      setOrders(data as Order[]);
      setIsLoading(false);
    });

