            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tighter">VendaPro</h1>
          </div>

          <nav className="flex-1 space-y-1.5">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3.5 px-5 py-4 rounded-2xl transition-all font-bold ${view === item.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}>
                {item.icon} {item.label}
