import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, CheckCircle2, Search, X, Loader2, Share2, ReceiptText, Banknote } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [productSearch, setProductSearch] = useState('');

  const finalizeOrder = async () => {
    if (!selectedCustomerId || cart.length === 0) return alert('Selecione cliente e itens!');
    setIsProcessing(true);
    try {
      const orderData = {
        customerId: selectedCustomerId,
        items: cart,
        total: cart.reduce((s, i) => s + (i.priceAtTime * i.quantity), 0),
        status,
        paymentMethod: status === 'PAID' ? paymentMethod : null,
        installments: status === 'PAID' ? installments : null
      };

      await dbService.add('orders', userId, orderData);

      if (status === 'PAID') {
        for (const item of cart) {
          const product = products.find(p => p.id === item.productId);
          if (product && product.type === 'PRODUCT') {
            await dbService.update('products', product.id, { stock: Math.max(0, product.stock - item.quantity) });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
    } catch (err) { alert("Erro ao processar."); } finally { setIsProcessing(false); }
  };

  const shareOrder = (order: Order) => {
    const customer = customers.find(c => c.id === order.customerId);
    const text = `📋 *${order.status === 'QUOTE' ? 'ORÇAMENTO' : 'RESUMO DE VENDA'}*\n\n` +
      `👤 Cliente: ${customer?.name || 'Consumidor'}\n` +
      `💰 Total: R$ ${order.total.toFixed(2)}\n` +
      `💳 Pagamento: ${order.paymentMethod || 'Pendente'}\n` +
      `📦 Itens: ${order.items.map(i => `${i.nameAtTime} (${i.quantity}x)`).join(', ')}`;

    if (navigator.share) navigator.share({ title: 'Resumo Venda', text });
    else { alert("Copiado: " + text); navigator.clipboard.writeText(text); }
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Movimentações</h2>
          <p className="text-slate-500 font-medium">Vendas e Orçamentos registrados.</p>
        </div>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="bg-indigo-600 text-white px-8 py-4 rounded-[1.5rem] font-black flex items-center gap-2 shadow-2xl shadow-indigo-100 active:scale-95 transition-all">
            <Plus size={20} /> Nova Transação
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in pb-20">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-5 rounded-3xl border border-slate-100 flex items-center gap-4 shadow-sm">
               <Search size={24} className="text-slate-300" />
               <input placeholder="Buscar por nome no catálogo..." value={productSearch} onChange={e => setProductSearch(e.target.value)} className="flex-1 bg-transparent outline-none font-bold text-slate-700 placeholder:text-slate-300" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => {
                  setCart(prev => {
                    const ex = prev.find(i => i.productId === p.id);
                    if (ex) return prev.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i);
                    return [...prev, {productId: p.id, quantity: 1, priceAtTime: p.price, nameAtTime: p.name}];
                  });
                }} className="bg-white p-5 rounded-[2rem] border border-slate-100 hover:border-indigo-500 hover:bg-indigo-50/5 text-left transition-all shadow-sm">
                  <h4 className="font-black text-slate-800">{p.name}</h4>
                  <p className="text-indigo-600 font-black text-lg">R$ {p.price.toFixed(2)}</p>
                  <p className="text-[10px] font-black text-slate-400 mt-2 uppercase">{p.type === 'SERVICE' ? 'SERVIÇO' : `ESTOQUE: ${p.stock}`}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl h-fit sticky top-4 flex flex-col">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
               <h3 className="font-black text-xl flex items-center gap-3"><ReceiptText className="text-indigo-600" /> Checkout</h3>
               <button onClick={() => setIsCreating(false)} className="text-slate-300 hover:text-slate-600"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Qual o destino desta operação?</label>
                  <div className="flex p-1 bg-slate-50 rounded-2xl">
                     <button onClick={() => setStatus('PAID')} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${status === 'PAID' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>VENDA PAGA</button>
                     <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${status === 'QUOTE' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>ORÇAMENTO</button>
                  </div>
               </div>

               <select className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl font-bold text-slate-700" value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)}>
                  <option value="">Para quem é o atendimento?</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
               </select>

               {status === 'PAID' && (
                 <div className="space-y-4 pt-4 border-t border-slate-50">
                    <div className="grid grid-cols-2 gap-3">
                       {['PIX', 'CREDIT_CARD', 'CASH'].map(m => (
                         <button key={m} onClick={() => setPaymentMethod(m as any)} className={`py-3 rounded-xl border text-[10px] font-black tracking-widest ${paymentMethod === m ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-400 border-slate-100'}`}>{m}</button>
                       ))}
                    </div>
                    {paymentMethod === 'CREDIT_CARD' && (
                      <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-2xl">
                         <span className="text-[10px] font-black text-slate-400 uppercase flex-1">Parcelas</span>
                         <input type="number" min="1" max="12" value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-16 bg-white border-none rounded-lg text-center font-black" />
                      </div>
                    )}
                 </div>
               )}

               <div className="pt-6 border-t border-slate-100">
                  <div className="flex justify-between items-center mb-4">
                     <span className="text-slate-400 text-xs font-black uppercase">Valor Total</span>
                     <span className="text-3xl font-black text-indigo-600 tracking-tighter">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                  </div>
                  <button disabled={isProcessing} onClick={finalizeOrder} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl hover:bg-indigo-800 transition-all flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50">
                     {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24} />}
                     {status === 'PAID' ? 'CONCLUIR RECEBIMENTO' : 'GERAR PROPOSTA'}
                  </button>
               </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-8 py-5">Identificação</th>
                <th className="px-8 py-5">Cliente</th>
                <th className="px-8 py-5">Total Bruto</th>
                <th className="px-8 py-5">Forma</th>
                <th className="px-8 py-5 text-right">Acões</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {orders.map(o => (
                <tr key={o.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-8 py-5">
                     <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase ${o.status === 'QUOTE' ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}>{o.status}</span>
                  </td>
                  <td className="px-8 py-5 font-bold text-slate-700">{customers.find(c => c.id === o.customerId)?.name || 'Consumidor'}</td>
                  <td className="px-8 py-5 font-black text-slate-900">R$ {o.total.toFixed(2)}</td>
                  <td className="px-8 py-5 text-xs font-black text-slate-400">{o.paymentMethod || 'ORÇAMENTO'}</td>
                  <td className="px-8 py-5 text-right flex justify-end gap-2">
                     <button onClick={() => shareOrder(o)} className="p-2.5 text-slate-400 hover:text-indigo-600 bg-slate-50 rounded-xl"><Share2 size={16}/></button>
                     <button onClick={() => dbService.delete('orders', o.id)} className="p-2.5 text-slate-400 hover:text-rose-500 bg-slate-50 rounded-xl"><Trash2 size={16}/></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <div className="py-24 text-center text-slate-300 italic">Nenhuma movimentação comercial detectada.</div>}
        </div>
      )}
    </div>
  );
};

