                   <button type="button" onClick={() => setFormData({...formData, type: 'PRODUCT'})} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${formData.type === 'PRODUCT' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>PRODUTO</button>
                   <button type="button" onClick={() => setFormData({...formData, type: 'SERVICE'})} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${formData.type === 'SERVICE' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>SERVIÇO</button>
                </div>
                <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300 focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="Nome do item ou serviço" />
                <div className="grid grid-cols-2 gap-4">
                   <input required type="number" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300" placeholder="Preço" />
                   {formData.type === 'PRODUCT' && <input required type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300" placeholder="Estoque" />}
                </div>
                <input value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-5 py-4 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300" placeholder="Categoria (Ex: Eletrônicos)" />
                <button disabled={isSaving} type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all mt-4">
                   {isSaving ? <Loader2 className="animate-spin" /> : 'Confirmar Cadastro'}
                </button>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

