import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  Users, 
  ShoppingCart, 
  Sparkles, 
  Menu,
  X,
  LogOut,
  Loader2,
  WalletMinimal,
  Zap
} from 'lucide-react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { Product, Customer, Order, Expense, ViewState } from './types';
import DashboardView from './views/DashboardView';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const unsubAuth = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      if (!user) setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser) return;
    setIsLoading(true);
    const uid = currentUser.uid;

    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => {
      setOrders(data as Order[]);
      setIsLoading(false);
    });

    return () => {
      unsubProducts();
      unsubCustomers();
      unsubOrders();
      unsubExpenses();
    };
  }, [currentUser]);

  const navItems = [
    { id: 'DASHBOARD', label: 'Painel Geral', icon: <LayoutDashboard size={20} /> },
    { id: 'PRODUCTS', label: 'Catálogo', icon: <Package size={20} /> },
    { id: 'CUSTOMERS', label: 'Meus Clientes', icon: <Users size={20} /> },
    { id: 'ORDERS', label: 'Vendas e Orç.', icon: <ShoppingCart size={20} /> },
    { id: 'EXPENSES', label: 'Gastos', icon: <WalletMinimal size={20} /> },
    { id: 'AI_INSIGHTS', label: 'Inteligência', icon: <Sparkles size={20} /> },
  ];

  if (isLoading && currentUser) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white text-amber-500">
        <Loader2 className="animate-spin mb-4" size={48} />
        <p className="font-extrabold text-slate-800 animate-pulse tracking-tight">Sincronizando Facindemais...</p>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/40 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`fixed lg:static inset-y-0 left-0 z-50 w-72 bg-white border-r border-slate-100 transform transition-transform duration-500 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="flex flex-col h-full p-6">
          <div className="flex items-center gap-3 mb-10 px-2">
            <div className="bg-amber-500 p-2.5 rounded-2xl shadow-lg shadow-amber-200">
              <Zap className="text-white fill-current" size={24} />
            </div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">Facindemais<span className="text-amber-500">.</span></h1>
          </div>

          <nav className="flex-1 space-y-1">
            {navItems.map((item) => (
              <button 
                key={item.id} 
                onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }} 
                className={`w-full flex items-center gap-3.5 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${view === item.id ? 'bg-slate-900 text-white shadow-xl shadow-slate-200' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                {item.icon} {item.label}
              </button>
            ))}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50">
            <div className="bg-slate-50 rounded-2xl p-4 flex items-center gap-3 border border-slate-100">
              <div className="w-10 h-10 rounded-xl bg-amber-500 flex items-center justify-center text-white font-black shadow-sm">{currentUser.email?.charAt(0).toUpperCase()}</div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-black text-slate-900 truncate uppercase tracking-tighter">{currentUser.email?.split('@')[0]}</p>
                <button onClick={() => signOut(auth)} className="text-[10px] font-bold text-slate-400 uppercase hover:text-rose-500 transition-colors">Sair da Conta</button>
              </div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b border-slate-100 flex items-center justify-between px-8 z-30">
          <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2.5 text-slate-600 bg-slate-50 rounded-xl border border-slate-100"><Menu size={20} /></button>
          <div className="flex-1 flex justify-end gap-6 items-center">
            <div className="hidden md:flex flex-col items-end">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hospedagem Ativa</span>
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-sm font-bold text-slate-700">Cloud Vercel</span>
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12">
          {view === 'DASHBOARD' && <DashboardView orders={orders} products={products} expenses={expenses} />}
          {view === 'PRODUCTS' && <ProductsView products={products} userId={currentUser.uid} />}
          {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={currentUser.uid} />}
          {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={currentUser.uid} />}
          {view === 'EXPENSES' && <ExpensesView expenses={expenses} userId={currentUser.uid} />}
          {view === 'AI_INSIGHTS' && <AIInsightsView orders={orders} products={products} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence
} from 'firebase/auth';
import { auth } from '../services/firebase';
import { Zap, Mail, Lock, Loader2, ArrowRight, ShieldCheck, Info } from 'lucide-react';

const LoginView: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      await setPersistence(auth, browserLocalPersistence);
      if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error(err);
      const errorCode = err.code;
      switch (errorCode) {
        case 'auth/user-not-found':
        case 'auth/wrong-password':
        case 'auth/invalid-credential':
          setError('Dados incorretos. Tente novamente.');
          break;
        case 'auth/email-already-in-use':
          setError('Este e-mail já está em uso por outra conta.');
          break;
        case 'auth/weak-password':
          setError('Senha muito curta (mínimo 6 caracteres).');
          break;
        default:
          setError('Erro de conexão com o servidor.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#F1F5F9] p-4 relative overflow-hidden">
      {/* Decoração Visual */}
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-amber-200/40 rounded-full blur-[100px]"></div>
      <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-slate-300/30 rounded-full blur-[100px]"></div>

      <div className="w-full max-w-[420px] relative z-10 animate-fade-in">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-20 h-20 rounded-[2rem] bg-slate-900 text-white shadow-2xl shadow-slate-300 mb-6 rotate-3">
            <Zap size={40} className="fill-amber-400 text-amber-400" />
          </div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic">Facindemais<span className="text-amber-500">.</span></h1>
          <p className="text-slate-500 font-bold text-sm mt-2 tracking-tight">O app que faz sua gestão ficar fácil.</p>
        </div>

        <div className="bg-white p-10 rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.08)] border border-white/50 backdrop-blur-sm">
          <div className="flex p-1.5 bg-slate-100 rounded-2xl mb-10">
            <button 
              onClick={() => { setIsRegistering(false); setError(''); }}
              className={`flex-1 py-3.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${!isRegistering ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}
            >
              Entrar
            </button>
            <button 
              onClick={() => { setIsRegistering(true); setError(''); }}
              className={`flex-1 py-3.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${isRegistering ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}
            >
              Cadastrar
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" size={18} />
                <input 
                  required
                  type="email" 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-12 pr-4 py-4.5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-bold text-slate-700"
                  placeholder="exemplo@gmail.com"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" size={18} />
                <input 
                  required
                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-12 pr-4 py-4.5 bg-slate-50 border-none rounded-2xl outline-none focus:ring-4 focus:ring-amber-500/10 transition-all font-bold text-slate-700"
                  placeholder="••••••••"
                />
              </div>
            </div>

            {error && (
              <div className="p-4 bg-rose-50 text-rose-600 text-[11px] font-black rounded-xl border border-rose-100 flex items-center gap-3">
                <Info size={16} />
                <span>{error}</span>
              </div>
            )}

            <button 
              disabled={isLoading}
              type="submit"
              className="w-full bg-slate-900 hover:bg-slate-800 text-white py-5 rounded-[1.5rem] font-black shadow-2xl shadow-slate-200 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50 mt-4"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <ArrowRight size={20} />}
              {isLoading ? 'Autenticando...' : (isRegistering ? 'CRIAR MINHA CONTA' : 'ACESSAR AGORA')}
            </button>
          </form>
        </div>

        <p className="mt-12 text-center text-slate-400 text-[9px] px-12 leading-loose font-bold uppercase tracking-[0.2em]">
          Ambiente Seguro & Hospedagem Facindemais Cloud
        </p>
      </div>
    </div>
  );
};

export default LoginView;

import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, CheckCircle2, Search, X, Loader2, Share2, ReceiptText, Zap } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [productSearch, setProductSearch] = useState('');

  const finalizeOrder = async () => {
    if (!selectedCustomerId || cart.length === 0) return alert('Selecione cliente e itens!');
    setIsProcessing(true);
    try {
      const total = cart.reduce((s, i) => s + (i.priceAtTime * i.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId,
        items: cart,
        total,
        status,
        paymentMethod: status === 'PAID' ? paymentMethod : null,
        installments: status === 'PAID' ? installments : null
      };

      await dbService.add('orders', userId, orderData);

      if (status === 'PAID') {
        for (const item of cart) {
          const product = products.find(p => p.id === item.productId);
          if (product && product.type === 'PRODUCT') {
            await dbService.update('products', product.id, { stock: Math.max(0, product.stock - item.quantity) });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
    } catch (err) { alert("Erro ao processar."); } finally { setIsProcessing(false); }
  };

  const shareOrder = (order: Order) => {
    const customer = customers.find(c => c.id === order.customerId);
    const text = `📋 *${order.status === 'QUOTE' ? 'ORÇAMENTO' : 'RECIBO DE VENDA'}*\n\n` +
      `👤 Cliente: ${customer?.name || 'Cliente Geral'}\n` +
      `💰 Valor Total: R$ ${order.total.toFixed(2)}\n` +
      `💳 Meio: ${order.paymentMethod || 'A combinar'}\n` +
      `📦 Itens: ${order.items.map(i => `${i.nameAtTime} (${i.quantity}x)`).join(', ')}\n\n` +
      `Facindemais Cloud ⚡`;

    if (navigator.share) navigator.share({ title: 'Comprovante', text });
    else { alert("Copiado com sucesso!"); navigator.clipboard.writeText(text); }
  };

  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter italic">Vendas<span className="text-amber-500">.</span></h2>
          <p className="text-slate-500 font-bold mt-1 text-lg">Gerencie pedidos e orçamentos rápidos.</p>
        </div>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="bg-slate-900 text-white px-10 py-5 rounded-[2rem] font-black flex items-center gap-3 shadow-2xl shadow-slate-200 hover:bg-slate-800 transition-all active:scale-95">
            <Plus size={24} className="text-amber-400" /> NOVA OPERAÇÃO
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 animate-fade-in">
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex items-center gap-5 shadow-sm focus-within:ring-4 focus-within:ring-amber-500/5 transition-all">
               <Search size={24} className="text-slate-300" />
               <input placeholder="Busque por nome, código ou marca..." value={productSearch} onChange={e => setProductSearch(e.target.value)} className="flex-1 bg-transparent outline-none font-bold text-slate-700 placeholder:text-slate-300 text-lg" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => {
                  setCart(prev => {
                    const ex = prev.find(i => i.productId === p.id);
                    if (ex) return prev.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i);
                    return [...prev, {productId: p.id, quantity: 1, priceAtTime: p.price, nameAtTime: p.name}];
                  });
                }} className="bg-white p-8 rounded-[3rem] border border-slate-100 hover:border-amber-400 hover:bg-amber-50/20 text-left transition-all shadow-sm group relative overflow-hidden">
                  <div className="absolute top-4 right-4 bg-slate-100 px-3 py-1 rounded-lg text-[9px] font-black text-slate-400 group-hover:bg-amber-100 group-hover:text-amber-600 transition-colors uppercase">{p.type}</div>
                  <h4 className="font-black text-slate-800 text-xl mb-1">{p.name}</h4>
                  <p className="text-amber-600 font-black text-2xl tracking-tight">R$ {p.price.toFixed(2)}</p>
                  <p className="text-[10px] font-black text-slate-400 mt-4 uppercase tracking-widest">{p.type === 'SERVICE' ? 'Disponibilidade Total' : `Em Estoque: ${p.stock}`}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[3.5rem] border border-slate-100 shadow-2xl h-fit sticky top-6 flex flex-col overflow-hidden">
            <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
               <h3 className="font-black text-2xl flex items-center gap-3 italic"><ReceiptText className="text-amber-500" /> Checkout</h3>
               <button onClick={() => setIsCreating(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-2xl text-slate-300 hover:text-rose-500 transition-colors shadow-sm"><X size={24} /></button>
            </div>
            <div className="p-10 space-y-8">
               <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">Tipo da Transação</label>
                  <div className="flex p-1.5 bg-slate-100 rounded-2xl">
                     <button onClick={() => setStatus('PAID')} className={`flex-1 py-4 rounded-xl text-xs font-black transition-all ${status === 'PAID' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>VENDA PAGA</button>
                     <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-4 rounded-xl text-xs font-black transition-all ${status === 'QUOTE' ? 'bg-white text-amber-500 shadow-sm' : 'text-slate-400'}`}>ORÇAMENTO</button>
                  </div>
               </div>

               <div className="space-y-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">Cliente</label>
                  <select className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold text-slate-700 appearance-none shadow-inner" value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)}>
                    <option value="">Selecione o cliente...</option>
                    {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
               </div>

               {status === 'PAID' && (
                 <div className="space-y-6 pt-6 border-t border-slate-50">
                    <div className="grid grid-cols-1 gap-3">
                       {['PIX', 'CREDIT_CARD', 'CASH'].map(m => (
                         <button key={m} onClick={() => setPaymentMethod(m as any)} className={`py-4 rounded-2xl border text-[11px] font-black tracking-widest transition-all ${paymentMethod === m ? 'bg-slate-900 text-white border-slate-900 shadow-xl' : 'bg-white text-slate-400 border-slate-100 hover:bg-slate-50'}`}>
                           {m === 'PIX' ? '⚡ PIX' : m === 'CREDIT_CARD' ? '💳 CARTÃO CRÉDITO' : '💵 DINHEIRO'}
                         </button>
                       ))}
                    </div>
                 </div>
               )}

               <div className="pt-10 border-t border-slate-100">
                  <div className="flex justify-between items-end mb-8">
                     <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Total à pagar</span>
                     <span className="text-4xl font-black text-slate-900 tracking-tighter italic">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                  </div>
                  <button disabled={isProcessing} onClick={finalizeOrder} className="w-full bg-amber-500 text-white py-6 rounded-[2rem] font-black shadow-2xl shadow-amber-200 hover:bg-amber-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50 text-lg">
                     {isProcessing ? <Loader2 className="animate-spin" /> : <Zap size={24} className="fill-current" />}
                     {status === 'PAID' ? 'FINALIZAR AGORA' : 'GERAR PROPOSTA'}
                  </button>
               </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[3rem] border border-slate-100 overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50">
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Cliente Responsável</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Valor Bruto</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest text-right">Ações Rápidas</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {orders.map(o => (
                  <tr key={o.id} className="hover:bg-slate-50/80 transition-colors group">
                    <td className="px-10 py-7">
                       <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest ${o.status === 'QUOTE' ? 'bg-amber-50 text-amber-600 border border-amber-100' : 'bg-emerald-50 text-emerald-600 border border-emerald-100'}`}>{o.status}</span>
                    </td>
                    <td className="px-10 py-7 font-extrabold text-slate-700 text-lg">{customers.find(c => c.id === o.customerId)?.name || 'Cliente Geral'}</td>
                    <td className="px-10 py-7 font-black text-slate-900 text-xl tracking-tight">R$ {o.total.toFixed(2)}</td>
                    <td className="px-10 py-7 text-right">
                       <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-all transform translate-x-4 group-hover:translate-x-0">
                         <button onClick={() => shareOrder(o)} className="p-3.5 text-slate-500 hover:text-amber-500 bg-white border border-slate-100 rounded-2xl shadow-sm transition-all"><Share2 size={18}/></button>
                         <button onClick={() => dbService.delete('orders', o.id)} className="p-3.5 text-slate-500 hover:text-rose-500 bg-white border border-slate-100 rounded-2xl shadow-sm transition-all"><Trash2 size={18}/></button>
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {orders.length === 0 && (
            <div className="py-32 text-center flex flex-col items-center">
               <div className="w-24 h-24 bg-slate-50 rounded-[2.5rem] flex items-center justify-center text-slate-200 mb-6">
                 <ShoppingCart size={40} />
               </div>
               <p className="text-slate-400 font-bold text-lg">Nenhuma movimentação comercial hoje.</p>
               <button onClick={() => setIsCreating(true)} className="mt-6 text-amber-500 font-black uppercase text-xs tracking-widest hover:underline">Iniciar primeira venda</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  Users, 
  ShoppingCart, 
  Sparkles, 
  Menu,
  X,
  Loader2,
  WalletMinimal,
  Zap
} from 'lucide-react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { Product, Customer, Order, Expense, ViewState } from './types';
import DashboardView from './views/DashboardView';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const unsubAuth = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      if (!user) setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser) return;
    setIsLoading(true);
    const uid = currentUser.uid;

    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => {
      setOrders(data as Order[]);
      setIsLoading(false);
    });

    return () => {
      unsubProducts();
      unsubCustomers();
      unsubOrders();
      unsubExpenses();
    };
  }, [currentUser]);

  const navItems = [
    { id: 'DASHBOARD', label: 'Painel Geral', icon: <LayoutDashboard size={20} /> },
    { id: 'PRODUCTS', label: 'Catálogo', icon: <Package size={20} /> },
    { id: 'CUSTOMERS', label: 'Meus Clientes', icon: <Users size={20} /> },
    { id: 'ORDERS', label: 'Vendas e Orç.', icon: <ShoppingCart size={20} /> },
    { id: 'EXPENSES', label: 'Gastos/Custos', icon: <WalletMinimal size={20} /> },
    { id: 'AI_INSIGHTS', label: 'Inteligência AI', icon: <Sparkles size={20} /> },
  ];

  if (isLoading && currentUser) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white text-amber-500">
        <div className="relative">
          <Loader2 className="animate-spin mb-4" size={56} />
          <Zap className="absolute top-4 left-4 text-amber-500 animate-pulse" size={24} />
        </div>
        <p className="font-black text-slate-800 animate-pulse tracking-tighter text-xl">Facindemais Pro</p>
        <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-2">Carregando sua operação...</p>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {isSidebarOpen && <div className="fixed inset-0 bg-slate-900/40 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`fixed lg:static inset-y-0 left-0 z-50 w-72 bg-white border-r border-slate-100 transform transition-transform duration-500 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="flex flex-col h-full p-6">
          <div className="flex items-center gap-3 mb-10 px-2">
            <div className="bg-amber-500 p-2.5 rounded-2xl shadow-lg shadow-amber-200">
              <Zap className="text-white fill-current" size={24} />
            </div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">Facindemais<span className="text-amber-500">.</span></h1>
          </div>

          <nav className="flex-1 space-y-1">
            {navItems.map((item) => (
              <button 
                key={item.id} 
                onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }} 
                className={`w-full flex items-center gap-3.5 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${view === item.id ? 'bg-slate-900 text-white shadow-xl shadow-slate-200 scale-[1.02]' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                {item.icon} {item.label}
              </button>
            ))}
          </nav>

          <div className="mt-auto pt-6 border-t border-slate-50">
            <div className="bg-slate-50 rounded-2xl p-4 flex items-center gap-3 border border-slate-100">
              <div className="w-10 h-10 rounded-xl bg-amber-500 flex items-center justify-center text-white font-black shadow-sm">{currentUser.email?.charAt(0).toUpperCase()}</div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-black text-slate-900 truncate uppercase tracking-tighter">{currentUser.email?.split('@')[0]}</p>
                <button onClick={() => signOut(auth)} className="text-[10px] font-bold text-slate-400 uppercase hover:text-rose-500 transition-colors">Sair da Conta</button>
              </div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b border-slate-100 flex items-center justify-between px-8 z-30">
          <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2.5 text-slate-600 bg-slate-50 rounded-xl border border-slate-100"><Menu size={20} /></button>
          <div className="flex-1 flex justify-end gap-6 items-center">
            <div className="hidden md:flex flex-col items-end">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hospedagem Ativa</span>
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-sm font-bold text-slate-700 uppercase tracking-tighter">Cloud Facindemais</span>
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12">
          {view === 'DASHBOARD' && <DashboardView orders={orders} products={products} expenses={expenses} />}
          {view === 'PRODUCTS' && <ProductsView products={products} userId={currentUser.uid} />}
          {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={currentUser.uid} />}
          {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={currentUser.uid} />}
          {view === 'EXPENSES' && <ExpensesView expenses={expenses} userId={currentUser.uid} />}
          {view === 'AI_INSIGHTS' && <AIInsightsView orders={orders} products={products} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Plus, Edit3, Trash2, Package, Search, X, Hammer, Loader2 } from 'lucide-react';
import { Product } from '../types';
import { dbService } from '../services/firebase';

interface ProductsViewProps {
  products: Product[];
  userId: string;
}

const ProductsView: React.FC<ProductsViewProps> = ({ products, userId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ name: '', price: '', stock: '', category: '', type: 'PRODUCT' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const data = {
        name: formData.name,
        price: parseFloat(formData.price),
        stock: formData.type === 'SERVICE' ? 999999 : parseInt(formData.stock),
        category: formData.category || 'Geral',
        type: formData.type
      };
      if (editingProduct) await dbService.update('products', editingProduct.id, data);
      else await dbService.add('products', userId, data);
      setIsModalOpen(false);
      setEditingProduct(null);
      setFormData({ name: '', price: '', stock: '', category: '', type: 'PRODUCT' });
    } catch (err) { alert("Erro ao salvar."); } finally { setIsSaving(false); }
  };

  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter italic">Catálogo<span className="text-amber-500">.</span></h2>
          <p className="text-slate-500 font-bold mt-1 text-lg">Controle seus itens físicos e sua mão de obra.</p>
        </div>
        <button onClick={() => { setEditingProduct(null); setIsModalOpen(true); }} className="bg-slate-900 text-white px-8 py-4 rounded-[2rem] font-black flex items-center gap-3 shadow-xl hover:bg-slate-800 transition-all">
          <Plus size={24} className="text-amber-500" /> NOVO CADASTRO
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {products.map(p => (
          <div key={p.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm relative group overflow-hidden transition-all hover:shadow-xl hover:-translate-y-1">
            <div className="flex justify-between items-start mb-6">
              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${p.type === 'SERVICE' ? 'bg-amber-50 text-amber-600' : 'bg-slate-50 text-slate-600'}`}>
                {p.type === 'SERVICE' ? <Hammer size={24} /> : <Package size={24} />}
              </div>
              <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                 <button onClick={() => { setEditingProduct(p); setFormData({name:p.name, price:p.price.toString(), stock:p.stock.toString(), category:p.category, type:p.type}); setIsModalOpen(true); }} className="p-3 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-colors"><Edit3 size={18}/></button>
                 <button onClick={() => { if(confirm('Remover item?')) dbService.delete('products', p.id) }} className="p-3 text-rose-600 bg-rose-50 rounded-xl hover:bg-rose-100 transition-colors"><Trash2 size={18}/></button>
              </div>
            </div>

            <h4 className="font-black text-slate-900 text-xl truncate mb-1">{p.name}</h4>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">{p.category || 'SEM CATEGORIA'}</p>

            <div className="flex justify-between items-end border-t border-slate-50 pt-6">
               <div>
                 <span className="text-[10px] font-black text-slate-400 uppercase block mb-1 tracking-widest">Preço</span>
                 <span className="text-2xl font-black text-slate-900 tracking-tighter italic">R$ {p.price.toFixed(2)}</span>
               </div>
               <div className="text-right">
                 <span className="text-[10px] font-black text-slate-400 uppercase block mb-1 tracking-widest">Estoque</span>
                 <span className={`text-xs font-black px-4 py-2 rounded-xl inline-block ${p.type === 'SERVICE' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : (p.stock < 5 ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-slate-100 text-slate-600')}`}>
                   {p.type === 'SERVICE' ? 'ILIMITADO' : `${p.stock} UN`}
                 </span>
               </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[3.5rem] w-full max-w-md shadow-2xl p-10 animate-fade-in">
             <div className="flex justify-between items-center mb-10">
                <h3 className="text-2xl font-black text-slate-900 italic">{editingProduct ? 'Editar' : 'Novo'} Registro</h3>
                <button onClick={() => setIsModalOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-2xl text-slate-400"><X size={24} /></button>
             </div>
             <form onSubmit={handleSave} className="space-y-5">
                <div className="flex p-1.5 bg-slate-100 rounded-[1.5rem] mb-6 shadow-inner">
                   <button type="button" onClick={() => setFormData({...formData, type: 'PRODUCT'})} className={`flex-1 py-4 rounded-xl text-[10px] font-black tracking-widest transition-all ${formData.type === 'PRODUCT' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>PRODUTO FÍSICO</button>
                   <button type="button" onClick={() => setFormData({...formData, type: 'SERVICE'})} className={`flex-1 py-4 rounded-xl text-[10px] font-black tracking-widest transition-all ${formData.type === 'SERVICE' ? 'bg-white text-amber-500 shadow-sm' : 'text-slate-400'}`}>SERVIÇO / HORA</button>
                </div>

                <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300 focus:ring-4 focus:ring-amber-500/10 transition-all" placeholder="Nome do item ou serviço" />

                <div className="grid grid-cols-2 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Preço R$</label>
                      <input required type="number" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold" />
                   </div>
                   {formData.type === 'PRODUCT' && (
                     <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Estoque</label>
                        <input required type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold" />
                     </div>
                   )}
                </div>

                <input value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300" placeholder="Categoria (Ex: Eletrônicos, Mão de Obra)" />

                <button disabled={isSaving} type="submit" className="w-full bg-slate-900 text-white py-6 rounded-[2rem] font-black shadow-2xl shadow-slate-200 hover:bg-slate-800 transition-all mt-6 flex items-center justify-center gap-3">
                   {isSaving ? <Loader2 className="animate-spin" /> : <Zap size={20} className="text-amber-400" />}
                   CONFIRMAR CADASTRO
                </button>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductsView;

