                 <span className={`text-xs font-black px-4 py-2 rounded-xl inline-block ${p.type === 'SERVICE' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : (p.stock < 5 ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-slate-100 text-slate-600')}`}>
