import React, { useState } from 'react';
import { Plus, Search, Mail, Phone, MapPin, Edit2, Trash2, X, UserCheck, Loader2 } from 'lucide-react';
import { Customer } from '../types';
import { dbService } from '../services/firebase';

interface CustomersViewProps {
  customers: Customer[];
  userId: string;
}

const CustomersView: React.FC<CustomersViewProps> = ({ customers, userId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', address: '' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (editingCustomer) {
        await dbService.update('customers', editingCustomer.id, formData);
      } else {
        await dbService.add('customers', userId, formData);
      }
      setIsModalOpen(false);
      setEditingCustomer(null);
      setFormData({ name: '', email: '', phone: '', address: '' });
    } catch (err) {
      alert("Erro ao salvar cliente.");
    } finally {
      setIsSaving(false);
