        <button onClick={() => { setEditingCustomer(null); setIsModalOpen(true); }} className="bg-slate-900 text-white px-8 py-4 rounded-[2rem] font-black flex items-center gap-3 shadow-xl hover:bg-slate-800 transition-all active:scale-95">
