        <Search className="text-slate-300" size={24} />
        <input 
          type="text" 
          placeholder="Pesquisar por nome ou e-mail..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-bold text-slate-700 placeholder:text-slate-300 text-lg" 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {customers.filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase())).map(customer => (
          <div key={customer.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 hover:shadow-xl hover:border-amber-100 transition-all relative group overflow-hidden">
            <div className="absolute top-6 right-6 flex gap-2 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0">
              <button onClick={() => openEdit(customer)} className="p-3 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-colors shadow-sm"><Edit2 size={18} /></button>
              <button onClick={() => deleteCustomer(customer.id)} className="p-3 text-rose-600 bg-rose-50 rounded-xl hover:bg-rose-100 transition-colors shadow-sm"><Trash2 size={18} /></button>
            </div>
            <div className="w-16 h-16 rounded-[1.5rem] bg-slate-50 flex items-center justify-center text-amber-500 font-black text-2xl mb-6 shadow-inner border border-slate-100">
              {customer.name.charAt(0).toUpperCase()}
