            <div className="space-y-3">
              <div className="flex items-center gap-3 bg-slate-50/50 p-3 rounded-2xl truncate text-sm font-bold text-slate-500 border border-slate-50">
                <Mail size={16} className="text-slate-300" /> {customer.email || 'Não informado'}
              </div>
              <div className="flex items-center gap-3 bg-slate-50/50 p-3 rounded-2xl text-sm font-bold text-slate-500 border border-slate-50">
