                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefone / WhatsApp</label>
                  <input type="tel" value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl font-bold placeholder:text-slate-300 focus:ring-4 focus:ring-amber-500/10 transition-all" placeholder="(00) 00000-0000" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Endereço (Opcional)</label>
                <textarea value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-2xl h-24 resize-none font-bold placeholder:text-slate-300 focus:ring-4 focus:ring-amber-500/10 transition-all" placeholder="Rua, Número, Bairro..." />
              </div>

              <button disabled={isSaving} type="submit" className="w-full bg-slate-900 text-white py-6 rounded-[2rem] font-black shadow-2xl shadow-slate-200 hover:bg-slate-800 transition-all flex items-center justify-center gap-3 mt-6">
                {isSaving ? <Loader2 className="animate-spin" size={20} /> : <UserCheck size={20} className="text-amber-500" />}
                {isSaving ? 'Sincronizando...' : 'CONFIRMAR CADASTRO'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomersView;

