        if (!userProfile) {
          const storedRefCode = sessionStorage.getItem('referredByCode') || undefined;
          userProfile = await dbService.createUserProfile(user.uid, user.email || '', storedRefCode);
        }
        setProfile(userProfile as UserProfile);
        setCurrentUser(user);
      } else {
        setCurrentUser(null);
        setProfile(null);
      }
      setIsLoading(false);
    });
    return () => unsubAuth();
