import { initializeApp } from "firebase/app";
import { 
  getFirestore, collection, addDoc, updateDoc, deleteDoc, doc, onSnapshot,
  query, orderBy, where, serverTimestamp, getDoc, setDoc, Timestamp, getDocs, limit
} from "firebase/firestore";
import { getAuth } from "firebase/auth";

const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

export const collections = {
  products: collection(db, "products"),
  customers: collection(db, "customers"),
  orders: collection(db, "orders"),
  expenses: collection(db, "expenses"),
  users: collection(db, "users")
};

export const dbService = {
  getUserProfile: async (uid: string) => {
    const docRef = doc(db, "users", uid);
    const docSnap = await getDoc(docRef);
    return docSnap.exists() ? docSnap.data() : null;
  },

  createUserProfile: async (uid: string, email: string, referredByCode?: string) => {
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const referralCode = uid.substring(0, 6).toUpperCase();

    let referredByUid = "";
    if (referredByCode) {
      const q = query(collections.users, where("referralCode", "==", referredByCode), limit(1));
      const snap = await getDocs(q);
      if (!snap.empty) {
        referredByUid = snap.docs[0].id;
        const indicatorRef = doc(db, "users", referredByUid);
        const indicatorData = snap.docs[0].data();
        await updateDoc(indicatorRef, { 
          referralCount: (indicatorData.referralCount || 0) + 1 
        });
      }
    }

    const profile = {
      uid,
      email,
      role: 'user',
      status: 'trial',
      plan: 'pro',
      expiresAt: Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode,
      referredBy: referredByUid,
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  getAllUsers: (callback: (data: any[]) => void) => {
    return onSnapshot(query(collections.users, orderBy("createdAt", "desc")), (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  },

  deleteUser: async (uid: string) => {
    // Nota: Em um sistema real, você deletaria também os dados vinculados (produtos, vendas etc)
    return await deleteDoc(doc(db, "users", uid));
  },

  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    const q = query(collection(db, collectionName), where("userId", "==", userId), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  add: async (collectionName: string, userId: string, data: any) => {
    return await addDoc(collection(db, collectionName), { ...data, userId, createdAt: serverTimestamp() });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  }
};

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { UserProfile } from '../types';
import { Search, ShieldCheck, UserMinus, Calendar, Zap, Loader2, RefreshCw, Trash2, ShieldAlert, CheckCircle2 } from 'lucide-react';
import { Timestamp } from 'firebase/firestore';

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const unsub = dbService.getAllUsers((data) => {
      setUsers(data as UserProfile[]);
      setIsLoading(false);
    });
    return () => unsub();
  }, []);

  const toggleStatus = async (user: UserProfile) => {
    const newStatus = user.status === 'blocked' ? 'active' : 'blocked';
    const action = user.status === 'blocked' ? 'DESBLOQUEAR' : 'BLOQUEAR';
    if(confirm(`Tem certeza que deseja ${action} o escritório ${user.email}?`)) {
      await dbService.updateUser(user.uid, { status: newStatus });
    }
  };

  const extendSubscription = async (user: UserProfile) => {
    const current = user.expiresAt?.toDate() || new Date();
    // Se já venceu, começa a contar de hoje. Se não, soma ao que falta.
    const baseDate = current < new Date() ? new Date() : current;
    const newDate = new Date(baseDate);
    newDate.setMonth(newDate.getMonth() + 1); 

    if(confirm(`Confirmar recebimento de pagamento e prorrogar +30 dias para ${user.email}?`)) {
      await dbService.updateUser(user.uid, { 
        expiresAt: Timestamp.fromDate(newDate),
        status: 'active'
      });
    }
  };

  const deleteAccount = async (user: UserProfile) => {
    if(confirm(`🚨 ATENÇÃO: Deseja EXCLUIR PERMANENTEMENTE o escritório ${user.email}? Esta ação não pode ser desfeita.`)) {
      await dbService.deleteUser(user.uid);
    }
  };

  const getStatusInfo = (user: UserProfile) => {
    if (user.status === 'blocked') return { label: 'BLOQUEADO', color: 'bg-rose-500 text-white', icon: <ShieldAlert size={14} /> };

    const now = new Date();
    const expiry = user.expiresAt?.toDate();
    const diffTime = expiry.getTime() - now.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays <= 0) return { label: 'VENCIDO', color: 'bg-rose-100 text-rose-600 border border-rose-200', icon: <ShieldAlert size={14} /> };
    if (diffDays <= 5) return { label: `VENCE EM ${diffDays}D`, color: 'bg-amber-100 text-amber-600 border border-amber-200', icon: <Zap size={14} className="fill-amber-500" /> };
    return { label: 'PAGO / ATIVO', color: 'bg-emerald-100 text-emerald-600 border border-emerald-200', icon: <CheckCircle2 size={14} /> };
  };

  const filteredUsers = users.filter(u => u.email.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter italic">Controle de Escritórios<span className="text-amber-500">.</span></h2>
          <p className="text-slate-500 font-bold mt-1 text-lg">Gestão financeira e de acesso dos assinantes.</p>
        </div>
        <div className="flex gap-4">
          <div className="bg-white px-6 py-4 rounded-2xl border border-slate-100 shadow-sm text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Total de Clientes</p>
            <p className="text-xl font-black text-slate-900">{users.length}</p>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex items-center gap-5 shadow-sm">
        <Search className="text-slate-300" size={24} />
        <input 
          type="text" 
          placeholder="Buscar escritório por e-mail..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-bold text-slate-700 placeholder:text-slate-300 text-lg" 
        />
      </div>

      <div className="bg-white rounded-[3.5rem] border border-slate-100 overflow-hidden shadow-sm overflow-x-auto">
        <table className="w-full text-left min-w-[800px]">
          <thead>
            <tr className="bg-slate-50/50">
              <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Escritório / E-mail</th>
              <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Expiração</th>
              <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">Status Financeiro</th>
              <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest text-right">Ações de Gestão</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {isLoading ? (
              <tr>
                <td colSpan={4} className="py-20 text-center"><Loader2 className="animate-spin mx-auto text-amber-500" size={32} /></td>
              </tr>
            ) : filteredUsers.map(user => {
              const status = getStatusInfo(user);
              return (
                <tr key={user.uid} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-10 py-7">
                    <p className="font-extrabold text-slate-700 text-lg">{user.email}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ID: {user.uid.substring(0,8)}</span>
                      <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                      <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Ref: {user.referralCode}</span>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-3">
                      <div className="p-2.5 bg-slate-50 rounded-xl text-slate-400">
                        <Calendar size={18} />
                      </div>
                      <div>
                        <p className="font-black text-slate-700 text-sm">{user.expiresAt?.toDate().toLocaleDateString('pt-BR')}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase">Vencimento</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                     <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest ${status.color}`}>
                       {status.icon}
                       {status.label}
                     </div>
                  </td>
                  <td className="px-10 py-7 text-right">
                     <div className="flex justify-end gap-3">
                       <button 
                         onClick={() => extendSubscription(user)}
                         title="Prorrogar +30 dias (Confirmar Pagamento)"
                         className="w-12 h-12 flex items-center justify-center text-emerald-600 bg-emerald-50 rounded-2xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
                       >
                         <RefreshCw size={20} />
                       </button>
                       <button 
                         onClick={() => toggleStatus(user)}
                         title={user.status === 'blocked' ? 'Desbloquear Acesso' : 'Bloquear Acesso'}
                         className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all shadow-sm ${user.status === 'blocked' ? 'bg-amber-500 text-white hover:bg-amber-600' : 'bg-slate-100 text-slate-600 hover:bg-slate-900 hover:text-white'}`}
                       >
                         {user.status === 'blocked' ? <ShieldCheck size={20} /> : <UserMinus size={20} />}
                       </button>
                       <button 
                         onClick={() => deleteAccount(user)}
