import { initializeApp } from "firebase/app";
import { 
  getFirestore, collection, addDoc, updateDoc, deleteDoc, doc, onSnapshot,
  query, orderBy, where, serverTimestamp, getDoc, setDoc, Timestamp, getDocs, limit
} from "firebase/firestore";
import { getAuth } from "firebase/auth";

// Usando process.env.API_KEY como fallback para evitar o erro de auth/invalid-api-key
// em ambientes onde as chaves específicas do Firebase não foram injetadas separadamente.
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY || process.env.API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN || `${process.env.FIREBASE_PROJECT_ID || 'facindemais-nexus'}.firebaseapp.com`,
  projectId: process.env.FIREBASE_PROJECT_ID || 'facindemais-nexus',
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET || `${process.env.FIREBASE_PROJECT_ID || 'facindemais-nexus'}.appspot.com`,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID || '100000000000',
  appId: process.env.FIREBASE_APP_ID || '1:100000000000:web:default'
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

export const collections = {
  products: collection(db, "products"),
  customers: collection(db, "customers"),
  orders: collection(db, "orders"),
  expenses: collection(db, "expenses"),
  users: collection(db, "users")
};

export const dbService = {
  getUserProfile: async (uid: string) => {
    const docRef = doc(db, "users", uid);
    const docSnap = await getDoc(docRef);
    return docSnap.exists() ? docSnap.data() : null;
  },

  createUserProfile: async (uid: string, email: string, referredByCode?: string) => {
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const referralCode = uid.substring(0, 6).toUpperCase();

    let referredByUid = "";
    if (referredByCode) {
      const q = query(collections.users, where("referralCode", "==", referredByCode), limit(1));
      const snap = await getDocs(q);
      if (!snap.empty) {
        referredByUid = snap.docs[0].id;
        const indicatorRef = doc(db, "users", referredByUid);
        const indicatorData = snap.docs[0].data();
        await updateDoc(indicatorRef, { 
          referralCount: (indicatorData.referralCount || 0) + 1 
        });
      }
    }

    const profile = {
      uid,
      email,
      role: 'user',
      status: 'trial',
      plan: 'pro',
      expiresAt: Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode,
      referredBy: referredByUid,
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  getAllUsers: (callback: (data: any[]) => void) => {
    return onSnapshot(query(collections.users, orderBy("createdAt", "desc")), (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  },

  deleteUser: async (uid: string) => {
    return await deleteDoc(doc(db, "users", uid));
  },

  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    const q = query(collection(db, collectionName), where("userId", "==", userId), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  add: async (collectionName: string, userId: string, data: any) => {
    return await addDoc(collection(db, collectionName), { ...data, userId, createdAt: serverTimestamp() });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  }
};

import React, { useState } from 'react';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence
} from 'firebase/auth';
