              </span>
            </button>
          </form>

          <div className="mt-8 pt-8 border-t border-white/5 text-center">
            <button 
              type="button"
              onClick={() => { setIsRegistering(!isRegistering); setError(''); }}
              className="text-[10px] font-black text-cyan-400/30 hover:text-cyan-400 transition-colors uppercase tracking-[0.2em]"
