import React, { useState } from 'react';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence,
  sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../services/firebase';
import { Lock, Loader2, ShieldCheck, AlertTriangle, Cpu, Mail } from 'lucide-react';

const LoginView: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      try {
        await setPersistence(auth, browserLocalPersistence);
      } catch (pErr) {
        console.warn("Falha na persistência, continuando login padrão.");
      }

      if (isRecovering) {
        await sendPasswordResetEmail(auth, email);
        setMessage({ text: 'Link de recuperação enviado para o seu e-mail.', type: 'success' });
        setTimeout(() => setIsRecovering(false), 3000);
      } else if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error("Erro Firebase Auth:", err);
      let errorMsg = 'ACESSO NEGADO: Credenciais incorretas ou falha na rede.';

      if (err.code === 'auth/invalid-api-key') {
        errorMsg = 'ERRO CRÍTICO: Chave Nexus inválida. Verifique as variáveis de ambiente.';
      } else if (err.code === 'auth/user-not-found') {
        errorMsg = 'Protocolo não encontrado para este e-mail.';
      } else if (err.code === 'auth/wrong-password') {
        errorMsg = 'Senha de segurança inválida.';
      } else if (err.code === 'auth/weak-password') {
        errorMsg = 'A senha deve conter no mínimo 6 dígitos.';
      }

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#0d0221] p-4 relative overflow-hidden font-terminal">
      <div className="absolute inset-0 grid-bg"></div>
      <div className="scanline"></div>

      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-cyan-500/10 rounded-full blur-[120px] pointer-events-none"></div>

      <div className="w-full max-w-[420px] relative z-10 animate-fade-in">
        <div className="bg-[#160833]/70 border-2 border-cyan-400/20 rounded-[3rem] p-10 backdrop-blur-xl shadow-[0_0_50px_rgba(0,243,255,0.1)]">

          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-[#0d0221] border border-cyan-400/30 text-cyan-400 shadow-[0_0_20px_rgba(0,243,255,0.2)] mb-6">
              {isRecovering ? <Mail size={28} /> : <Lock size={28} />}
            </div>
            <h1 className="text-3xl font-black text-white tracking-[0.2em] uppercase mb-1">
              FACINDEMAIS
            </h1>
            <p className="text-cyan-400/40 text-[9px] font-bold tracking-[0.4em] uppercase">
              {isRecovering ? 'Protocolo de Recuperação' : 'Nexus Terminal OS v3.1'}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-cyan-400/50 uppercase tracking-widest ml-1">E-mail de Acesso</label>
              <input 
                required
                type="email" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl outline-none focus:border-cyan-400/40 focus:ring-4 focus:ring-cyan-400/5 transition-all font-bold text-white placeholder:text-white/10"
                placeholder="USUARIO@NEXUS"
              />
            </div>

            {!isRecovering && (
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-cyan-400/50 uppercase tracking-widest ml-1">Senha de Segurança</label>
                <input 
                  required
                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl outline-none focus:border-cyan-400/40 focus:ring-4 focus:ring-cyan-400/5 transition-all font-bold text-white placeholder:text-white/10"
                  placeholder="••••••••"
                />
              </div>
            )}

            {message.text && (
              <div className={`p-4 ${message.type === 'error' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'} text-[9px] font-black rounded-xl border flex items-center gap-3 animate-pulse uppercase tracking-wider`}>
                <AlertTriangle size={14} className="shrink-0" />
                <span>{message.text}</span>
              </div>
            )}

            <button 
              disabled={isLoading}
              type="submit"
              className="w-full bg-cyan-400 hover:bg-cyan-300 text-black py-5 rounded-2xl font-black shadow-[0_0_30px_rgba(0,243,255,0.3)] flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50 mt-6 relative overflow-hidden group"
            >
              <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700 pointer-events-none"></div>
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <ShieldCheck size={20} />}
              <span className="tracking-widest uppercase text-sm">
                {isLoading ? 'Sincronizando...' : isRecovering ? 'Resetar Senha' : 'Acessar Terminal'}
              </span>
            </button>
          </form>

          <div className="mt-8 pt-8 border-t border-white/5 flex flex-col items-center gap-4">
            {!isRecovering ? (
              <>
                <button 
                  type="button"
                  onClick={() => { setIsRegistering(!isRegistering); setMessage({ text: '', type: '' }); }}
                  className="text-[10px] font-black text-cyan-400/30 hover:text-cyan-400 transition-colors uppercase tracking-[0.2em]"
                >
                  {isRegistering ? 'Retornar ao Login' : 'Solicitar Protocolo de Acesso'}
                </button>
                <button 
                  type="button"
                  onClick={() => { setIsRecovering(true); setMessage({ text: '', type: '' }); }}
                  className="text-[9px] font-bold text-white/20 hover:text-rose-400 transition-colors uppercase tracking-[0.1em]"
                >
                  Esqueci minha senha
                </button>
              </>
            ) : (
              <button 
                type="button"
                onClick={() => { setIsRecovering(false); setMessage({ text: '', type: '' }); }}
                className="text-[10px] font-black text-cyan-400/30 hover:text-cyan-400 transition-colors uppercase tracking-[0.2em]"
              >
                Voltar para Acesso
              </button>
            )}
          </div>
        </div>

        <div className="mt-8 flex items-center justify-center gap-4 text-cyan-400/10">
          <Cpu size={14} />
          <p className="text-[8px] font-bold uppercase tracking-[0.5em]">
            AES-256 Cloud Encryption Active
          </p>
          <Cpu size={14} />
        </div>
      </div>
    </div>
  );
};

