import { updatePassword, updateProfile } from 'firebase/auth';
import { auth } from '../services/firebase';
import { Settings, Key, User, ShieldCheck, Loader2, Save, CheckCircle2, AlertTriangle } from 'lucide-react';
import { UserProfile } from '../types';

interface SettingsViewProps {
  profile: UserProfile;
}

const SettingsView: React.FC<SettingsViewProps> = ({ profile }) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      return setMessage({ text: 'As senhas não coincidem!', type: 'error' });
    }
    if (newPassword.length < 6) {
      return setMessage({ text: 'A senha deve ter no mínimo 6 caracteres.', type: 'error' });
    }

    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      const user = auth.currentUser;
      if (user) {
        await updatePassword(user, newPassword);
        setMessage({ text: 'Senha atualizada com sucesso!', type: 'success' });
        setNewPassword('');
        setConfirmPassword('');
      }
    } catch (err: any) {
      console.error(err);
      if (err.code === 'auth/requires-recent-login') {
        setMessage({ text: 'Por segurança, faça logout e login novamente para trocar a senha.', type: 'error' });
      } else {
        setMessage({ text: 'Erro ao atualizar senha.', type: 'error' });
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter italic flex items-center gap-4">
            <div className="p-3 bg-slate-900 rounded-2xl text-cyan-400 shadow-xl shadow-slate-200">
              <Settings size={28} />
            </div>
            Configurações<span className="text-cyan-500">.</span>
          </h2>
          <p className="text-slate-500 font-bold mt-2 text-lg">Gerencie sua segurança e dados de acesso.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white rounded-[3.5rem] p-10 md:p-12 shadow-sm border border-slate-100 relative overflow-hidden">
             <div className="flex items-center gap-5 mb-10">
                <div className="w-14 h-14 rounded-2xl bg-cyan-50 text-cyan-600 flex items-center justify-center shadow-inner">
                  <Key size={28} />
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight">Segurança do Terminal</h3>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Altere sua senha de acesso</p>
                </div>
              </div>

              <form onSubmit={handleChangePassword} className="space-y-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nova Senha</label>
                  <input 
                    required
                    type="password" 
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-4 focus:ring-cyan-500/5 transition-all font-bold text-slate-900"
                    placeholder="Letras ou números (min 6)"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirmar Nova Senha</label>
                  <input 
                    required
                    type="password" 
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-4 focus:ring-cyan-500/5 transition-all font-bold text-slate-900"
                    placeholder="Repita a nova senha"
                  />
                </div>

                {message.text && (
                  <div className={`p-4 ${message.type === 'error' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'} text-xs font-black rounded-xl border flex items-center gap-3 animate-fade-in uppercase tracking-wider`}>
                    {message.type === 'error' ? <AlertTriangle size={16} /> : <CheckCircle2 size={16} />}
                    <span>{message.text}</span>
                  </div>
                )}

                <button 
                  disabled={isLoading}
                  type="submit"
                  className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl shadow-slate-200 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50 mt-4"
                >
                  {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />}
                  <span className="tracking-widest uppercase text-sm">Atualizar Senha</span>
                </button>
              </form>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-slate-900 p-10 rounded-[3.5rem] text-white shadow-2xl shadow-slate-200 relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-40 h-40 bg-cyan-500/10 rounded-full -mr-20 -mt-20 transition-transform group-hover:scale-125 duration-700"></div>
            <h4 className="font-black text-2xl mb-6 flex items-center gap-3">
              <ShieldCheck size={28} className="text-cyan-400" />
              Privacidade Nexus
            </h4>
            <p className="text-slate-400 font-bold text-sm leading-relaxed mb-6">
              Sua conta está em um nó isolado e criptografado. Nenhum outro usuário tem visibilidade sobre seus dados, clientes ou faturamento.
            </p>
            <div className="p-5 bg-white/5 rounded-3xl border border-white/10 text-[10px] font-black text-cyan-400 flex items-center gap-3 uppercase tracking-widest">
              Ambiente 100% Único
            </div>
          </div>

          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
            <h4 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3 italic">
              <User size={20} className="text-cyan-500" /> Perfil Ativo
            </h4>
            <div className="space-y-4">
               <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">E-mail</p>
                 <p className="font-bold text-slate-700 truncate">{profile.email}</p>
               </div>
               <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Plano</p>
                 <p className="font-bold text-cyan-600 uppercase italic">{profile.plan}</p>
               </div>
               <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Protocolo ID</p>
                 <p className="font-mono text-xs text-slate-500">{profile.uid}</p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Package, Users, ShoppingCart, Sparkles, 
  Menu, X, Loader2, WalletMinimal, Zap, ShieldAlert, UserCog, Gift, Cpu, Settings
} from 'lucide-react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { Product, Customer, Order, Expense, ViewState, UserProfile } from './types';
import DashboardView from './views/DashboardView';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import LoginView from './views/LoginView';
import AdminView from './views/AdminView';
import ReferralView from './views/ReferralView';
import SettingsView from './views/SettingsView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const refCode = urlParams.get('ref');
    if (refCode) sessionStorage.setItem('referredByCode', refCode);

    const unsubAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        let userProfile = await dbService.getUserProfile(user.uid);
        if (!userProfile) {
          const storedRefCode = sessionStorage.getItem('referredByCode') || undefined;
          userProfile = await dbService.createUserProfile(user.uid, user.email || '', storedRefCode);
        }
        setProfile(userProfile as UserProfile);
        setCurrentUser(user);
      } else {
        setCurrentUser(null);
        setProfile(null);
      }
      setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser || !profile) return;

    // Verificação de expiração apenas para usuários comuns
    const isExpired = profile.role !== 'admin' && profile.expiresAt?.toDate() < new Date();
    const isBlocked = profile.status === 'blocked';

    if (isExpired || isBlocked) return;

    const uid = currentUser.uid;
    // Subscrições isoladas por UID para garantir que um usuário nunca veja dados do outro
    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => setOrders(data as Order[]));

    return () => {
      unsubProducts(); unsubCustomers(); unsubOrders(); unsubExpenses();
    };
  }, [currentUser, profile]);

  const navItems = [
    { id: 'DASHBOARD', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { id: 'PRODUCTS', label: 'Produtos', icon: <Package size={20} /> },
    { id: 'CUSTOMERS', label: 'Clientes', icon: <Users size={20} /> },
    { id: 'ORDERS', label: 'Vendas', icon: <ShoppingCart size={20} /> },
    { id: 'EXPENSES', label: 'Finanças', icon: <WalletMinimal size={20} /> },
    { id: 'AI_INSIGHTS', label: 'Nexus AI', icon: <Sparkles size={20} /> },
    { id: 'REFERRALS', label: 'Recompensas', icon: <Gift size={20} /> },
    { id: 'SETTINGS', label: 'Ajustes', icon: <Settings size={20} /> },
  ];

  if (isLoading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-[#0d0221] relative overflow-hidden">
        <div className="absolute inset-0 grid-bg opacity-20"></div>
        <div className="scanline"></div>
        <Loader2 className="animate-spin text-cyan-400 mb-6 relative z-10" size={56} />
        <p className="font-terminal font-black text-cyan-400 tracking-[0.3em] text-xl italic relative z-10 animate-pulse">BOOTING NEXUS OS</p>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  const isExpired = profile?.role !== 'admin' && profile?.expiresAt?.toDate() < new Date();
  const isBlocked = profile?.status === 'blocked';

  if (isExpired || isBlocked) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-[#0d0221] p-6 relative">
        <div className="absolute inset-0 grid-bg opacity-10"></div>
        <div className="max-w-md w-full glass-nexus rounded-[3rem] p-12 text-center shadow-[0_0_50px_rgba(244,63,94,0.1)] animate-fade-in border border-rose-500/20">
          <ShieldAlert size={80} className="mx-auto text-rose-500 mb-8 drop-shadow-[0_0_15px_rgba(244,63,94,0.5)]" />
          <h2 className="text-3xl font-terminal font-black text-white mb-4 italic tracking-wider">TERMINAL BLOQUEADO</h2>
          <p className="text-slate-400 font-bold mb-10 leading-relaxed uppercase text-xs tracking-[0.1em]">Detectada expiração de licença ou bloqueio administrativo. Sincronize seu pagamento para restabelecer o acesso.</p>
          <button onClick={() => signOut(auth)} className="w-full bg-rose-600 text-white py-5 rounded-2xl font-black shadow-xl hover:bg-rose-500 transition-all font-terminal tracking-widest">LOGOUT</button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-[#F8FAFC] lg:bg-[#F1F5F9] overflow-hidden text-slate-800">
      <div className={`fixed inset-0 bg-slate-900/60 z-40 lg:hidden transition-opacity duration-300 backdrop-blur-sm ${isSidebarOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`} onClick={() => setIsSidebarOpen(false)} />

      <aside className={`fixed lg:static inset-y-0 left-0 z-50 w-72 bg-white lg:bg-transparent border-r border-slate-100 lg:border-none transform transition-transform duration-300 ease-in-out lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full p-6 lg:p-8">
          <div className="flex items-center justify-between mb-12 px-2">
            <div className="flex items-center gap-4">
              <div className="bg-slate-900 p-2.5 rounded-2xl shadow-xl shadow-slate-200">
                <Cpu className="text-cyan-400" size={26} />
              </div>
              <div>
                <h1 className="text-xl font-terminal font-black text-slate-900 italic tracking-tighter leading-none">FACINDEMAIS</h1>
                <span className="text-[9px] font-black text-cyan-600 uppercase tracking-[0.3em]">Nexus Terminal</span>
              </div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-slate-400 hover:text-slate-900"><X size={24} /></button>
          </div>

          <nav className="flex-1 space-y-1.5 overflow-y-auto custom-scrollbar">
            {navItems.map((item) => (
              <button 
                key={item.id} 
                onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }} 
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${view === item.id ? 'bg-slate-900 text-white shadow-xl shadow-slate-300' : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900'}`}
              >
                <span className={view === item.id ? 'text-cyan-400' : ''}>{item.icon}</span>
                {item.label}
              </button>
            ))}

            {profile?.role === 'admin' && (
              <div className="pt-8 mt-8 border-t border-slate-200/50">
                <p className="px-5 text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Master Control</p>
                <button 
                  onClick={() => { setView('ADMIN_PANEL'); setIsSidebarOpen(false); }} 
                  className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${view === 'ADMIN_PANEL' ? 'bg-amber-500 text-white shadow-xl shadow-amber-200' : 'text-slate-500 hover:bg-slate-100'}`}
                >
                  <UserCog size={20} /> Administração
                </button>
              </div>
            )}
          </nav>

          <div className="mt-auto pt-8 border-t border-slate-100">
            <div className="bg-white rounded-3xl p-4 flex items-center gap-3 shadow-sm border border-slate-50 group">
              <div className="w-11 h-11 rounded-2xl bg-slate-900 flex items-center justify-center text-cyan-400 font-terminal font-black text-lg group-hover:shadow-[0_0_15px_rgba(0,243,255,0.3)] transition-all">
                {profile?.email.charAt(0).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-black text-slate-900 truncate uppercase tracking-tighter">{profile?.email.split('@')[0]}</p>
                <button onClick={() => signOut(auth)} className="text-[10px] font-bold text-rose-500 uppercase hover:text-rose-600 transition-colors">Terminar Sessão</button>
              </div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/60 lg:bg-transparent backdrop-blur-xl lg:backdrop-blur-none border-b border-slate-100 lg:border-none flex items-center justify-between px-6 lg:px-12 z-30">
          <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-3 text-slate-600 bg-white rounded-xl shadow-sm border border-slate-50 active:scale-95"><Menu size={22} /></button>
          <div className="flex-1 flex justify-end items-center gap-8">
             <div className="flex flex-col items-end">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocolo Ativo</span>
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                  <span className="text-xs font-black text-slate-800 uppercase italic">Acesso {profile?.plan}</span>
                </div>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12 lg:pt-4">
          <div className="max-w-[1400px] mx-auto">
            {view === 'DASHBOARD' && <DashboardView orders={orders} products={products} expenses={expenses} />}
            {view === 'PRODUCTS' && <ProductsView products={products} userId={currentUser.uid} />}
            {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={currentUser.uid} />}
            {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={currentUser.uid} />}
            {view === 'EXPENSES' && <ExpensesView expenses={expenses} userId={currentUser.uid} />}
            {view === 'AI_INSIGHTS' && <AIInsightsView orders={orders} products={products} />}
            {view === 'ADMIN_PANEL' && profile?.role === 'admin' && <AdminView />}
            {view === 'REFERRALS' && <ReferralView profile={profile!} />}
            {view === 'SETTINGS' && <SettingsView profile={profile!} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import { initializeApp } from "firebase/app";
import { 
  getFirestore, collection, addDoc, updateDoc, deleteDoc, doc, onSnapshot,
  query, orderBy, where, serverTimestamp, getDoc, setDoc, Timestamp, getDocs, limit
} from "firebase/firestore";
import { getAuth } from "firebase/auth";

// IMPORTANTE: Para rodar online, você deve garantir que estas variáveis 
// estejam configuradas no seu painel de hospedagem.
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY || process.env.API_KEY, 
  authDomain: process.env.FIREBASE_AUTH_DOMAIN || "facindemais-nexus.firebaseapp.com",
  projectId: process.env.FIREBASE_PROJECT_ID || "facindemais-nexus",
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET || "facindemais-nexus.appspot.com",
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID || "100000000000",
  appId: process.env.FIREBASE_APP_ID || "1:100000000000:web:default"
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

const MASTER_ADMIN_EMAIL = "giufarlosdias@hotmail.com";

export const dbService = {
  getUserProfile: async (uid: string) => {
    const docRef = doc(db, "users", uid);
    const docSnap = await getDoc(docRef);
    return docSnap.exists() ? docSnap.data() : null;
  },

  createUserProfile: async (uid: string, email: string, referredByCode?: string) => {
    const isAdmin = email.toLowerCase() === MASTER_ADMIN_EMAIL.toLowerCase();
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const profile = {
      uid,
      email,
      role: isAdmin ? 'admin' : 'user',
      status: 'active',
      plan: isAdmin ? 'master' : 'pro',
      expiresAt: isAdmin ? Timestamp.fromDate(new Date(2099, 11, 31)) : Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  // ISOLAMENTO TOTAL: Filtro compulsório por userId em todas as buscas
  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    if (!userId) return () => {};
    const q = query(
      collection(db, collectionName), 
      where("userId", "==", userId), 
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  add: async (collectionName: string, userId: string, data: any) => {
    if (!userId) throw new Error("Usuário não autenticado");
    return await addDoc(collection(db, collectionName), { 
      ...data, 
      userId, 
      createdAt: serverTimestamp() 
    });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  },

  getAllUsers: (callback: (data: any[]) => void) => {
    return onSnapshot(query(collection(db, "users"), orderBy("createdAt", "desc")), (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  }
};

import React, { useState } from 'react';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence,
  sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../services/firebase';
import { Lock, Loader2, ShieldCheck, AlertTriangle, Cpu, Mail, ArrowLeft } from 'lucide-react';

const LoginView: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      await setPersistence(auth, browserLocalPersistence);

      if (isRecovering) {
        await sendPasswordResetEmail(auth, email);
        setMessage({ text: 'Link de recuperação enviado para seu e-mail!', type: 'success' });
        setTimeout(() => setIsRecovering(false), 3000);
      } else if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error("Erro Auth:", err.code);
      let errorMsg = 'Falha na autenticação. Verifique os dados.';

      if (err.code === 'auth/invalid-api-key' || err.code === 'auth/api-key-not-valid') {
        errorMsg = 'ERRO DE CONFIGURAÇÃO: API Key do Firebase não configurada corretamente.';
      } else if (err.code === 'auth/user-not-found') {
        errorMsg = 'Usuário não encontrado.';
      } else if (err.code === 'auth/wrong-password') {
        errorMsg = 'Senha incorreta.';
      } else if (err.code === 'auth/weak-password') {
        errorMsg = 'A senha deve ter no mínimo 6 caracteres.';
      }

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
