import React, { useState } from 'react';
import { updatePassword } from 'firebase/auth';
import { auth } from '../services/firebase';
import { Settings, Key, ShieldCheck, Loader2, Save, CheckCircle2, AlertTriangle } from 'lucide-react';
import { UserProfile } from '../types';

interface SettingsViewProps {
  profile: UserProfile;
}

const SettingsView: React.FC<SettingsViewProps> = ({ profile }) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      return setMessage({ text: 'As senhas não coincidem!', type: 'error' });
    }
    if (newPassword.length < 6) {
      return setMessage({ text: 'A senha deve ter no mínimo 6 caracteres.', type: 'error' });
    }

    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setMessage({ text: 'Senha atualizada com sucesso!', type: 'success' });
        setNewPassword(''); setConfirmPassword('');
      }
    } catch (err: any) {
      if (err.code === 'auth/requires-recent-login') {
        setMessage({ text: 'Por segurança, saia e entre novamente para mudar a senha.', type: 'error' });
      } else {
        setMessage({ text: 'Erro ao atualizar senha.', type: 'error' });
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-fade-in pb-20">
      <div>
        <h2 className="text-4xl font-black text-slate-900 tracking-tighter italic flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-2xl text-cyan-400 shadow-xl shadow-slate-200">
            <Settings size={28} />
          </div>
          Configurações<span className="text-cyan-500">.</span>
        </h2>
        <p className="text-slate-500 font-bold mt-2 text-lg">Segurança e dados do terminal.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2">
          <div className="bg-white rounded-[3.5rem] p-10 shadow-sm border border-slate-100">
             <div className="flex items-center gap-5 mb-10">
                <div className="w-14 h-14 rounded-2xl bg-cyan-50 text-cyan-600 flex items-center justify-center">
                  <Key size={28} />
                </div>
                <h3 className="text-2xl font-black text-slate-900">Trocar Senha</h3>
              </div>

              <form onSubmit={handleChangePassword} className="space-y-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nova Senha (Letras ou Números)</label>
                  <input 
                    required type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:ring-4 focus:ring-cyan-500/5 transition-all"
                    placeholder="Mínimo 6 caracteres"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirmar Senha</label>
                  <input 
                    required type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:ring-4 focus:ring-cyan-500/5 transition-all"
                  />
                </div>

                {message.text && (
                  <div className={`p-4 ${message.type === 'error' ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500'} text-xs font-black rounded-xl border flex items-center gap-3`}>
                    {message.type === 'error' ? <AlertTriangle size={16} /> : <CheckCircle2 size={16} />}
                    <span>{message.text}</span>
                  </div>
                )}

                <button 
                  disabled={isLoading} type="submit"
                  className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl shadow-slate-200 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50"
                >
                  {isLoading ? <Loader2 className="animate-spin" /> : <Save size={20} />}
                  <span className="tracking-widest uppercase">Salvar Nova Senha</span>
                </button>
              </form>
          </div>
        </div>

        <div className="bg-slate-900 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden h-fit">
          <ShieldCheck size={28} className="text-cyan-400 mb-6" />
          <h4 className="font-black text-2xl mb-4">Privacidade Nexus</h4>
          <p className="text-slate-400 font-bold text-sm leading-relaxed">
            Seus dados são armazenados em silos criptografados. Cada login cria um ambiente isolado.
          </p>
          <div className="mt-8 pt-8 border-t border-white/10 text-[10px] font-black text-cyan-400 uppercase tracking-widest">
            Protocolo: AES-256 Cloud
          </div>
        </div>
      </div>
    </div>
  );
};

