import React, { useState } from 'react';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence,
  sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../services/firebase';
import { Lock, Loader2, ShieldCheck, AlertTriangle, Mail, ArrowLeft, Zap } from 'lucide-react';

const LoginView: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) return;

    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      await setPersistence(auth, browserLocalPersistence);

      if (isRecovering) {
        await sendPasswordResetEmail(auth, email);
        setMessage({ text: 'Link de recuperação enviado!', type: 'success' });
        setTimeout(() => setIsRecovering(false), 3000);
      } else if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error("Erro Auth:", err.code);
      let errorMsg = 'E-mail ou senha incorretos.';

      if (err.code?.includes('api-key-not-valid') || err.code?.includes('invalid-api-key')) {
        errorMsg = 'ERRO CRÍTICO: Chave do Firebase inválida. Verifique o arquivo services/firebase.ts';
      } else if (err.code === 'auth/user-not-found') {
        errorMsg = 'Usuário não cadastrado.';
      } else if (err.code === 'auth/wrong-password') {
        errorMsg = 'Senha incorreta.';
      } else if (err.code === 'auth/weak-password') {
        errorMsg = 'Senha muito fraca (mínimo 6 caracteres).';
      } else if (err.code === 'auth/email-already-in-use') {
        errorMsg = 'Este e-mail já está em uso.';
      }

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-[#0d0221] p-4 relative overflow-hidden font-terminal">
      {/* Background futurista */}
      <div className="absolute inset-0 grid-bg opacity-30"></div>
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-500/10 blur-[120px] rounded-full"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-500/10 blur-[120px] rounded-full"></div>
      <div className="scanline"></div>

      <div className="w-full max-w-[440px] relative z-10 animate-fade-in">
        <div className="bg-[#160833]/60 border border-cyan-400/20 rounded-[3.5rem] p-10 backdrop-blur-3xl shadow-[0_0_80px_rgba(0,243,255,0.05)]">

          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 rounded-3xl bg-black/40 border-2 border-cyan-400/30 text-cyan-400 mb-6 shadow-[0_0_30px_rgba(0,243,255,0.2)]">
              {isRecovering ? <Mail size={32} /> : <Zap size={32} className="fill-current" />}
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase mb-1 italic">FACINDEMAIS</h1>
            <p className="text-cyan-400/40 text-[10px] font-black tracking-[0.5em] uppercase">
              {isRecovering ? 'Redefinir Acesso' : 'Nexus OS v3.2'}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-cyan-400/50 uppercase tracking-widest ml-1">E-mail de Operador</label>
              <input 
                required type="email" value={email} onChange={(e) => setEmail(e.target.value)}
                className="w-full px-6 py-5 bg-black/40 border border-white/5 rounded-2xl outline-none focus:border-cyan-400/60 text-white font-bold transition-all"
                placeholder="nome@email.com"
              />
            </div>

            {!isRecovering && (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400/50 uppercase tracking-widest ml-1">Chave de Acesso</label>
                <input 
                  required type="password" value={password} onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-6 py-5 bg-black/40 border border-white/5 rounded-2xl outline-none focus:border-cyan-400/60 text-white font-bold transition-all"
                  placeholder="••••••••"
                />
              </div>
            )}

            {message.text && (
              <div className={`p-4 ${message.type === 'error' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'} text-[11px] font-black rounded-2xl border flex items-center gap-3 uppercase animate-pulse`}>
                <AlertTriangle size={16} />
                <span>{message.text}</span>
              </div>
            )}

            <button 
              disabled={isLoading} type="submit"
              className="w-full bg-cyan-400 hover:bg-cyan-300 text-black py-6 rounded-2xl font-black shadow-[0_10px_40px_rgba(0,243,255,0.25)] flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50 text-sm tracking-widest uppercase mt-4"
            >
              {isLoading ? <Loader2 className="animate-spin" /> : <ShieldCheck size={22} />}
              {isRecovering ? 'Enviar Reset' : isRegistering ? 'Criar Terminal' : 'Autenticar'}
            </button>
          </form>

          <div className="mt-10 flex flex-col items-center gap-5 border-t border-white/5 pt-8">
            <div className="flex justify-center gap-6">
              <button onClick={() => setIsRegistering(!isRegistering)} className="text-[10px] font-black text-cyan-400/40 hover:text-cyan-400 uppercase tracking-widest transition-colors">
                {isRegistering ? 'Login Existente' : 'Novo Registro'}
              </button>
              <button onClick={() => setIsRecovering(true)} className="text-[10px] font-black text-white/20 hover:text-rose-400 uppercase tracking-widest transition-colors">
                Esqueci a Senha
              </button>
            </div>

            {isRecovering && (
              <button onClick={() => setIsRecovering(false)} className="flex items-center gap-2 text-[10px] font-black text-cyan-400/60 hover:text-cyan-400 uppercase tracking-widest">
                <ArrowLeft size={12} /> Voltar ao Painel
              </button>
            )}
          </div>
        </div>

        <p className="mt-8 text-center text-[9px] font-black text-white/10 uppercase tracking-[0.4em]">
          Secure Connection Established via Facindemais Cloud
        </p>
      </div>
    </div>
  );
