import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  setPersistence,
  browserLocalPersistence,
  sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../services/firebase';
import { Lock, Loader2, ShieldCheck, AlertTriangle, Mail, ArrowLeft, Zap, Sun } from 'lucide-react';

const LoginView: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) return;

    setIsLoading(true);
    setMessage({ text: '', type: '' });

    try {
      await setPersistence(auth, browserLocalPersistence);

      if (isRecovering) {
        await sendPasswordResetEmail(auth, email);
        setMessage({ text: 'Link de recuperação enviado!', type: 'success' });
        setTimeout(() => setIsRecovering(false), 3000);
      } else if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      console.error("Erro Auth:", err.code);
      let errorMsg = 'E-mail ou senha incorretos.';

      if (err.code?.includes('api-key-not-valid') || err.code?.includes('invalid-api-key')) {
        errorMsg = 'CONFIGURAÇÃO PENDENTE: Chave do Firebase ausente no servidor.';
      } else if (err.code === 'auth/user-not-found') {
        errorMsg = 'Usuário não cadastrado.';
      } else if (err.code === 'auth/wrong-password') {
        errorMsg = 'Senha incorreta.';
      }

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-white p-4 relative overflow-hidden font-terminal">
      {/* Background Radiante */}
      <div className="absolute inset-0 grid-bg-light opacity-60"></div>
      <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-cyan-200/40 blur-[150px] rounded-full"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-purple-200/40 blur-[150px] rounded-full"></div>
      <div className="scanline"></div>

      <div className="w-full max-w-[460px] relative z-10 animate-fade-in">
        <div className="bg-white/80 border border-white rounded-[4rem] p-12 backdrop-blur-3xl shadow-[0_30px_100px_rgba(0,243,255,0.15)] ring-1 ring-cyan-100">

          <div className="text-center mb-12">
            <div className="inline-flex items-center justify-center w-24 h-24 rounded-[2.5rem] bg-gradient-to-br from-cyan-400 to-purple-500 text-white mb-8 shadow-[0_15px_40px_rgba(0,243,255,0.4)] transform hover:rotate-6 transition-transform">
              {isRecovering ? <Mail size={36} /> : <Sun size={36} className="animate-spin-slow" />}
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tighter uppercase mb-2 italic bg-clip-text text-transparent bg-gradient-to-r from-slate-900 to-slate-500">FACINDEMAIS</h1>
            <p className="text-cyan-500 font-black tracking-[0.5em] text-[11px] uppercase opacity-80">
              {isRecovering ? 'RESTAURAR PORTAL' : 'NEXUS RADIANT v4.0'}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Identificação de Operador</label>
              <input 
                required type="email" value={email} onChange={(e) => setEmail(e.target.value)}
                className="w-full px-8 py-6 bg-slate-50 border-2 border-transparent rounded-[2rem] outline-none focus:border-cyan-400/30 focus:bg-white text-slate-800 font-bold transition-all shadow-inner"
                placeholder="operador@nexus.com"
              />
            </div>

            {!isRecovering && (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Código de Segurança</label>
                <input 
                  required type="password" value={password} onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-8 py-6 bg-slate-50 border-2 border-transparent rounded-[2rem] outline-none focus:border-cyan-400/30 focus:bg-white text-slate-800 font-bold transition-all shadow-inner"
                  placeholder="••••••••"
                />
              </div>
            )}

            {message.text && (
              <div className={`p-5 ${message.type === 'error' ? 'bg-rose-50 text-rose-500 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'} text-xs font-black rounded-3xl border flex items-center gap-4 uppercase animate-bounce`}>
                <AlertTriangle size={18} />
                <span>{message.text}</span>
              </div>
            )}

            <button 
              disabled={isLoading} type="submit"
              className="w-full bg-slate-900 hover:bg-black text-white py-7 rounded-[2.5rem] font-black shadow-[0_15px_45px_rgba(0,0,0,0.15)] flex items-center justify-center gap-4 transition-all active:scale-95 disabled:opacity-50 text-base tracking-widest uppercase mt-6 group"
            >
              {isLoading ? <Loader2 className="animate-spin" /> : <ShieldCheck size={24} className="group-hover:text-cyan-400 transition-colors" />}
              {isRecovering ? 'ENVIAR PORTAL' : isRegistering ? 'INICIALIZAR' : 'AUTENTICAR'}
            </button>
          </form>

          <div className="mt-12 flex flex-col items-center gap-6 border-t border-slate-100 pt-10">
            <div className="flex justify-center gap-8">
              <button onClick={() => setIsRegistering(!isRegistering)} className="text-[11px] font-black text-slate-400 hover:text-cyan-600 uppercase tracking-widest transition-all">
                {isRegistering ? 'VOLTAR AO LOGIN' : 'SOLICITAR ACESSO'}
              </button>
              <button onClick={() => setIsRecovering(true)} className="text-[11px] font-black text-slate-300 hover:text-rose-500 uppercase tracking-widest transition-all">
                PERDI A CHAVE
              </button>
            </div>

            {isRecovering && (
              <button onClick={() => setIsRecovering(false)} className="flex items-center gap-2 text-[11px] font-black text-cyan-500 hover:text-cyan-700 uppercase tracking-widest">
                <ArrowLeft size={14} /> RETORNAR AO TERMINAL
              </button>
            )}
          </div>
        </div>

        <p className="mt-10 text-center text-[10px] font-black text-slate-300 uppercase tracking-[0.5em] animate-pulse">
          PROTECTED BY FACINDEMAIS LIGHT ENCRYPTION
        </p>
      </div>

      <style>{`
        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .animate-spin-slow {
          animation: spin-slow 12s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Package, Users, ShoppingCart, Sparkles, 
  Menu, X, Loader2, WalletMinimal, Zap, ShieldAlert, UserCog, Gift, Cpu, Settings, Sun
} from 'lucide-react';
import { onAuthStateChanged, signOut, User } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { Product, Customer, Order, Expense, ViewState, UserProfile } from './types';
import DashboardView from './views/DashboardView';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import LoginView from './views/LoginView';
import AdminView from './views/AdminView';
import ReferralView from './views/ReferralView';
import SettingsView from './views/SettingsView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const unsubAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        let userProfile = await dbService.getUserProfile(user.uid);
        if (!userProfile) {
          const storedRefCode = sessionStorage.getItem('referredByCode') || undefined;
          userProfile = await dbService.createUserProfile(user.uid, user.email || '', storedRefCode);
        }
        setProfile(userProfile as UserProfile);
        setCurrentUser(user);
      } else {
        setCurrentUser(null);
        setProfile(null);
      }
      setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser || !profile) return;

    const isExpired = profile.role !== 'admin' && profile.expiresAt?.toDate() < new Date();
    const isBlocked = profile.status === 'blocked';

    if (isExpired || isBlocked) return;

    const uid = currentUser.uid;
    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => setOrders(data as Order[]));

    return () => {
      unsubProducts(); unsubCustomers(); unsubOrders(); unsubExpenses();
    };
  }, [currentUser, profile]);

  const navItems = [
    { id: 'DASHBOARD', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { id: 'PRODUCTS', label: 'Produtos', icon: <Package size={20} /> },
    { id: 'CUSTOMERS', label: 'Clientes', icon: <Users size={20} /> },
    { id: 'ORDERS', label: 'Vendas', icon: <ShoppingCart size={20} /> },
    { id: 'EXPENSES', label: 'Finanças', icon: <WalletMinimal size={20} /> },
    { id: 'AI_INSIGHTS', label: 'Nexus AI', icon: <Sparkles size={20} /> },
    { id: 'REFERRALS', label: 'Recompensas', icon: <Gift size={20} /> },
    { id: 'SETTINGS', label: 'Ajustes', icon: <Settings size={20} /> },
  ];

  if (isLoading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white relative overflow-hidden">
        <div className="absolute inset-0 grid-bg-light opacity-40"></div>
        <div className="scanline"></div>
        <Loader2 className="animate-spin text-cyan-500 mb-8 relative z-10" size={64} />
        <p className="font-terminal font-black text-slate-800 tracking-[0.4em] text-2xl italic relative z-10 animate-pulse">AWAKENING RADIANT OS</p>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  return (
    <div className="flex h-screen bg-[#F0F4F8] overflow-hidden text-slate-800">
      <div className={`fixed inset-0 bg-slate-900/10 z-40 lg:hidden transition-opacity duration-300 backdrop-blur-md ${isSidebarOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`} onClick={() => setIsSidebarOpen(false)} />

      <aside className={`fixed lg:static inset-y-0 left-0 z-50 w-80 bg-white border-r border-white/80 transform transition-transform duration-500 ease-in-out lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} shadow-[20px_0_60px_rgba(0,0,0,0.02)]`}>
        <div className="flex flex-col h-full p-8">
          <div className="flex items-center justify-between mb-16 px-2">
            <div className="flex items-center gap-5">
              <div className="bg-slate-900 p-3 rounded-[1.5rem] shadow-[0_10px_30px_rgba(0,0,0,0.15)] transform hover:rotate-12 transition-transform">
                <Sun className="text-cyan-400" size={28} />
              </div>
              <div>
                <h1 className="text-2xl font-terminal font-black text-slate-900 italic tracking-tighter leading-none">FACINDEMAIS</h1>
                <span className="text-[10px] font-black text-cyan-600 uppercase tracking-[0.4em]">Nexus Radiant</span>
              </div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-3 text-slate-400 hover:text-slate-900 bg-slate-50 rounded-2xl"><X size={24} /></button>
          </div>

          <nav className="flex-1 space-y-2 overflow-y-auto custom-scrollbar">
            {navItems.map((item) => (
              <button 
                key={item.id} 
                onClick={() => { setView(item.id as ViewState); setIsSidebarOpen(false); }} 
                className={`w-full flex items-center gap-5 px-6 py-5 rounded-[1.8rem] transition-all font-black text-[13px] tracking-wide uppercase ${view === item.id ? 'bg-slate-900 text-white shadow-[0_15px_40px_rgba(0,0,0,0.15)] scale-[1.02]' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-900'}`}
              >
                <span className={view === item.id ? 'text-cyan-400 drop-shadow-[0_0_8px_rgba(0,243,255,0.6)]' : ''}>{item.icon}</span>
                {item.label}
              </button>
            ))}

            {profile?.role === 'admin' && (
              <div className="pt-10 mt-10 border-t border-slate-100">
                <p className="px-6 text-[10px] font-black text-slate-300 uppercase tracking-widest mb-6">Master Control</p>
                <button 
                  onClick={() => { setView('ADMIN_PANEL'); setIsSidebarOpen(false); }} 
                  className={`w-full flex items-center gap-5 px-6 py-5 rounded-[1.8rem] transition-all font-black text-[13px] tracking-wide uppercase ${view === 'ADMIN_PANEL' ? 'bg-amber-400 text-slate-900 shadow-[0_15px_40px_rgba(251,191,36,0.25)]' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-900'}`}
                >
                  <UserCog size={20} /> Administração
                </button>
              </div>
            )}
          </nav>

          <div className="mt-auto pt-10 border-t border-slate-50">
            <div className="bg-slate-50/80 rounded-[2.5rem] p-5 flex items-center gap-4 border border-white group hover:bg-white hover:shadow-xl transition-all">
              <div className="w-12 h-12 rounded-2xl bg-slate-900 flex items-center justify-center text-cyan-400 font-terminal font-black text-xl group-hover:scale-110 transition-transform">
                {profile?.email.charAt(0).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[11px] font-black text-slate-900 truncate uppercase tracking-tighter">{profile?.email.split('@')[0]}</p>
                <button onClick={() => signOut(auth)} className="text-[10px] font-bold text-rose-500 uppercase hover:text-rose-600 transition-colors">Encerrar Fluxo</button>
              </div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-cyan-100/30 blur-[120px] rounded-full pointer-events-none -mr-40 -mt-40"></div>
        <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-purple-100/30 blur-[120px] rounded-full pointer-events-none -ml-40 -mb-40"></div>

        <header className="h-24 bg-white/40 backdrop-blur-2xl border-b border-white flex items-center justify-between px-8 lg:px-14 z-30">
          <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-4 text-slate-600 bg-white rounded-2xl shadow-sm border border-slate-100 active:scale-95"><Menu size={24} /></button>

          <div className="flex-1 flex justify-end items-center gap-10">
             <div className="hidden sm:flex flex-col items-end">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Fluxo Radiante Ativo</span>
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 bg-cyan-400 rounded-full animate-ping"></div>
                  <span className="text-sm font-black text-slate-900 uppercase italic tracking-tight">Sincronizado {profile?.plan}</span>
                </div>
             </div>
             <div className="h-10 w-px bg-slate-200/50 mx-2 hidden sm:block"></div>
             <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600">
                  <Zap size={18} fill="currentColor" />
                </div>
                <div className="hidden md:block">
                  <p className="text-[10px] font-black text-slate-400 uppercase">Latência</p>
                  <p className="text-xs font-black text-slate-800 tracking-widest">0.03ms Nexus</p>
                </div>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 lg:p-14 lg:pt-8 relative z-10 custom-scrollbar">
          <div className="max-w-[1500px] mx-auto">
            {view === 'DASHBOARD' && <DashboardView orders={orders} products={products} expenses={expenses} />}
            {view === 'PRODUCTS' && <ProductsView products={products} userId={currentUser.uid} />}
            {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={currentUser.uid} />}
            {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={currentUser.uid} />}
            {view === 'EXPENSES' && <ExpensesView expenses={expenses} userId={currentUser.uid} />}
            {view === 'AI_INSIGHTS' && <AIInsightsView orders={orders} products={products} />}
            {view === 'ADMIN_PANEL' && profile?.role === 'admin' && <AdminView />}
            {view === 'REFERRALS' && <ReferralView profile={profile!} />}
            {view === 'SETTINGS' && <SettingsView profile={profile!} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

