            >
              {isLoading ? <Loader2 className="animate-spin" /> : <ShieldCheck size={24} className="group-hover:scale-110 transition-transform" />}
              {isRecovering ? 'ENVIAR PORTAL' : isRegistering ? 'INICIALIZAR' : 'AUTENTICAR'}
            </button>
          </form>

          <div className="mt-12 flex flex-col items-center gap-6 border-t border-white/5 pt-10">
            <div className="flex justify-center gap-8">
              <button onClick={() => setIsRegistering(!isRegistering)} className="text-[11px] font-black text-cyan-400/40 hover:text-cyan-400 uppercase tracking-widest transition-all">
                {isRegistering ? 'LOGIN EXISTENTE' : 'SOLICITAR ACESSO'}
