const MASTER_ADMIN_EMAIL = "giufarlosdias@hotmail.com";

export const dbService = {
  getUserProfile: async (uid: string) => {
    try {
      const docRef = doc(db, "users", uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? docSnap.data() : null;
    } catch (e) { return null; }
  },

  createUserProfile: async (uid: string, email: string, referredByCode?: string) => {
    const isAdmin = email.toLowerCase() === MASTER_ADMIN_EMAIL.toLowerCase();
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const profile = {
      uid,
      email,
      role: isAdmin ? 'admin' : 'user',
      status: 'active',
      plan: isAdmin ? 'master' : 'pro',
      expiresAt: isAdmin ? Timestamp.fromDate(new Date(2099, 11, 31)) : Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    if (!userId) return () => {};
    const q = query(
      collection(db, collectionName), 
      where("userId", "==", userId), 
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    }, (err) => console.error(`Erro na subscrição ${collectionName}:`, err));
  },

  add: async (collectionName: string, userId: string, data: any) => {
    if (!userId) throw new Error("Usuário não autenticado");
    return await addDoc(collection(db, collectionName), { 
      ...data, 
      userId, 
      createdAt: serverTimestamp() 
    });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  },

  getAllUsers: (callback: (data: any[]) => void) => {
    return onSnapshot(query(collection(db, "users"), orderBy("createdAt", "desc")), (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  },

  deleteUser: async (uid: string) => {
    return await deleteDoc(doc(db, "users", uid));
  }
};

import React, { useState } from 'react';
