      console.error("Erro Auth:", err.code);
      let errorMsg = 'Acesso Negado: Credenciais inválidas.';

      if (err.code?.includes('api-key-not-valid') || err.code?.includes('invalid-api-key')) {
        errorMsg = 'NEXUS ERROR: Chave do Firebase inválida. Verifique a configuração.';
