            <h1 className="text-6xl font-black text-white tracking-tighter uppercase mb-2 italic text-glow-cyan leading-tight">FACINDEMAIS</h1>
            <p className="text-cyan-300 font-black tracking-[0.6em] text-[12px] uppercase opacity-90">
