                className="w-full px-8 py-6 bg-black/60 border-2 border-cyan-500/20 rounded-[2.2rem] outline-none focus:border-cyan-400 focus:bg-black/80 text-white font-bold transition-all shadow-[inset_0_2px_10px_rgba(0,243,255,0.1)] text-lg placeholder:text-slate-700"
