  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [productSearch, setProductSearch] = useState('');

  const finalizeOrder = async () => {
    if (!selectedCustomerId || cart.length === 0) return alert('Selecione cliente e itens!');
    setIsProcessing(true);
    try {
      const total = cart.reduce((s, i) => s + (i.priceAtTime * i.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId,
        items: cart,
        total,
        status,
        paymentMethod: status === 'PAID' ? paymentMethod : null,
        installments: status === 'PAID' ? installments : null
      };

      await dbService.add('orders', userId, orderData);

      if (status === 'PAID') {
        for (const item of cart) {
          const product = products.find(p => p.id === item.productId);
          if (product && product.type === 'PRODUCT') {
            await dbService.update('products', product.id, { stock: Math.max(0, product.stock - item.quantity) });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
    } catch (err) { alert("Erro ao processar."); } finally { setIsProcessing(false); }
  };

  const shareOrder = (order: Order) => {
    const customer = customers.find(c => c.id === order.customerId);
    const dateStr = order.createdAt?.toDate().toLocaleDateString('pt-BR') || new Date().toLocaleDateString('pt-BR');

    const text = 
      `📄 *${order.status === 'QUOTE' ? 'ORÇAMENTO DETALHADO' : 'RECIBO DE PAGAMENTO'}*\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `📅 *Data:* ${dateStr}\n` +
      `👤 *Cliente:* ${customer?.name || 'Consumidor Geral'}\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `📦 *ITENS DOS PEDIDO:*\n` +
      order.items.map(i => `• ${i.nameAtTime} (${i.quantity}x) - R$ ${(i.priceAtTime * i.quantity).toFixed(2)}`).join('\n') +
      `\n━━━━━━━━━━━━━━━━━━━━\n` +
      `💰 *VALOR TOTAL: R$ ${order.total.toFixed(2)}*\n` +
      (order.status === 'PAID' ? `💳 *PAGAMENTO:* ${order.paymentMethod}\n` : `⏳ *VALIDADE:* 7 dias úteis\n`) +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `⚡ _Enviado via Facindemais Cloud_`;

    const whatsappUrl = `https://wa.me/${customer?.phone?.replace(/\D/g, '')}?text=${encodeURIComponent(text)}`;
    if (customer?.phone) window.open(whatsappUrl, '_blank');
    else alert("O cliente não possui telefone cadastrado para sincronização WhatsApp.");
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-5xl font-black text-white tracking-tighter italic text-glow-cyan leading-none">Fluxos Ativos<span className="text-white">.</span></h2>
          <p className="text-slate-500 font-bold mt-4 text-xl tracking-wide uppercase opacity-70">Sincronização de vendas e propostas.</p>
        </div>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="btn-radiant px-10 py-5 rounded-[2.5rem] flex items-center gap-4 active:scale-95 transition-all group">
            <Plus size={32} className="text-black group-hover:rotate-90 transition-transform" /> 
            <span className="tracking-tight uppercase">NOVA OPERAÇÃO</span>
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12 animate-fade-in">
          <div className="lg:col-span-2 space-y-10">
            <div className="bg-[#0c0628]/80 p-8 rounded-[3rem] border-2 border-cyan-400/20 flex items-center gap-6 shadow-inner backdrop-blur-3xl focus-within:border-cyan-400 transition-all">
               <Search size={32} className="text-cyan-400/50" />
               <input placeholder="Filtrar por nome ou código Nexus..." value={productSearch} onChange={e => setProductSearch(e.target.value)} className="flex-1 bg-transparent outline-none font-black text-white placeholder:text-slate-700 text-2xl italic tracking-tight" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => {
                  setCart(prev => {
                    const ex = prev.find(i => i.productId === p.id);
                    if (ex) return prev.map(i => i.productId === p.id ? {...i, quantity: i.quantity + 1} : i);
                    return [...prev, {productId: p.id, quantity: 1, priceAtTime: p.price, nameAtTime: p.name}];
                  });
                }} className="nexus-card p-10 text-left transition-all hover:border-cyan-400 hover:scale-105 active:scale-95 group relative overflow-hidden">
                  <div className="flex justify-between items-start mb-6">
                    <div className="p-4 bg-white/5 rounded-2xl text-slate-500 group-hover:text-cyan-400 group-hover:border-cyan-400/30 border border-transparent transition-all">
                      <Cpu size={24} />
                    </div>
                    <div className="bg-cyan-400/10 px-4 py-2 rounded-xl text-[10px] font-black text-cyan-400 uppercase tracking-widest">{p.type}</div>
                  </div>
                  <h4 className="font-black text-white text-xl mb-2 truncate group-hover:text-glow-cyan">{p.name}</h4>
                  <p className="text-cyan-400 font-black text-3xl tracking-tighter italic">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card h-fit sticky top-6 border-cyan-400/40 shadow-[0_0_80px_rgba(0,243,255,0.1)] overflow-hidden">
            <div className="p-10 border-b border-white/5 flex justify-between items-center bg-white/5">
               <h3 className="font-terminal font-black text-2xl flex items-center gap-4 italic text-glow-cyan">CHECKOUT</h3>
               <button onClick={() => setIsCreating(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-500 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>
            <div className="p-10 space-y-10 overflow-y-auto max-h-[60vh] custom-scrollbar">
               <div className="space-y-4">
                  <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest block ml-2">Modo de Operação</label>
                  <div className="flex p-2 bg-black/40 rounded-[2rem] border border-white/5 shadow-inner">
                     <button onClick={() => setStatus('PAID')} className={`flex-1 py-5 rounded-2xl text-xs font-black tracking-widest transition-all ${status === 'PAID' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>VENDA PAGA</button>
                     <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-5 rounded-2xl text-xs font-black tracking-widest transition-all ${status === 'QUOTE' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>ORÇAMENTO</button>
                  </div>
               </div>

               <div className="space-y-4">
                  <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest block ml-2">Operador/Cliente</label>
                  <select className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-black italic outline-none focus:border-cyan-400 transition-all text-lg appearance-none" value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)}>
                    <option value="" className="bg-[#0c0628]">BUSCAR NA REDE...</option>
                    {customers.map(c => <option key={c.id} value={c.id} className="bg-[#0c0628]">{c.name}</option>)}
                  </select>
               </div>

               {cart.length > 0 && (
                 <div className="space-y-6 pt-6">
                   <p className="text-[11px] font-black text-cyan-400 uppercase tracking-widest block ml-2">Carga Selecionada</p>
                   {cart.map(item => (
                     <div key={item.productId} className="flex justify-between items-center p-6 bg-black/40 rounded-3xl border border-white/5">
                       <div className="flex-1 min-w-0 pr-6">
                         <p className="font-black text-white text-base truncate">{item.nameAtTime}</p>
                         <p className="text-xs font-black text-cyan-400 tracking-tighter italic">{item.quantity}x R$ {item.priceAtTime.toFixed(2)}</p>
                       </div>
                       <button onClick={() => setCart(prev => prev.filter(i => i.productId !== item.productId))} className="p-3 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all"><Trash2 size={20}/></button>
                     </div>
                   ))}
                 </div>
               )}

               <div className="pt-10 border-t border-white/5">
                  <div className="flex justify-between items-end mb-10">
                     <div>
                       <span className="text-slate-500 text-[11px] font-black uppercase tracking-widest block mb-2">Total Final</span>
                       <span className="text-xs font-black text-cyan-400 opacity-60 uppercase tracking-widest">{cart.length} ITENS EM BUFFER</span>
                     </div>
                     <span className="text-5xl font-black text-white tracking-tighter italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                  </div>
                  <button disabled={isProcessing || cart.length === 0} onClick={finalizeOrder} className="btn-radiant w-full py-8 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50">
                     {isProcessing ? <Loader2 className="animate-spin" size={28} /> : <Zap size={32} className="text-black" />}
                     {status === 'PAID' ? 'FINALIZAR SINCRONIA' : 'EMITIR PROPOSTA'}
                  </button>
               </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="nexus-card overflow-hidden shadow-2xl border-white/5">
          <table className="w-full text-left min-w-[900px]">
            <thead>
              <tr className="bg-white/5">
                <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Status</th>
                <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Entidade</th>
                <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60 text-center">Volume Total</th>
                <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60 text-right">Controle</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {orders.map(o => (
                <tr key={o.id} className="hover:bg-white/5 transition-all group">
                  <td className="px-10 py-10">
                     <span className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${o.status === 'QUOTE' ? 'bg-amber-500/10 text-amber-500 border border-amber-500/30' : 'bg-cyan-400/10 text-cyan-400 border border-cyan-400/30 shadow-[0_0_15px_rgba(0,243,255,0.1)]'}`}>
                       {o.status === 'QUOTE' ? 'ORÇAMENTO' : 'SINCRONIZADO'}
                     </span>
                  </td>
                  <td className="px-10 py-10">
                    <p className="font-black text-white text-2xl italic tracking-tighter text-glow-cyan opacity-80 group-hover:opacity-100">{customers.find(c => c.id === o.customerId)?.name || 'CONSUMIDOR GERAL'}</p>
                    <p className="text-[11px] font-black text-slate-600 uppercase tracking-widest mt-1">NEXUS ID: {o.id.substring(0,8)}</p>
                  </td>
