const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const unsubAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        let userProfile = await dbService.getUserProfile(user.uid);
        if (!userProfile) {
          userProfile = await dbService.createUserProfile(user.uid, user.email || '');
        }
        setProfile(userProfile as UserProfile);
        setCurrentUser(user);
      } else {
        setCurrentUser(null);
        setProfile(null);
      }
      setIsLoading(false);
    });
    return () => unsubAuth();
  }, []);

  useEffect(() => {
    if (!currentUser || !profile) return;
    const uid = currentUser.uid;
    const unsubProducts = dbService.subscribe('products', uid, (data) => setProducts(data as Product[]));
    const unsubCustomers = dbService.subscribe('customers', uid, (data) => setCustomers(data as Customer[]));
    const unsubExpenses = dbService.subscribe('expenses', uid, (data) => setExpenses(data as Expense[]));
    const unsubOrders = dbService.subscribe('orders', uid, (data) => setOrders(data as Order[]));
    return () => { unsubProducts(); unsubCustomers(); unsubOrders(); unsubExpenses(); };
  }, [currentUser, profile]);

  const navItems = [
    { id: 'DASHBOARD', label: 'Painel Nexus', icon: <LayoutDashboard size={22} /> },
    { id: 'PRODUCTS', label: 'Inventário', icon: <Package size={22} /> },
    { id: 'CUSTOMERS', label: 'Rede Clientes', icon: <Users size={22} /> },
    { id: 'ORDERS', label: 'Operações', icon: <ShoppingCart size={22} /> },
    { id: 'EXPENSES', label: 'Fluxo Saída', icon: <WalletMinimal size={22} /> },
    { id: 'AI_INSIGHTS', label: 'Núcleo AI', icon: <Sparkles size={22} /> },
    { id: 'REFERRALS', label: 'Recompensas', icon: <Gift size={22} /> },
    { id: 'SETTINGS', label: 'Segurança', icon: <Settings size={22} /> },
  ];

  if (isLoading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d] relative">
        <div className="absolute inset-0 grid-bg opacity-20"></div>
        <div className="scanline"></div>
        <div className="relative z-10 flex flex-col items-center">
          <div className="w-24 h-24 bg-cyan-400 rounded-[2rem] flex items-center justify-center shadow-[0_0_50px_rgba(0,243,255,0.4)] animate-bounce mb-8">
            <Sun size={48} className="text-black" />
          </div>
