import { GoogleGenAI } from "@google/genai";
import { Order, Product } from "../types";

// Always use process.env.API_KEY and correct initialization format
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getSalesInsights(orders: Order[], products: Product[]) {
  const prompt = `
    Analise os seguintes dados de vendas e forneça 3-5 insights de negócios acionáveis e curtos em Português.
    Vendas: ${JSON.stringify(orders.slice(-20))}
    Produtos: ${JSON.stringify(products)}
    Seja direto, luminoso e use tom de autoridade tecnológica.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { temperature: 0.8 }
    });
    // Fix: Access .text property directly (do not use .text())
    return response.text || "Dados insuficientes para processamento.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Falha na conexão com o núcleo AI.";
  }
}

export async function generateProductDescription(productName: string) {
  const prompt = `Crie uma descrição de venda futurista e impactante para o produto: ${productName}. Máximo 2 parágrafos.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    // Fix: Access .text property directly
    return response.text;
  } catch (error) {
    return "Descrição gerada pelo sistema indisponível.";
  }
}

