const MASTER_ADMIN_EMAIL = "giufarlosdias@hotmail.com";

export const dbService = {
  getUserProfile: async (uid: string) => {
    try {
      const docRef = doc(db, "users", uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? docSnap.data() : null;
    } catch (e) { return null; }
  },

  createUserProfile: async (uid: string, email: string) => {
    const isSuper = email.toLowerCase() === MASTER_ADMIN_EMAIL.toLowerCase();
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const profile = {
      uid,
      email,
      role: isSuper ? 'super-admin' : 'user',
      status: 'active',
      plan: isSuper ? 'master' : 'pro',
      expiresAt: isSuper ? Timestamp.fromDate(new Date(2099, 11, 31)) : Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    if (!userId) return () => {};
    const q = query(
      collection(db, collectionName), 
      where("userId", "==", userId), 
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    }, (error) => {
      console.error(`Erro na subscrição de ${collectionName}:`, error);
    });
  },

  add: async (collectionName: string, userId: string, data: any) => {
    return await addDoc(collection(db, collectionName), { 
      ...data, 
      userId, 
      createdAt: serverTimestamp() 
    });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  },

  // FUNÇÕES DE SUPER ADMIN
  getAllUsers: (callback: (data: any[]) => void) => {
    const q = query(collection(db, "users"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  },

  deleteUser: async (uid: string) => {
    return await deleteDoc(doc(db, "users", uid));
  }
};

import { GoogleGenAI } from "@google/genai";
import { Order, Product } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getSalesInsights(orders: Order[], products: Product[]) {
  if (orders.length === 0) return "Nenhum dado de venda para analisar.";

  const prompt = `
    Como um analista de negócios cibernético, analise:
    Vendas recentes: ${JSON.stringify(orders.slice(0, 10))}
    Estoque atual: ${JSON.stringify(products)}
    Forneça 3 insights estratégicos curtos e em Português sobre o desempenho.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text || "O núcleo AI está processando novas frequências.";
  } catch (error) {
    console.error("Erro Gemini:", error);
    return "Falha na conexão neural com o núcleo AI.";
  }
}

