import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Cpu, CreditCard, Clock } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [search, setSearch] = useState('');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, {
        productId: product.id,
        quantity: 1,
        priceAtTime: product.price,
        nameAtTime: product.name
      }];
    });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Selecione itens.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: paymentMethod === 'DEFERRED' ? 'PENDING' : status,
        paymentMethod,
        installments: paymentMethod === 'CASH' ? 1 : installments
      };

      await dbService.add('orders', userId, orderData);

      if (status !== 'QUOTE') {
        for (const item of cart) {
          const prod = products.find(p => p.id === item.productId);
          if (prod && prod.type === 'PRODUCT') {
            await dbService.update('products', prod.id, { stock: Math.max(0, prod.stock - item.quantity) });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
    } catch (e) {
      alert('Erro ao processar venda.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Fluxo de Vendas</h2>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-4 rounded-2xl flex items-center gap-3">
            <Plus size={24} /> NOVA OPERAÇÃO
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-[#0c0628]/80 p-6 rounded-3xl border border-white/5 flex items-center gap-4">
              <Search className="text-cyan-400" />
              <input 
                placeholder="Localizar item..." 
                className="bg-transparent flex-1 outline-none text-white font-bold" 
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {filteredProducts.map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-6 text-left hover:scale-[1.02] transition-all group">
                   <div className="flex justify-between mb-4">
                     <div className="p-3 bg-white/5 rounded-xl text-cyan-400"><Cpu size={20}/></div>
                     <span className="text-[8px] font-black text-cyan-400 uppercase tracking-widest">{p.type}</span>
                   </div>
                   <p className="font-black text-white truncate text-lg group-hover:text-cyan-400 transition-colors">{p.name}</p>
                   <p className="text-cyan-400 font-black text-2xl tracking-tighter">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-8 h-fit sticky top-6">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/5">
              <h3 className="font-terminal font-black text-xl text-glow-cyan uppercase">CHECKOUT</h3>
              <button onClick={() => setIsCreating(false)} className="text-slate-500 hover:text-rose-500"><X /></button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Documento</label>
                <div className="flex gap-2 p-1 bg-black/40 rounded-xl border border-white/5">
                  <button onClick={() => setStatus('PAID')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'PAID' ? 'bg-cyan-400 text-black' : 'text-slate-500'}`}>VENDA</button>
                  <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'QUOTE' ? 'bg-cyan-400 text-black' : 'text-slate-500'}`}>ORÇAMENTO</button>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Cliente</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white font-bold outline-none focus:border-cyan-400">
                  <option value="">CONSUMIDOR FINAL</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => setPaymentMethod('PIX')} className={`p-3 rounded-xl border flex flex-col items-center gap-1 ${paymentMethod === 'PIX' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}><Smartphone size={16}/> <span className="text-[8px] font-black">PIX</span></button>
                  <button onClick={() => setPaymentMethod('CREDIT_CARD')} className={`p-3 rounded-xl border flex flex-col items-center gap-1 ${paymentMethod === 'CREDIT_CARD' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}><CreditCard size={16}/> <span className="text-[8px] font-black">CARTÃO</span></button>
                  <button onClick={() => setPaymentMethod('CASH')} className={`p-3 rounded-xl border flex flex-col items-center gap-1 ${paymentMethod === 'CASH' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}><Zap size={16}/> <span className="text-[8px] font-black">DINHEIRO</span></button>
                  <button onClick={() => setPaymentMethod('DEFERRED')} className={`p-3 rounded-xl border flex flex-col items-center gap-1 ${paymentMethod === 'DEFERRED' ? 'border-rose-500 text-rose-500 bg-rose-500/10' : 'border-white/5 text-slate-500'}`}><Clock size={16}/> <span className="text-[8px] font-black">A PRAZO</span></button>
                </div>
              </div>

              <div className="pt-6 border-t border-white/5 space-y-4">
                {cart.map(item => (
                  <div key={item.productId} className="flex justify-between items-center bg-black/40 p-3 rounded-xl border border-white/5 text-xs font-bold">
                    <span className="truncate flex-1 pr-2 text-white">{item.nameAtTime}</span>
                    <span className="text-cyan-400">{item.quantity}x</span>
                    <button onClick={() => setCart(prev => prev.filter(i => i.productId !== item.productId))} className="ml-3 text-rose-500"><Trash2 size={14}/></button>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                  <span className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Total</span>
                  <span className="text-3xl font-black text-white italic tracking-tighter">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-2xl font-black text-sm flex items-center justify-center gap-3 active:scale-95 disabled:opacity-30">
                  {isProcessing ? <Loader2 className="animate-spin"/> : status === 'QUOTE' ? 'GERAR ORÇAMENTO' : 'EFETIVAR VENDA'}
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="nexus-card overflow-x-auto shadow-xl">
           <table className="w-full text-left min-w-[800px]">
             <thead>
               <tr className="border-b border-white/5">
                 <th className="px-8 py-6 text-[10px] font-black text-cyan-400 uppercase tracking-widest">Status</th>
                 <th className="px-8 py-6 text-[10px] font-black text-cyan-400 uppercase tracking-widest">Entidade</th>
                 <th className="px-8 py-6 text-[10px] font-black text-cyan-400 uppercase tracking-widest">Valor</th>
                 <th className="px-8 py-6 text-[10px] font-black text-cyan-400 uppercase tracking-widest text-right">Controle</th>
               </tr>
             </thead>
             <tbody>
               {orders.map(o => (
                 <tr key={o.id} className="hover:bg-white/5 transition-all">
                   <td className="px-8 py-6">
                     <span className={`px-4 py-1.5 rounded-lg text-[8px] font-black uppercase border ${o.status === 'PAID' ? 'bg-cyan-400/10 text-cyan-400 border-cyan-400/20' : 'bg-rose-500/10 text-rose-500 border-rose-500/20'}`}>
                       {o.status}
                     </span>
                   </td>
                   <td className="px-8 py-6">
                     <p className="font-black text-white text-lg italic tracking-tight">{customers.find(c => c.id === o.customerId)?.name || 'CONSM. FINAL'}</p>
                     <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">MODO: {o.paymentMethod || 'N/A'}</p>
                   </td>
                   <td className="px-8 py-6 font-black text-white text-2xl tracking-tighter italic">R$ {o.total.toFixed(2)}</td>
                   <td className="px-8 py-6 text-right">
                     <button className="text-cyan-400 hover:underline text-[10px] font-black uppercase tracking-widest">Detalhes</button>
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
        </div>
      )}
    </div>
  );
};

