export const dbService = {
  getUserProfile: async (uid: string) => {
    try {
      const docRef = doc(db, "users", uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? docSnap.data() : null;
    } catch (e) { return null; }
  },

  createUserProfile: async (uid: string, email: string) => {
    const isSuper = email.toLowerCase() === MASTER_ADMIN_EMAIL.toLowerCase();
    const trialDate = new Date();
    trialDate.setDate(trialDate.getDate() + 7);

    const profile = {
      uid,
      email,
      role: isSuper ? 'super-admin' : 'user',
      status: 'active',
      plan: isSuper ? 'master' : 'pro',
      expiresAt: isSuper ? Timestamp.fromDate(new Date(2099, 11, 31)) : Timestamp.fromDate(trialDate),
      createdAt: serverTimestamp(),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referralCount: 0,
      referralBalance: 0
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  subscribe: (collectionName: string, userId: string, callback: (data: any[]) => void) => {
    if (!userId) return () => {};
    const q = query(
      collection(db, collectionName), 
      where("userId", "==", userId), 
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  add: async (collectionName: string, userId: string, data: any) => {
    return await addDoc(collection(db, collectionName), { 
      ...data, 
      userId, 
      createdAt: serverTimestamp() 
    });
  },

  update: async (collectionName: string, id: string, data: any) => {
    return await updateDoc(doc(db, collectionName, id), { ...data, updatedAt: serverTimestamp() });
  },

  delete: async (collectionName: string, id: string) => {
    return await deleteDoc(doc(db, collectionName, id));
  },

  getAllUsers: (callback: (data: any[]) => void) => {
    const q = query(collection(db, "users"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
      callback(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
  },

  updateUser: async (uid: string, data: any) => {
    return await updateDoc(doc(db, "users", uid), data);
  },

  deleteUser: async (uid: string) => {
    return await deleteDoc(doc(db, "users", uid));
  }
};

import { GoogleGenAI } from "@google/genai";
import { Order, Product } from "../types";

export async function getSalesInsights(orders: Order[], products: Product[]) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (orders.length === 0) return "### Matriz de Dados Vazia\nSincronize as primeiras operações para habilitar o processamento preditivo.";

  const prompt = `
    Aja como o Nexus AI, um consultor de negócios cibernético de alto nível.
    Analise os seguintes dados:
    Vendas Recentes: ${JSON.stringify(orders.slice(0, 15))}
    Inventário Atual: ${JSON.stringify(products)}

    Forneça um relatório dividido em:
    1. Performance de Fluxo (Como estão as vendas)
    2. Alertas de Escassez (O que precisa repor)
    3. Sugestão Estratégica Nexus (Uma ação para aumentar lucro)
    Use Markdown e linguagem futurista/profissional.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Failure:", error);
    return "Falha na conexão neural com o núcleo AI. Verifique as credenciais da API.";
  }
}

import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Cpu, CreditCard, Clock, FileText } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [search, setSearch] = useState('');

  const addToCart = (product: Product) => {
    if (product.type === 'PRODUCT' && product.stock <= 0) {
      alert("Estoque esgotado para este item!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, {
        productId: product.id,
        quantity: 1,
        priceAtTime: product.price,
        nameAtTime: product.name
      }];
    });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Selecione itens para continuar.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: status === 'QUOTE' ? 'QUOTE' : (paymentMethod === 'DEFERRED' ? 'PENDING' : 'PAID'),
        paymentMethod,
        createdAt: new Date()
      };

      await dbService.add('orders', userId, orderData);

      // Baixa de estoque apenas para vendas reais (não orçamentos)
      if (status === 'PAID') {
        for (const item of cart) {
          const prod = products.find(p => p.id === item.productId);
          if (prod && prod.type === 'PRODUCT') {
            await dbService.update('products', prod.id, { 
              stock: Math.max(0, prod.stock - item.quantity) 
            });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      alert("Operação sincronizada com sucesso!");
    } catch (e) {
      alert('Erro crítico ao processar transação.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none">Fluxo de Vendas</h2>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-5 rounded-2xl flex items-center gap-4 transition-all active:scale-95">
            <Plus size={24} /> NOVA OPERAÇÃO
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-[#0c0628]/80 p-6 rounded-3xl border border-cyan-400/20 flex items-center gap-4 shadow-lg focus-within:border-cyan-400 transition-all">
              <Search className="text-cyan-400" />
              <input 
                placeholder="Escanear ou digitar item..." 
                className="bg-transparent flex-1 outline-none text-white font-bold text-xl" 
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[600px] overflow-y-auto custom-scrollbar pr-2">
              {filteredProducts.map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-6 text-left hover:scale-[1.02] transition-all group border-white/5 hover:border-cyan-400/50">
                   <div className="flex justify-between mb-4">
                     <div className="p-3 bg-white/5 rounded-xl text-cyan-400 group-hover:text-white transition-colors"><Cpu size={24}/></div>
                     <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg ${p.type === 'SERVICE' ? 'bg-cyan-400/10 text-cyan-400' : 'bg-purple-500/10 text-purple-400'}`}>{p.type}</span>
                   </div>
                   <p className="font-black text-white truncate text-xl mb-1 group-hover:text-glow-cyan transition-all">{p.name}</p>
                   <p className="text-cyan-400 font-black text-2xl tracking-tighter">R$ {p.price.toFixed(2)}</p>
                   {p.type === 'PRODUCT' && <p className="text-[10px] font-bold text-slate-500 mt-2">ESTOQUE: {p.stock} UN</p>}
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-8 h-fit sticky top-6 border-cyan-400/30">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/5">
              <h3 className="font-terminal font-black text-xl text-glow-cyan uppercase">CHECKOUT</h3>
              <button onClick={() => setIsCreating(false)} className="text-slate-500 hover:text-rose-500 transition-colors"><X size={28}/></button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Tipo de Registro</label>
                <div className="flex gap-2 p-1 bg-black/40 rounded-xl border border-white/5">
                  <button onClick={() => setStatus('PAID')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'PAID' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>EFETIVAR VENDA</button>
                  <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'QUOTE' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>ORÇAMENTO</button>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Rede de Clientes</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white font-bold outline-none focus:border-cyan-400 appearance-none">
                  <option value="" className="bg-[#0c0628]">CONSUMIDOR FINAL</option>
                  {customers.map(c => <option key={c.id} value={c.id} className="bg-[#0c0628]">{c.name}</option>)}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Método de Fluxo</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => setPaymentMethod('PIX')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'PIX' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500 hover:border-white/20'}`}><Smartphone size={18}/> <span className="text-[9px] font-black">PIX</span></button>
                  <button onClick={() => setPaymentMethod('CREDIT_CARD')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'CREDIT_CARD' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500 hover:border-white/20'}`}><CreditCard size={18}/> <span className="text-[9px] font-black">CARTÃO</span></button>
                  <button onClick={() => setPaymentMethod('CASH')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'CASH' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500 hover:border-white/20'}`}><Zap size={18}/> <span className="text-[9px] font-black">DINHEIRO</span></button>
                  <button onClick={() => setPaymentMethod('DEFERRED')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'DEFERRED' ? 'border-rose-500 text-rose-500 bg-rose-500/10' : 'border-white/5 text-slate-500 hover:border-rose-500/30'}`}><Clock size={18}/> <span className="text-[9px] font-black uppercase">A PRAZO</span></button>
                </div>
              </div>

              <div className="pt-4 space-y-3 max-h-[250px] overflow-y-auto custom-scrollbar">
                {cart.map(item => (
                  <div key={item.productId} className="flex justify-between items-center bg-black/40 p-4 rounded-xl border border-white/5 text-sm font-bold animate-fade-in">
                    <div className="flex-1 truncate pr-3">
                      <p className="text-white truncate">{item.nameAtTime}</p>
                      <p className="text-[10px] text-cyan-400/60 uppercase">R$ {item.priceAtTime.toFixed(2)} un</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-cyan-400 font-black">{item.quantity}x</span>
                      <button onClick={() => setCart(prev => prev.filter(i => i.productId !== item.productId))} className="text-rose-500 hover:scale-110 transition-transform"><Trash2 size={16}/></button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-8">
                   <span className="text-slate-500 text-[11px] font-black uppercase tracking-widest">Total Líquido</span>
                   <span className="text-4xl font-black text-white italic tracking-tighter text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button 
                  disabled={isProcessing || cart.length === 0} 
                  onClick={finalize} 
                  className="btn-radiant w-full py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 disabled:opacity-30 disabled:pointer-events-none"
                >
                  {isProcessing ? <Loader2 className="animate-spin" size={24}/> : (status === 'QUOTE' ? <FileText size={24}/> : <Zap size={24}/>)}
                  {status === 'QUOTE' ? 'GERAR DOCUMENTO' : 'SINCRONIZAR VENDA'}
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="nexus-card overflow-x-auto shadow-2xl">
           <table className="w-full text-left min-w-[900px]">
             <thead>
               <tr className="border-b border-white/5 bg-white/5">
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Identificador</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Status Fluxo</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Entidade/Cliente</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Valor Operação</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest text-right">Ações</th>
               </tr>
