import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Cpu, CreditCard, Clock, FileText } from 'lucide-react';
import { Order, Product, Customer, OrderItem } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [search, setSearch] = useState('');

  const addToCart = (product: Product) => {
    if (product.type === 'PRODUCT' && product.stock <= 0) {
      alert("Estoque esgotado para este item!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, {
        productId: product.id,
        quantity: 1,
        priceAtTime: product.price,
        nameAtTime: product.name
      }];
    });
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Selecione itens para continuar.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: status === 'QUOTE' ? 'QUOTE' : (paymentMethod === 'DEFERRED' ? 'PENDING' : 'PAID'),
        paymentMethod,
        createdAt: new Date()
      };

      await dbService.add('orders', userId, orderData);

      // Baixa de estoque apenas para vendas reais (não orçamentos)
      if (status === 'PAID') {
        for (const item of cart) {
          const prod = products.find(p => p.id === item.productId);
          if (prod && prod.type === 'PRODUCT') {
            await dbService.update('products', prod.id, { 
              stock: Math.max(0, prod.stock - item.quantity) 
            });
          }
        }
      }

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      alert("Operação sincronizada com sucesso!");
    } catch (e) {
      alert('Erro crítico ao processar transação.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none">Fluxo de Vendas</h2>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-5 rounded-2xl flex items-center gap-4 transition-all active:scale-95">
            <Plus size={24} /> NOVA OPERAÇÃO
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-[#0c0628]/80 p-6 rounded-3xl border border-cyan-400/20 flex items-center gap-4 shadow-lg focus-within:border-cyan-400 transition-all">
