            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Tipo de Registro</label>
                <div className="flex gap-2 p-1 bg-black/40 rounded-xl border border-white/5">
                  <button onClick={() => setStatus('PAID')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'PAID' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>EFETIVAR VENDA</button>
                  <button onClick={() => setStatus('QUOTE')} className={`flex-1 py-3 rounded-lg text-[9px] font-black transition-all ${status === 'QUOTE' ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20' : 'text-slate-500'}`}>ORÇAMENTO</button>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Rede de Clientes</label>
