              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Método de Fluxo</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => setPaymentMethod('PIX')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'PIX' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500 hover:border-white/20'}`}><Smartphone size={18}/> <span className="text-[9px] font-black">PIX</span></button>
                  <button onClick={() => setPaymentMethod('CREDIT_CARD')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'CREDIT_CARD' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500 hover:border-white/20'}`}><CreditCard size={18}/> <span className="text-[9px] font-black">CARTÃO</span></button>
