                  <button onClick={() => setPaymentMethod('DEFERRED')} className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all ${paymentMethod === 'DEFERRED' ? 'border-rose-500 text-rose-500 bg-rose-500/10' : 'border-white/5 text-slate-500 hover:border-rose-500/30'}`}><Clock size={18}/> <span className="text-[9px] font-black uppercase">A PRAZO</span></button>
                </div>
              </div>

              <div className="pt-4 space-y-3 max-h-[250px] overflow-y-auto custom-scrollbar">
                {cart.map(item => (
                  <div key={item.productId} className="flex justify-between items-center bg-black/40 p-4 rounded-xl border border-white/5 text-sm font-bold animate-fade-in">
                    <div className="flex-1 truncate pr-3">
                      <p className="text-white truncate">{item.nameAtTime}</p>
                      <p className="text-[10px] text-cyan-400/60 uppercase">R$ {item.priceAtTime.toFixed(2)} un</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-cyan-400 font-black">{item.quantity}x</span>
                      <button onClick={() => setCart(prev => prev.filter(i => i.productId !== item.productId))} className="text-rose-500 hover:scale-110 transition-transform"><Trash2 size={16}/></button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-8">
                   <span className="text-slate-500 text-[11px] font-black uppercase tracking-widest">Total Líquido</span>
                   <span className="text-4xl font-black text-white italic tracking-tighter text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button 
                  disabled={isProcessing || cart.length === 0} 
                  onClick={finalize} 
                  className="btn-radiant w-full py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 disabled:opacity-30 disabled:pointer-events-none"
                >
                  {isProcessing ? <Loader2 className="animate-spin" size={24}/> : (status === 'QUOTE' ? <FileText size={24}/> : <Zap size={24}/>)}
                  {status === 'QUOTE' ? 'GERAR DOCUMENTO' : 'SINCRONIZAR VENDA'}
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="nexus-card overflow-x-auto shadow-2xl">
           <table className="w-full text-left min-w-[900px]">
             <thead>
               <tr className="border-b border-white/5 bg-white/5">
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Identificador</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Status Fluxo</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Entidade/Cliente</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest">Valor Operação</th>
                 <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-white/5">
               {orders.map(o => (
                 <tr key={o.id} className="hover:bg-white/5 transition-all group">
                   <td className="px-10 py-8 font-mono text-[10px] text-slate-500">#{o.id.substring(0,8).toUpperCase()}</td>
                   <td className="px-10 py-8">
                     <span className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase border ${o.status === 'PAID' ? 'bg-cyan-400/10 text-cyan-400 border-cyan-400/30' : o.status === 'PENDING' ? 'bg-amber-500/10 text-amber-500 border-amber-500/30' : 'bg-rose-500/10 text-rose-500 border-rose-500/30'}`}>
                       {o.status === 'PAID' ? 'LIQUIDADO' : o.status === 'PENDING' ? 'PENDENTE' : 'ORÇAMENTO'}
                     </span>
                   </td>
                   <td className="px-10 py-8">
                     <p className="font-black text-white text-xl italic tracking-tight">{customers.find(c => c.id === o.customerId)?.name || 'CONSM. FINAL'}</p>
                     <p className="text-[9px] font-bold text-slate-600 uppercase tracking-widest">MODALIDADE: {o.paymentMethod || 'N/A'}</p>
                   </td>
                   <td className="px-10 py-8 font-black text-white text-3xl tracking-tighter italic">R$ {o.total.toFixed(2)}</td>
                   <td className="px-10 py-8 text-right">
                     <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button className="p-3 text-cyan-400 bg-cyan-400/10 rounded-xl hover:bg-cyan-400 hover:text-black transition-all font-black text-[10px] tracking-widest uppercase">DETALHES</button>
                        {/* Fix: use dbService.del instead of dbService.delete */}
                        <button onClick={() => { if(confirm('Remover registro?')) dbService.del('orders', o.id) }} className="p-3 text-rose-500 hover:bg-rose-500 hover:text-white rounded-xl transition-all"><Trash2 size={18}/></button>
                     </div>
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
           {orders.length === 0 && (
             <div className="py-40 text-center">
                <ShoppingCart size={80} className="text-white/5 mx-auto mb-8" />
                <p className="text-slate-700 font-black uppercase tracking-[0.4em] italic text-sm">Nenhum fluxo de venda detectado.</p>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState } from 'react';
import { Plus, WalletMinimal, Trash2, X, Loader2, Zap } from 'lucide-react';
import { Expense } from '../types';
import { dbService } from '../services/firebase';

interface ExpensesViewProps {
  expenses: Expense[];
  userId: string;
}

const ExpensesView: React.FC<ExpensesViewProps> = ({ expenses, userId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ description: '', amount: '', category: 'Operacional' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await dbService.add('expenses', userId, {
        description: formData.description,
        amount: parseFloat(formData.amount),
        category: formData.category
      });
      setIsModalOpen(false);
      setFormData({ description: '', amount: '', category: 'Operacional' });
    } catch (err) { alert("Erro ao salvar."); } finally { setIsSaving(false); }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-5xl font-black text-white tracking-tighter italic text-glow-cyan leading-none">Fluxos de Saída<span className="text-white">.</span></h2>
          <p className="text-slate-500 font-bold mt-4 text-xl tracking-wide uppercase opacity-70">Monitoramento de custos e manutenção do sistema.</p>
        </div>
        <button onClick={() => setIsModalOpen(true)} className="bg-rose-500 text-white px-10 py-5 rounded-[2.5rem] font-black flex items-center gap-4 shadow-[0_0_30px_rgba(244,63,94,0.4)] hover:bg-rose-400 transition-all active:scale-95 text-lg">
          <Plus size={32} /> REGISTRAR CUSTO
        </button>
      </div>

      <div className="nexus-card overflow-hidden shadow-2xl border-white/5">
        <table className="w-full text-left min-w-[800px]">
          <thead>
            <tr className="bg-white/5">
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Descrição da Operação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Classificação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Drenagem de Crédito</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60 text-right">Ação</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {expenses.map(exp => (
              <tr key={exp.id} className="hover:bg-white/5 transition-all group">
                <td className="px-10 py-10 font-black text-white text-2xl italic tracking-tighter">{exp.description}</td>
                <td className="px-10 py-10">
                  <span className="text-[10px] font-black px-5 py-2.5 rounded-2xl bg-white/5 text-slate-400 border border-white/10 uppercase tracking-[0.2em]">{exp.category}</span>
                </td>
                <td className="px-10 py-10 font-black text-rose-500 text-3xl tracking-tighter italic">R$ {exp.amount.toFixed(2)}</td>
                <td className="px-10 py-10 text-right">
                  {/* Fix: use dbService.del instead of dbService.delete */}
                  <button onClick={() => { if(confirm('Excluir?')) dbService.del('expenses', exp.id) }} className="p-4 text-slate-500 hover:text-rose-500 hover:bg-rose-500/10 rounded-2xl transition-all opacity-0 group-hover:opacity-100"><Trash2 size={24} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {expenses.length === 0 && (
           <div className="py-40 text-center flex flex-col items-center">
              <div className="w-28 h-28 bg-white/5 rounded-[3rem] border-2 border-dashed border-white/10 flex items-center justify-center text-slate-700 mb-10">
                <WalletMinimal size={48} />
              </div>
              <p className="text-slate-500 font-black text-xl uppercase tracking-widest opacity-40 italic">Nenhuma drenagem de crédito detectada no ciclo.</p>
           </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-xl p-12 animate-fade-in border-rose-500/40">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-3xl font-black text-white italic text-rose-500 uppercase">Novo Registro de Custo</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-400 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>
            <form onSubmit={handleSave} className="space-y-8">
              <input required value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-rose-500 transition-all text-xl" placeholder="Especificação do Gasto" />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Créditos R$</label>
                  <input required type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold outline-none focus:border-rose-500 transition-all text-xl" />
                </div>
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Protocolo</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-black italic outline-none focus:border-rose-500 transition-all text-lg appearance-none">
                    <option className="bg-[#0c0628]">OPERACIONAL</option>
                    <option className="bg-[#0c0628]">MANUTENÇÃO</option>
                    <option className="bg-[#0c0628]">MARKETING</option>
                    <option className="bg-[#0c0628]">INFRAESTRUTURA</option>
                    <option className="bg-[#0c0628]">OUTROS</option>
                  </select>
                </div>
              </div>
              <button disabled={isSaving} type="submit" className="w-full bg-rose-500 text-white py-8 rounded-[2.5rem] font-black text-xl shadow-[0_0_40px_rgba(244,63,94,0.4)] hover:bg-rose-400 transition-all mt-8 flex items-center justify-center gap-4">
                {isSaving ? <Loader2 className="animate-spin" size={28} /> : <Zap size={28} className="fill-current" />}
                CONFIRMAR DRENAGEM
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExpensesView;

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { UserProfile } from '../types';
import { Search, Loader2, RefreshCw, Trash2, ShieldAlert, UserCheck, Ban, Calendar } from 'lucide-react';
import { Timestamp } from 'firebase/firestore';

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const unsub = dbService.getAllUsers((data) => {
      setUsers(data as UserProfile[]);
      setIsLoading(false);
    });
    return () => unsub();
  }, []);

  const handleToggleBlock = async (user: UserProfile) => {
    const newStatus = user.status === 'blocked' ? 'active' : 'blocked';
    if(confirm(`Deseja alterar o status de ${user.email} para ${newStatus}?`)) {
      // Fix: use dbService.update('users', ...) instead of dbService.updateUser
      await dbService.update('users', user.uid, { status: newStatus });
    }
  };

  const handleExtendTrial = async (user: UserProfile) => {
    const newDate = new Date();
    newDate.setMonth(newDate.getMonth() + 1);
    if(confirm(`Estender acesso de ${user.email} por +30 dias?`)) {
      // Fix: use dbService.update('users', ...) instead of dbService.updateUser
      await dbService.update('users', user.uid, { expiresAt: Timestamp.fromDate(newDate) });
    }
  };

  const filteredUsers = users.filter(u => u.email.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-10 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-rose-500 rounded-2xl flex items-center justify-center shadow-lg shadow-rose-500/30">
            <ShieldAlert size={32} className="text-white" />
          </div>
          <div>
            <h2 className="text-4xl font-black text-white italic tracking-tighter text-glow-rose leading-none uppercase">Console Master</h2>
            <p className="text-slate-500 font-bold text-sm tracking-wide uppercase opacity-70">Controle Global da Rede Nexus.</p>
          </div>
        </div>
        <div className="bg-white/5 px-6 py-4 rounded-2xl border border-white/10">
          <p className="text-[9px] font-black text-cyan-400 uppercase tracking-widest mb-1">Operadores Ativos</p>
          <p className="text-2xl font-black text-white italic">{users.length}</p>
        </div>
      </div>

      <div className="bg-[#1a0a2e]/80 p-6 rounded-3xl border border-rose-500/20 flex items-center gap-4">
        <Search className="text-rose-500/50" size={24} />
        <input 
          placeholder="Localizar terminal operacional..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-black text-white placeholder:text-slate-700 text-xl" 
        />
      </div>

      <div className="nexus-card overflow-hidden bg-[#0f041a]/90">
        <div className="overflow-x-auto">
          <table className="w-full text-left min-w-[900px]">
            <thead>
              <tr className="bg-rose-500/5">
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Operador</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Expiração</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-rose-400 uppercase tracking-widest opacity-60 text-right">Controle</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {isLoading ? (
                <tr><td colSpan={4} className="py-20 text-center"><Loader2 className="animate-spin mx-auto text-rose-500" /></td></tr>
              ) : filteredUsers.map(user => (
                <tr key={user.uid} className="hover:bg-rose-500/5 transition-all group">
                  <td className="px-8 py-8">
                    <p className="font-black text-white text-lg tracking-tight">{user.email}</p>
                    <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">ID: {user.uid.substring(0,10)}</p>
                  </td>
                  <td className="px-8 py-8 text-slate-400 text-sm font-bold flex items-center gap-3">
                    <Calendar size={14} className="text-rose-400/40" />
                    {user.expiresAt?.toDate().toLocaleDateString('pt-BR')}
                  </td>
                  <td className="px-8 py-8">
                     <span className={`px-4 py-1.5 rounded-lg text-[8px] font-black uppercase border ${user.status === 'active' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 'bg-rose-500/10 text-rose-500 border-rose-500/20'}`}>
                       {user.status === 'active' ? 'OPERACIONAL' : 'BLOQUEADO'}
                     </span>
                  </td>
                  <td className="px-8 py-8 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleExtendTrial(user)} className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl hover:bg-emerald-500 hover:text-black transition-all" title="Estender Acesso"><RefreshCw size={18} /></button>
                      <button onClick={() => handleToggleBlock(user)} className={`p-3 rounded-xl transition-all ${user.status === 'blocked' ? 'bg-cyan-500/10 text-cyan-500 hover:bg-cyan-500 hover:text-black' : 'bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white'}`} title="Bloquear/Desbloquear">{user.status === 'blocked' ? <UserCheck size={18} /> : <Ban size={18} />}</button>
                      {user.role !== 'super-admin' && (
                        // Fix: use dbService.del('users', ...) instead of dbService.deleteUser
                        <button onClick={() => { if(confirm('Excluir?')) dbService.del('users', user.uid) }} className="p-3 bg-white/5 text-slate-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={18} /></button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AdminView;

export interface UserProfile {
  uid: string;
  email: string;
  role: 'super-admin' | 'admin';
