export const dbService = {
  getUserProfile: async (uid: string) => {
    const snap = await getDoc(doc(db, "users", uid));
    return snap.exists() ? snap.data() : null;
  },

  initProfile: async (uid: string, email: string) => {
    const isMaster = email.toLowerCase() === MASTER_EMAIL.toLowerCase();
    const profile = {
      uid, email,
      role: isMaster ? 'super-admin' : 'admin',
      status: 'active',
      officeName: isMaster ? 'Nexus Prime' : 'Novo Escritório Virtual',
      parentId: isMaster ? null : 'MASTER_ROOT',
      createdAt: serverTimestamp(),
      subscriptionExpiresAt: Timestamp.fromDate(new Date(2099, 11, 31)),
      metrics: { totalSalesCount: 0, totalRevenue: 0, commissionEarned: 0 }
    };
    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  // Monitoramento global para o Super Admin
  watchAllOffices: (cb: (data: any[]) => void) => {
    const q = query(collection(db, "users"), where("role", "==", "admin"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  // Monitoramento de vendas (Global ou Específico)
  watchSales: (userId: string | null, cb: (data: any[]) => void) => {
    const q = userId 
      ? query(collection(db, "sales"), where("userId", "==", userId), orderBy("createdAt", "desc"))
      : query(collection(db, "sales"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  updateStatus: (uid: string, status: 'active' | 'blocked') => 
    updateDoc(doc(db, "users", uid), { status }),

  delOffice: (uid: string) => deleteDoc(doc(db, "users", uid)),

  addSale: (userId: string, amount: number, description: string) => 
    addDoc(collection(db, "sales"), { userId, amount, description, createdAt: serverTimestamp() })
};

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile } from './types';
import { 
  LayoutDashboard, Users, ShieldAlert, LogOut, 
  Zap, Building2, TrendingUp, DollarSign 
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import AdminDashboard from './views/AdminDashboard';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        if (p.status === 'blocked') {
          alert("Acesso suspenso. Entre em contato com o Super Admin.");
          await signOut(auth);
          return;
        }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_OFFICE');
      } else {
        setUser(null);
        setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-12 h-12 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(0,243,255,0.2)]"></div>
      <p className="mt-6 font-terminal text-[10px] text-cyan-400 tracking-[0.4em] uppercase">Auth Syncing...</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';

  return (
    <div className="flex h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

      <aside className="w-72 border-r border-white/5 bg-[#0c0628]/50 backdrop-blur-xl flex flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-14">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg shadow-cyan-400/20">
            <Zap size={20} className="text-black" />
          </div>
          <div>
            <span className="font-terminal font-black text-sm block glow-cyan">FACINDEMAIS</span>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">{isSuper ? 'Master Root' : 'Virtual Office'}</span>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          {isSuper ? (
            <>
              <button onClick={() => setView('MASTER_DASHBOARD')} className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-[11px] font-black uppercase tracking-wider transition-all ${view === 'MASTER_DASHBOARD' ? 'bg-cyan-400 text-black' : 'text-slate-500 hover:text-white'}`}>
                <LayoutDashboard size={18}/> Performance Global
              </button>
              <button onClick={() => setView('OFFICE_MANAGEMENT')} className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-[11px] font-black uppercase tracking-wider transition-all ${view === 'OFFICE_MANAGEMENT' ? 'bg-cyan-400 text-black' : 'text-slate-500 hover:text-white'}`}>
                <Building2 size={18}/> Escritórios Vendidos
              </button>
            </>
          ) : (
            <button onClick={() => setView('MY_OFFICE')} className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-[11px] font-black uppercase tracking-wider transition-all ${view === 'MY_OFFICE' ? 'bg-cyan-400 text-black' : 'text-slate-500 hover:text-white'}`}>
              <LayoutDashboard size={18}/> Meu Dashboard
            </button>
          )}
        </nav>

        <div className="pt-8 border-t border-white/5 space-y-4">
          <div className="px-5">
            <p className="text-[10px] font-black text-slate-600 uppercase mb-1">Logado como</p>
            <p className="text-xs font-bold text-white truncate">{profile?.email}</p>
