        <div className="max-w-7xl mx-auto">
          {view === 'MASTER_DASHBOARD' && <MasterDashboard />}
          {view === 'OFFICE_MANAGEMENT' && <OfficeManagement />}
          {view === 'MY_OFFICE' && <AdminDashboard profile={profile!} />}
