} from 'lucide-react';

const OfficeManagement: React.FC = () => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    return dbService.watchAllOffices((data) => setOffices(data as UserProfile[]));
  }, []);

  const toggleStatus = async (uid: string, currentStatus: string) => {
    const newStatus = currentStatus === 'active' ? 'blocked' : 'active';
    if (confirm(`Deseja alterar o status do escritório para: ${newStatus.toUpperCase()}?`)) {
      await dbService.updateStatus(uid, newStatus as 'active' | 'blocked');
    }
  };

  const deleteOffice = async (uid: string) => {
    if (confirm("ATENÇÃO: A exclusão é permanente e removerá todos os dados do escritório. Prosseguir?")) {
      await dbService.delOffice(uid);
    }
  };

  const filtered = offices.filter(o => 
    o.email.toLowerCase().includes(search.toLowerCase()) || 
    o.officeName.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-12 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-4xl font-black text-white italic tracking-tighter glow-cyan leading-none uppercase">Gestão de Escritórios</h2>
          <p className="text-slate-500 font-bold text-sm tracking-widest uppercase mt-4">Controle total sobre terminais secundários.</p>
        </div>
        <div className="bg-[#1a0a2e] p-2 rounded-2xl flex items-center gap-4 border border-white/5">
          <Search className="ml-4 text-slate-500" size={18} />
          <input 
            placeholder="Buscar por nome ou email..." 
            className="bg-transparent border-0 outline-none p-4 text-white font-bold w-64"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {filtered.map(office => (
          <div key={office.uid} className="glass-panel p-8 border border-white/5 flex items-center justify-between group hover:border-cyan-400/20 transition-all">
             <div className="flex items-center gap-8">
               <div className={`w-16 h-16 rounded-2xl flex items-center justify-center border ${office.status === 'active' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-rose-500/10 border-rose-500/30 text-rose-400'}`}>
                 <Building2 size={32} />
               </div>
               <div>
                 <h4 className="text-xl font-black text-white italic tracking-tight uppercase">{office.officeName}</h4>
                 <div className="flex items-center gap-4 mt-2">
                   <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{office.email}</p>
                   <span className="w-1 h-1 bg-slate-800 rounded-full"></span>
                   <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">EXPIRA EM: {office.subscriptionExpiresAt?.toDate().toLocaleDateString()}</p>
                 </div>
               </div>
             </div>

             <div className="flex items-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => toggleStatus(office.uid, office.status)}
                  className={`flex items-center gap-3 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${office.status === 'active' ? 'bg-amber-500/10 text-amber-500 hover:bg-amber-500 hover:text-black' : 'bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-black'}`}
                >
                  {office.status === 'active' ? <Ban size={16}/> : <CheckCircle size={16}/>}
                  {office.status === 'active' ? 'Bloquear' : 'Ativar'}
                </button>
                <button 
                  onClick={() => deleteOffice(office.uid)}
                  className="flex items-center gap-3 px-6 py-3 rounded-xl bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white text-[10px] font-black uppercase tracking-widest transition-all"
                >
                  <Trash2 size={16}/> Excluir
                </button>
                <div className="w-12 h-12 bg-white/5 rounded-xl flex items-center justify-center text-slate-500 hover:text-cyan-400 transition-all cursor-pointer">
                  <ExternalLink size={18} />
                </div>
             </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="py-32 text-center">
            <ShieldAlert size={64} className="mx-auto text-slate-800 mb-6" />
            <p className="text-slate-600 font-black uppercase tracking-[0.4em]">Nenhum escritório detectado na rede.</p>
          </div>
        )}
