export const dbService = {
  getUserProfile: async (uid: string) => {
    const snap = await getDoc(doc(db, "users", uid));
    return snap.exists() ? snap.data() : null;
  },

  initProfile: async (uid: string, email: string) => {
    const isMaster = email.toLowerCase() === MASTER_EMAIL.toLowerCase();
    const profile = {
      uid, email,
      role: isMaster ? 'super-admin' : 'admin',
      status: 'active',
      officeName: isMaster ? 'Nexus Prime' : 'Novo Escritório Virtual',
      parentId: isMaster ? null : 'MASTER_ROOT',
      createdAt: serverTimestamp(),
      subscriptionExpiresAt: Timestamp.fromDate(new Date(2099, 11, 31)),
      expiresAt: Timestamp.fromDate(new Date(2099, 11, 31)),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referralCount: 0,
      metrics: { totalSalesCount: 0, totalRevenue: 0, commissionEarned: 0 }
    };
    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  // Monitoramento global para o Super Admin
  watchAllOffices: (cb: (data: any[]) => void) => {
    const q = query(collection(db, "users"), where("role", "==", "admin"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  // Monitoramento de vendas (Global ou Específico)
  watchSales: (userId: string | null, cb: (data: any[]) => void) => {
    const q = userId 
      ? query(collection(db, "sales"), where("userId", "==", userId), orderBy("createdAt", "desc"))
      : query(collection(db, "sales"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  // Generic sync for various collections
  sync: (col: string, userId: string | null, cb: (data: any[]) => void) => {
    let q;
    if (userId) {
      q = query(collection(db, col), where("userId", "==", userId));
    } else {
      q = query(collection(db, col));
    }
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  // Generic add document with userId and timestamp
  add: (col: string, userId: string, data: any) => 
    addDoc(collection(db, col), { ...data, userId, createdAt: serverTimestamp() }),

  // Generic update document by ID
  update: (col: string, id: string, data: any) => 
    updateDoc(doc(db, col, id), data),

  // Generic delete document by ID
  del: (col: string, id: string) => 
    deleteDoc(doc(db, col, id)),

  // Get all users for Super Admin management
  getAllUsers: (cb: (data: any[]) => void) => {
    const q = query(collection(db, "users"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  updateStatus: (uid: string, status: 'active' | 'blocked') => 
    updateDoc(doc(db, "users", uid), { status }),

  delOffice: (uid: string) => deleteDoc(doc(db, "users", uid)),

  addSale: (userId: string, amount: number, description: string) => 
    addDoc(collection(db, "sales"), { userId, amount, description, createdAt: serverTimestamp() })
};

