import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense } from './types';
import { 
  LayoutDashboard, Users, ShieldAlert, LogOut, 
  Zap, Building2, TrendingUp, DollarSign, 
  Package, ShoppingCart, WalletMinimal, BrainCircuit, Settings
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import AdminDashboard from './views/AdminDashboard';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  // States para dados globais do Admin
  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        if (p.status === 'blocked') {
          alert("Acesso suspenso. Entre em contato com o Super Admin.");
          await signOut(auth);
          return;
        }

        setProfile(p as UserProfile);
        setUser(u);

        const initialView = p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_OFFICE';
        setView(initialView);

        // Sync data se for admin
        if (p.role === 'admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null);
        setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-12 h-12 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(0,243,255,0.2)]"></div>
      <p className="mt-6 font-terminal text-[10px] text-cyan-400 tracking-[0.4em] uppercase">Sincronizando Nexus...</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';

  const adminMenu = [
    { id: 'MY_OFFICE', label: 'Início', icon: <LayoutDashboard size={18}/> },
    { id: 'ORDERS', label: 'Vendas (PDV)', icon: <ShoppingCart size={18}/> },
    { id: 'PRODUCTS', label: 'Estoque', icon: <Package size={18}/> },
    { id: 'CUSTOMERS', label: 'Clientes', icon: <Users size={18}/> },
    { id: 'EXPENSES', label: 'Despesas', icon: <WalletMinimal size={18}/> },
    { id: 'AI_INSIGHTS', label: 'Inteligência AI', icon: <BrainCircuit size={18}/> },
    { id: 'SETTINGS', label: 'Ajustes', icon: <Settings size={18}/> },
  ];

  const superMenu = [
    { id: 'MASTER_DASHBOARD', label: 'Métricas Globais', icon: <LayoutDashboard size={18}/> },
    { id: 'OFFICE_MANAGEMENT', label: 'Gerir Escritórios', icon: <Building2 size={18}/> },
  ];

  return (
    <div className="flex h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

      <aside className="w-72 border-r border-white/5 bg-[#0c0628]/50 backdrop-blur-xl flex flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-14">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg shadow-cyan-400/20">
            <Zap size={20} className="text-black" />
          </div>
          <div>
            <span className="font-terminal font-black text-sm block glow-cyan">FACINDEMAIS</span>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">{isSuper ? 'Master Root' : 'Virtual Office'}</span>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          {(isSuper ? superMenu : adminMenu).map(item => (
            <button 
              key={item.id}
              onClick={() => setView(item.id as ViewState)} 
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-[11px] font-black uppercase tracking-wider transition-all ${view === item.id ? 'bg-cyan-400 text-black shadow-lg shadow-cyan-400/20 font-bold' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
            >
              {item.icon} {item.label}
            </button>
          ))}
        </nav>

        <div className="pt-8 border-t border-white/5 space-y-4">
          <div className="px-5">
            <p className="text-[10px] font-black text-slate-600 uppercase mb-1">Terminal Ativo</p>
            <p className="text-xs font-bold text-white truncate">{profile?.email}</p>
          </div>
          <button onClick={() => signOut(auth)} className="w-full flex items-center gap-4 px-5 py-4 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all text-[11px] font-black uppercase">
            <LogOut size={18}/> Desconectar
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-12 relative z-10 custom-scrollbar">
        <div className="max-w-7xl mx-auto">
          {isSuper ? (
            <>
              {view === 'MASTER_DASHBOARD' && <MasterDashboard />}
              {view === 'OFFICE_MANAGEMENT' && <OfficeManagement />}
            </>
          ) : (
            <>
              {view === 'MY_OFFICE' && <AdminDashboard profile={profile!} orders={orders} expenses={expenses} products={products} />}
              {view === 'ORDERS' && <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} />}
              {view === 'PRODUCTS' && <ProductsView userId={user.uid} />}
              {view === 'CUSTOMERS' && <CustomersView customers={customers} userId={user.uid} />}
              {view === 'EXPENSES' && <ExpensesView expenses={expenses} userId={user.uid} />}
              {view === 'AI_INSIGHTS' && <AIInsightsView orders={orders} products={products} />}
              {view === 'SETTINGS' && <SettingsView profile={profile!} />}
            </>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
