const MASTER_EMAIL = "giufarlosdias@hotmail.com";

export const dbService = {
  getUserProfile: async (uid: string) => {
    const snap = await getDoc(doc(db, "users", uid));
    return snap.exists() ? snap.data() : null;
  },

  initProfile: async (uid: string, email: string, refCodeInput?: string) => {
    const isMaster = email.toLowerCase() === MASTER_EMAIL.toLowerCase();

    let lineage = { l1: '', l2: '', l3: '' };
    let referredBy = '';

    // Lógica de busca de linhagem se houver código de indicação
    if (refCodeInput) {
      const q = query(collection(db, "users"), where("referralCode", "==", refCodeInput.toUpperCase()));
      const snap = await getDocs(q);
      if (!snap.empty) {
        const sponsor = snap.docs[0].data();
        referredBy = sponsor.uid;
        lineage = {
          l1: sponsor.uid,
          l2: sponsor.lineage?.l1 || '',
          l3: sponsor.lineage?.l2 || ''
        };
      }
    }

    const profile = {
      uid, email,
      role: isMaster ? 'super-admin' : 'admin',
      status: 'active',
      subscriptionStatus: 'PAID',
      officeName: isMaster ? 'Nexus Root' : `Escritório de ${email.split('@')[0]}`,
      createdAt: serverTimestamp(),
      subscriptionExpiresAt: Timestamp.fromDate(new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referredBy,
      lineage,
      metrics: {
        totalSalesCount: 0,
        totalRevenue: 0,
        referralEarnings: { l1: 0, l2: 0, l3: 0 }
      }
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  // Monitoramento global de rede para o Super Admin
  watchNetwork: (cb: (users: any[], sales: any[]) => void) => {
    const unsubUsers = onSnapshot(collection(db, "users"), (uSnap) => {
      const users = uSnap.docs.map(d => ({ id: d.id, ...d.data() }));
      onSnapshot(collection(db, "orders"), (oSnap) => {
        const orders = oSnap.docs.map(d => ({ id: d.id, ...d.data() }));
        cb(users, orders);
      });
    });
    return unsubUsers;
  },

  sync: (col: string, userId: string | null, cb: (data: any[]) => void) => {
    const q = userId ? query(collection(db, col), where("userId", "==", userId)) : query(collection(db, col));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  updateSubscription: (uid: string, status: 'PAID' | 'EXPIRED') => 
    updateDoc(doc(db, "users", uid), { subscriptionStatus: status }),

  updateStatus: (uid: string, status: 'active' | 'blocked') => 
    updateDoc(doc(db, "users", uid), { status }),

  add: (col: string, userId: string, data: any) => 
    addDoc(collection(db, col), { ...data, userId, createdAt: serverTimestamp() }),

  update: (col: string, id: string, data: any) => 
    updateDoc(doc(db, col, id), data),

  del: (col: string, id: string) => 
    deleteDoc(doc(db, col, id)),

  delOffice: (uid: string) => deleteDoc(doc(db, "users", uid))
};

import React, { useState, useEffect } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, dbService } from '../services/firebase';
import { Zap, Loader2, UserPlus } from 'lucide-react';

const LoginView: React.FC = () => {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [refCode, setRefCode] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('ref');
    if (code) setRefCode(code.toUpperCase());
  }, []);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Tenta login
      await signInWithEmailAndPassword(auth, email, pass);
    } catch (err: any) {
      if (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
        try {
          // Se não existe, cria conta e inicializa perfil com refCode
          const cred = await createUserWithEmailAndPassword(auth, email, pass);
          await dbService.initProfile(cred.user.uid, email, refCode);
        } catch (regErr) {
          alert("Erro ao criar terminal operacional.");
        }
      } else {
        alert("Erro de autenticação.");
      }
    } finally { setLoading(false); }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-[#05010d] p-6 relative overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-30"></div>

      {/* Detalhes Estéticos Cyberpunk */}
      <div className="absolute top-1/4 -left-20 w-64 h-64 bg-cyan-400/10 blur-[100px] animate-pulse"></div>
      <div className="absolute bottom-1/4 -right-20 w-64 h-64 bg-purple-500/10 blur-[100px] animate-pulse"></div>

      <div className="w-full max-w-sm glass-panel p-10 border border-white/5 shadow-2xl relative z-10 animate-fade-in">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-cyan-400 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-cyan-400/20 rotate-3 hover:rotate-0 transition-transform cursor-pointer">
            <Zap size={40} className="text-black" />
          </div>
          <h1 className="font-terminal font-black text-3xl glow-cyan tracking-tighter italic">FACINDEMAIS OS</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-3">Auth & Synchronization Core</p>
        </div>

        <form onSubmit={submit} className="space-y-5">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">Terminal (E-mail)</label>
            <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="operador@nexus.com" />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">Chave de Criptografia</label>
            <input required type="password" value={pass} onChange={e => setPass(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="••••••••" />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-purple-400 uppercase tracking-widest ml-1">Código de Indicação (Opcional)</label>
            <div className="relative">
              <UserPlus className="absolute left-5 top-1/2 -translate-y-1/2 text-purple-400/50" size={18} />
              <input type="text" value={refCode} onChange={e => setRefCode(e.target.value.toUpperCase())} className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-purple-400 font-black outline-none focus:border-purple-400 transition-all placeholder:text-slate-800" placeholder="NEXUS-00" />
            </div>
          </div>

          <button disabled={loading} className="btn-nexus w-full py-6 rounded-2xl flex items-center justify-center gap-4 active:scale-95 mt-4 group">
            {loading ? <Loader2 className="animate-spin" size={24}/> : (
