import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense } from './types';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, 
  Gift, BrainCircuit, Settings, Grid3X3, WalletMinimal, 
  ShoppingCart, Package, Truck, Layers, Box, CreditCard, UserPlus, Star, 
  Clock, Download, Calendar as CalendarIcon, FileText, CheckCircle, TrendingUp, Mail, HeartPulse, Activity,
  PieChart, AlertTriangle, Filter, Database, ShieldCheck
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  // Global Data States
  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        if (p.status === 'blocked') {
          alert("Acesso suspenso.");
          await signOut(auth);
          return;
        }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null);
        setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-12 h-12 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const goBackToHub = () => setView('MY_HUB');

  // Mapeamento de Visões Genéricas para Módulos Novos
  const renderView = () => {
    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;

      // Mapeamento de Cadastros
      case 'SUPPLIERS': return <GenericModuleView onBack={goBackToHub} title="Fornecedores" icon={<Truck />} />;
      case 'CATEGORIES': return <GenericModuleView onBack={goBackToHub} title="Categorias" icon={<Layers />} />;
      case 'UNITS': return <GenericModuleView onBack={goBackToHub} title="Unidades" icon={<Box />} />;
      case 'PAYMENT_METHODS': return <GenericModuleView onBack={goBackToHub} title="Formas de Pagamento" icon={<CreditCard />} />;
      case 'STOCK_REPLACEMENT': return <GenericModuleView onBack={goBackToHub} title="Reposição de Estoque" icon={<ClipboardList />} />;
      case 'SELLERS': return <GenericModuleView onBack={goBackToHub} title="Vendedores" icon={<UserPlus />} />;
      case 'CREDIT_LIMIT': return <GenericModuleView onBack={goBackToHub} title="Limite de Crédito" icon={<Star />} />;

      // Acesso Rápido
      case 'SALES_HISTORY': return <GenericModuleView onBack={goBackToHub} title="Vendas Realizadas" icon={<ShoppingCart />} />;
      case 'RECEIVABLES': return <GenericModuleView onBack={goBackToHub} title="Receber" icon={<Download />} />;
      case 'CALENDAR': return <GenericModuleView onBack={goBackToHub} title="Agendamentos" icon={<CalendarIcon />} />;
      case 'RECEIPT_COPY': return <GenericModuleView onBack={goBackToHub} title="2ª Via de Recibo" icon={<FileText />} />;
      case 'PAYMENTS_RECEIVED': return <GenericModuleView onBack={goBackToHub} title="Pagamentos Recebidos" icon={<CheckCircle />} />;
      case 'LOSS_WRITE_OFF': return <GenericModuleView onBack={goBackToHub} title="Baixa para Prejuízo" icon={<TrendingUp />} />;
      case 'SALES_QUERY': return <GenericModuleView onBack={goBackToHub} title="Consultar Vendas" icon={<Activity />} />;
      case 'BULK_EMAIL': return <GenericModuleView onBack={goBackToHub} title="E-mail em Massa" icon={<Mail />} />;
      case 'DOCTOR_PANEL': return <GenericModuleView onBack={goBackToHub} title="Painel Profissional" icon={<HeartPulse />} />;

      // Apoio e Decisão
      case 'REPORTS_RECEIVABLES': return <GenericModuleView onBack={goBackToHub} title="Clientes x Receber" icon={<PieChart />} />;
      case 'REPORTS_CUSTOMER_MOVEMENTS': return <GenericModuleView onBack={goBackToHub} title="Movimentações Cliente" icon={<TrendingUp />} />;
      case 'OVERDUE_OPERATIONS': return <GenericModuleView onBack={goBackToHub} title="Operações Vencidas" icon={<AlertTriangle />} />;
      case 'CUSTOMER_PROFILE_LIST': return <GenericModuleView onBack={goBackToHub} title="Perfil do Cliente" icon={<Users />} />;
      case 'LOW_STOCK_REPORT': return <GenericModuleView onBack={goBackToHub} title="Estoque Baixo" icon={<Package />} />;
      case 'BEST_SELLERS_REPORT': return <GenericModuleView onBack={goBackToHub} title="Mais Vendidos" icon={<Zap />} />;
      case 'MANAGEMENT_TRACKING': return <GenericModuleView onBack={goBackToHub} title="Acomp. Gerencial" icon={<Activity />} />;
      case 'PROMOTIONS': return <GenericModuleView onBack={goBackToHub} title="Divulgar Promoções" icon={<Star />} />;
      case 'SALES_TO_COLLECT': return <GenericModuleView onBack={goBackToHub} title="Vendas a Cobrar" icon={<ShoppingCart />} />;
      case 'REVENUE_EXPENSES_REPORT': return <GenericModuleView onBack={goBackToHub} title="Receita x Despesas" icon={<CreditCard />} />;
      case 'PENDING_PURCHASES': return <GenericModuleView onBack={goBackToHub} title="Compras Pendentes" icon={<Clock />} />;
      case 'SALES_BY_PAYMENT_METHOD': return <GenericModuleView onBack={goBackToHub} title="Vendas x Pagamentos" icon={<LayoutDashboard />} />;

      // Relatórios
      case 'CUSTOMER_STATEMENT': return <GenericModuleView onBack={goBackToHub} title="Extrato p/ Clientes" icon={<FileText />} />;
      case 'PRODUCTS_BY_CATEGORY': return <GenericModuleView onBack={goBackToHub} title="Produtos por Categoria" icon={<Filter />} />;
      case 'MONTHLY_REPORTS': return <GenericModuleView onBack={goBackToHub} title="Relatórios Mensais" icon={<CalendarIcon />} />;
      case 'HTML_REPORTS': return <GenericModuleView onBack={goBackToHub} title="Relatórios HTML" icon={<FileText />} />;
      case 'EXCEL_EXPORT': return <GenericModuleView onBack={goBackToHub} title="Exportar para Excel" icon={<Download />} />;

      // Segurança
      case 'BACKUP': return <GenericModuleView onBack={goBackToHub} title="Backup e Restauração" icon={<Database />} />;
      case 'SECURITY_TIPS': return <GenericModuleView onBack={goBackToHub} title="Dicas de Segurança" icon={<ShieldCheck />} />;
      case 'COMPANY_SETTINGS': return <GenericModuleView onBack={goBackToHub} title="Configurar Empresa" icon={<Settings />} />;

      default: return <NexusHub setView={setView} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

      <aside className="w-20 lg:w-72 border-r border-white/5 bg-[#0c0628]/50 backdrop-blur-xl flex flex-col p-6 z-20 transition-all">
        <div className="flex items-center gap-4 mb-14 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg shadow-cyan-400/20 shrink-0">
            <Zap size={20} className="text-black" />
          </div>
          <div className="hidden lg:block">
            <span className="font-terminal font-black text-sm block glow-cyan">FACINDEMAIS</span>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Digital OS</span>
          </div>
        </div>

        <nav className="flex-1 space-y-4">
          {isSuper ? (
            <>
              <button onClick={() => setView('MASTER_DASHBOARD')} className={`nav-btn ${view === 'MASTER_DASHBOARD' ? 'active' : ''}`}><LayoutDashboard size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Métricas</span></button>
              <button onClick={() => setView('OFFICE_MANAGEMENT')} className={`nav-btn ${view === 'OFFICE_MANAGEMENT' ? 'active' : ''}`}><Building2 size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Escritórios</span></button>
            </>
          ) : (
            <>
              <button onClick={() => setView('MY_HUB')} className={`nav-btn ${view === 'MY_HUB' ? 'active' : ''}`}><Grid3X3 size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Painel Central</span></button>
              <button onClick={() => setView('REFERRALS')} className={`nav-btn ${view === 'REFERRALS' ? 'active' : ''}`}><Gift size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Minha Rede</span></button>
              <button onClick={() => setView('AI_INSIGHTS')} className={`nav-btn ${view === 'AI_INSIGHTS' ? 'active' : ''}`}><BrainCircuit size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">IA Nexus</span></button>
            </>
          )}
        </nav>

        <div className="pt-8 border-t border-white/5 space-y-4">
          <button onClick={() => setView('SETTINGS')} className={`nav-btn ${view === 'SETTINGS' ? 'active' : ''}`}><Settings size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Ajustes</span></button>
          <button onClick={() => signOut(auth)} className="nav-btn text-rose-500 hover:bg-rose-500/10"><LogOut size={20}/><span className="hidden lg:block uppercase tracking-widest text-[10px]">Sair</span></button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-8 lg:p-12 relative z-10 custom-scrollbar bg-[#05010d]">
        <div className="max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

