import React, { useState, useEffect } from 'react';
import { Gift, Share2, Copy, Trophy, Zap, Smartphone, MessageCircle } from 'lucide-react';
import { UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface ReferralViewProps { profile: UserProfile; }

const ReferralView: React.FC<ReferralViewProps> = ({ profile }) => {
  const [targetPhone, setTargetPhone] = useState('');
  const [network, setNetwork] = useState({ l1: [], l2: [], l3: [] });

  useEffect(() => {
    return dbService.watchNetwork((users) => {
      const l1 = users.filter(u => u.lineage?.l1 === profile.uid);
      const l2 = users.filter(u => u.lineage?.l2 === profile.uid);
      const l3 = users.filter(u => u.lineage?.l3 === profile.uid);
      setNetwork({ l1, l2, l3 });
    });
  }, [profile.uid]);

  const referralLink = `${window.location.origin}/?ref=${profile.referralCode}`;

  const shareWhatsApp = () => {
    if(!targetPhone) return alert("Insira o telefone do convidado.");
    const cleanPhone = targetPhone.replace(/\D/g, '');
    const message = encodeURIComponent(`Olá! Estou te convidando para conhecer o Facindemais OS, o sistema de gestão mais rápido do mercado. Cadastre-se pelo meu link: ${referralLink}`);
    window.open(`https://wa.me/55${cleanPhone}?text=${message}`, '_blank');
  };

  const copyLink = () => { 
    navigator.clipboard.writeText(referralLink); 
    alert('Link de Indicação copiado!'); 
  };

  return (
    <div className="max-w-6xl mx-auto space-y-12 animate-fade-in pb-20">
      <div className="text-center space-y-6">
        <div className="w-24 h-24 bg-cyan-400 text-black rounded-[2.2rem] flex items-center justify-center mx-auto shadow-[0_0_50px_rgba(0,243,255,0.4)] rotate-6">
          <Gift size={48} />
        </div>
        <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Expansão de Rede</h2>
        <p className="text-slate-500 font-bold text-xl max-w-2xl mx-auto uppercase tracking-wide opacity-70 leading-relaxed">
          Convide novos escritórios e ganhe comissões recorrentes.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="nexus-card p-10 bg-gradient-to-br from-[#0c0628] to-black">
          <h3 className="text-2xl font-black text-white italic mb-8 uppercase">Compartilhar no WhatsApp</h3>
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">Telefone do Convidado (com DDD)</label>
              <div className="relative">
                <Smartphone className="absolute left-5 top-1/2 -translate-y-1/2 text-cyan-400/50" size={20} />
                <input 
                  type="text" 
                  value={targetPhone} 
                  onChange={e => setTargetPhone(e.target.value)}
                  placeholder="Ex: 11999999999"
                  className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-5 text-white font-bold outline-none focus:border-cyan-400 transition-all"
                />
              </div>
            </div>
            <button onClick={shareWhatsApp} className="w-full bg-[#25D366] text-white py-6 rounded-2xl font-black flex items-center justify-center gap-4 hover:scale-[1.02] active:scale-95 transition-all shadow-lg shadow-green-500/20">
              <MessageCircle size={24} /> ENVIAR CONVITE VIA ZAP
            </button>
            <button onClick={copyLink} className="w-full bg-white/5 text-slate-400 py-6 rounded-2xl font-black flex items-center justify-center gap-4 border border-white/5 hover:bg-white/10 transition-all">
              <Copy size={20} /> APENAS COPIAR LINK
            </button>
          </div>
        </div>

        <div className="glass-panel p-10 border border-white/5">
          <h3 className="text-2xl font-black text-white italic mb-8 uppercase">Sua Rede Atual</h3>
          <div className="grid grid-cols-3 gap-4">
             <div className="p-6 bg-white/5 rounded-2xl text-center border border-white/5">
                <p className="text-[9px] font-black text-cyan-400 uppercase mb-2">Nível 1</p>
                <p className="text-3xl font-black text-white italic">{network.l1.length}</p>
             </div>
             <div className="p-6 bg-white/5 rounded-2xl text-center border border-white/5">
                <p className="text-[9px] font-black text-purple-400 uppercase mb-2">Nível 2</p>
                <p className="text-3xl font-black text-white italic">{network.l2.length}</p>
             </div>
             <div className="p-6 bg-white/5 rounded-2xl text-center border border-white/5">
                <p className="text-[9px] font-black text-rose-400 uppercase mb-2">Nível 3</p>
                <p className="text-3xl font-black text-white italic">{network.l3.length}</p>
             </div>
          </div>
          <div className="mt-8 p-6 bg-cyan-400/5 rounded-2xl border border-cyan-400/20">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Status do Seu Link</p>
            <p className="text-cyan-400 font-bold truncate text-xs">{referralLink}</p>
          </div>
        </div>
      </div>
    </div>
  );
