import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Cpu, CreditCard, Clock, FileText, User, ShoppingBag } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [search, setSearch] = useState('');

  // Estados para item avulso
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });

  const addToCart = (product: Product) => {
    if (product.type === 'PRODUCT' && product.stock <= 0) {
      alert("Estoque esgotado para este item!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, {
        productId: product.id,
        quantity: 1,
        priceAtTime: product.price,
        nameAtTime: product.name
      }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha nome e valor do item avulso.");
    const newItem: OrderItem = {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase()
    };
    setCart(prev => [...prev, newItem]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const generateWhatsAppReceipt = (orderData: any, customerObj?: Customer) => {
    const total = orderData.total;
    const dateStr = new Date().toLocaleDateString('pt-BR');

    let msg = `*📄 COMPROVANTE DE VENDA - ${profile.officeName}*\n`;
    msg += `------------------------------------------\n`;
    msg += `*🗓 Data:* ${dateStr}\n`;
    msg += `*👤 Cliente:* ${customerObj ? customerObj.name : 'Consumidor Final'}\n`;
    msg += `------------------------------------------\n\n`;

    msg += `*📦 ITENS DA OPERAÇÃO:*\n`;
    cart.forEach(item => {
      msg += `• ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });

    msg += `\n*💰 TOTAL LÍQUIDO: R$ ${total.toFixed(2)}*\n`;
    msg += `*💳 FORMA PAGTO:* ${orderData.paymentMethod}\n`;

    if (orderData.paymentMethod === 'DEFERRED' && installments > 1) {
      msg += `\n*🗓 PLANO DE PARCELAMENTO:* \n`;
      const installmentValue = total / installments;
      for (let i = 1; i <= installments; i++) {
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + (i * 30));
        msg += `${i}ª Parcela: R$ ${installmentValue.toFixed(2)} (${dueDate.toLocaleDateString('pt-BR')})\n`;
      }
    }

    msg += `\n------------------------------------------\n`;
    msg += `_Obrigado pela preferência!_\n`;
    msg += `_Gerado por Facindemais OS Digital_`;

    const phone = customerObj?.phone?.replace(/\D/g, '') || '';
    const encodedMsg = encodeURIComponent(msg);
    window.open(`https://wa.me/55${phone}?text=${encodedMsg}`, '_blank');
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Selecione itens para continuar.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customerObj = customers.find(c => c.id === selectedCustomerId);

      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: status === 'QUOTE' ? 'QUOTE' : (paymentMethod === 'DEFERRED' ? 'PENDING' : 'PAID'),
        paymentMethod,
        createdAt: new Date()
      };

      // Salvar no banco
      await dbService.add('orders', userId, orderData);

      // Baixa de estoque apenas para produtos cadastrados e vendas reais
      if (status === 'PAID') {
        for (const item of cart) {
          const prod = products.find(p => p.id === item.productId);
          if (prod && prod.type === 'PRODUCT') {
            await dbService.update('products', prod.id, { 
              stock: Math.max(0, prod.stock - item.quantity) 
            });
          }
        }
      }

      // Enviar WhatsApp
      generateWhatsAppReceipt(orderData, customerObj);

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setInstallments(1);
    } catch (e) {
      alert('Erro crítico ao processar transação.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none">Fluxo de Vendas</h2>
        {!isCreating && (
          <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-5 rounded-2xl flex items-center gap-4 transition-all active:scale-95">
            <Plus size={24} /> NOVA OPERAÇÃO
          </button>
        )}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            {/* Venda Avulsa Quick Form */}
            <div className="nexus-card p-8 border-dashed border-2 border-cyan-400/20">
               <div className="flex items-center gap-4 mb-6">
                 <ShoppingBag size={20} className="text-cyan-400" />
                 <h4 className="text-xs font-black text-white uppercase tracking-[0.2em]">Item Avulso (Venda Rápida)</h4>
               </div>
               <div className="flex flex-wrap md:flex-nowrap gap-4">
                 <input 
                    placeholder="Descrição do Produto..." 
                    value={manualItem.name} 
                    onChange={e => setManualItem({...manualItem, name: e.target.value})}
                    className="flex-1 bg-black/40 border border-white/10 rounded-xl px-5 py-3 text-white font-bold outline-none focus:border-cyan-400" 
                 />
                 <input 
                    type="number" 
                    placeholder="R$ Valor" 
                    value={manualItem.price} 
                    onChange={e => setManualItem({...manualItem, price: e.target.value})}
                    className="w-32 bg-black/40 border border-white/10 rounded-xl px-5 py-3 text-white font-bold outline-none focus:border-cyan-400" 
                 />
                 <input 
                    type="number" 
                    placeholder="Qtd" 
                    value={manualItem.qty} 
                    onChange={e => setManualItem({...manualItem, qty: e.target.value})}
                    className="w-20 bg-black/40 border border-white/10 rounded-xl px-5 py-3 text-white font-bold outline-none focus:border-cyan-400" 
                 />
                 <button onClick={addManualToCart} className="bg-cyan-400 text-black px-6 rounded-xl font-black flex items-center gap-2 hover:scale-105 transition-all">
                   <Plus size={20} /> INCLUIR
                 </button>
               </div>
            </div>

            <div className="bg-[#0c0628]/80 p-6 rounded-3xl border border-cyan-400/20 flex items-center gap-4 shadow-lg focus-within:border-cyan-400 transition-all">
              <Search className="text-cyan-400" />
              <input 
                placeholder="Pesquisar catálogo de produtos..." 
                className="bg-transparent flex-1 outline-none text-white font-bold text-xl" 
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto custom-scrollbar pr-2">
              {filteredProducts.map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-6 text-left hover:scale-[1.02] transition-all group border-white/5 hover:border-cyan-400/50">
                   <div className="flex justify-between mb-4">
                     <div className="p-3 bg-white/5 rounded-xl text-cyan-400 group-hover:text-white transition-colors"><Cpu size={24}/></div>
                     <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg ${p.type === 'SERVICE' ? 'bg-cyan-400/10 text-cyan-400' : 'bg-purple-500/10 text-purple-400'}`}>{p.type}</span>
                   </div>
                   <p className="font-black text-white truncate text-xl mb-1 group-hover:text-glow-cyan transition-all">{p.name}</p>
