            <p className="text-slate-500 font-bold text-xs uppercase">Você atingiu {salesCount} vendas. Libere o acesso completo agora.</p>
          </div>
          <div className="nexus-card p-10 border-cyan-400 w-full max-w-lg bg-cyan-400/5">
            <p className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 italic">PIX PARA LIBERAÇÃO IMEDIATA</p>
            <div className="bg-black/60 p-5 rounded-2xl border border-white/10 font-mono text-white break-all mb-6 select-all cursor-pointer">giufarlosdias@hotmail.com</div>
            <p className="text-[10px] font-bold text-slate-500 uppercase">Liberação automática em até 10 minutos após o pagamento.</p>
          </div>
          <button onClick={() => signOut(auth)} className="text-slate-700 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors">Encerrar Sessão</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
