const MASTER_EMAIL = "giufarlosdias@hotmail.com";

export const dbService = {
  getUserProfile: async (uid: string) => {
    const snap = await getDoc(doc(db, "users", uid));
    return snap.exists() ? snap.data() : null;
  },

  resetPassword: async (email: string) => {
    return sendPasswordResetEmail(auth, email);
  },

  initProfile: async (uid: string, email: string, refCodeInput?: string) => {
    const isMaster = email.toLowerCase() === MASTER_EMAIL.toLowerCase();
    let lineage = { l1: '', l2: '', l3: '' };
    let referredBy = '';

    if (refCodeInput) {
      const q = query(collection(db, "users"), where("referralCode", "==", refCodeInput.toUpperCase()));
      const snap = await getDocs(q);
      if (!snap.empty) {
        const sponsor = snap.docs[0].data();
        referredBy = sponsor.uid;
        lineage = {
          l1: sponsor.uid,
          l2: sponsor.lineage?.l1 || '',
          l3: sponsor.lineage?.l2 || ''
        };
      }
    }

    const profile = {
      uid, email,
      role: isMaster ? 'super-admin' : 'admin',
      status: 'active',
      subscriptionStatus: 'TRIAL',
      officeName: isMaster ? 'Nexus Root' : `Escritório de ${email.split('@')[0]}`,
      phone: '', address: '', pixKey: '',
      createdAt: serverTimestamp(),
      subscriptionExpiresAt: Timestamp.fromDate(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)),
      referralCode: uid.substring(0, 6).toUpperCase(),
      referredBy, lineage
    };

    await setDoc(doc(db, "users", uid), profile);
    return profile;
  },

  sync: (col: string, userId: string, cb: (data: any[]) => void) => {
    const q = query(collection(db, col), where("userId", "==", userId), orderBy("createdAt", "desc"));
    return onSnapshot(q, (s) => cb(s.docs.map(d => ({ id: d.id, ...d.data() }))));
  },

  add: (col: string, userId: string, data: any) => 
    addDoc(collection(db, col), { ...data, userId, createdAt: serverTimestamp() }),

  update: (col: string, id: string, data: any) => 
    updateDoc(doc(db, col, id), data),

  del: (col: string, id: string) => 
    deleteDoc(doc(db, col, id)),

  updateProfile: (uid: string, data: any) =>
    updateDoc(doc(db, "users", uid), data),

  watchNetwork: (cb: (users: any[]) => void) => {
    return onSnapshot(collection(db, "users"), (s) => cb(s.docs.map(d => d.data())));
  }
};

import React, { useState, useEffect } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, dbService } from '../services/firebase';
import { Zap, Loader2, KeyRound, Mail, AlertCircle } from 'lucide-react';

const LoginView: React.FC = () => {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [refCode, setRefCode] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('ref');
    if (code) setRefCode(code.toUpperCase());
  }, []);

  const handleResetPassword = async () => {
    if (!email) return setMessage({ text: 'Digite seu e-mail operacional primeiro.', type: 'error' });
    try {
      await dbService.resetPassword(email);
      setMessage({ text: 'Link de recuperação enviado ao seu e-mail.', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao enviar link. Verifique o e-mail.', type: 'error' });
    }
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ text: '', type: '' });
    try {
      await signInWithEmailAndPassword(auth, email, pass);
    } catch (err: any) {
      if (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
        try {
          const cred = await createUserWithEmailAndPassword(auth, email, pass);
          await dbService.initProfile(cred.user.uid, email, refCode);
        } catch (regErr: any) {
          setMessage({ text: 'Falha ao inicializar núcleo operacional.', type: 'error' });
        }
      } else {
        setMessage({ text: 'Erro de autenticação de rede.', type: 'error' });
      }
    } finally { setLoading(false); }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-[#05010d] p-6 relative overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-30"></div>

      <div className="w-full max-w-sm glass-panel p-10 border border-white/5 shadow-2xl relative z-10">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-cyan-400 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-cyan-400/20 rotate-3">
            <Zap size={40} className="text-black" />
          </div>
          <h1 className="font-terminal font-black text-3xl glow-cyan tracking-tighter italic">NEXUS OPERATIONAL</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-3">Sincronização de Dados v2.0</p>
        </div>

        {message.text && (
          <div className={`mb-6 p-4 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border ${message.type === 'error' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'}`}>
            <AlertCircle size={16} /> {message.text}
          </div>
        )}

        <form onSubmit={submit} className="space-y-5">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">ID Operador (E-mail)</label>
            <div className="relative">
              <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-cyan-400/30" size={18} />
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="operador@nexus.com" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">Chave Mestra</label>
            <div className="relative">
              <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-cyan-400/30" size={18} />
              <input required type="password" value={pass} onChange={e => setPass(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="••••••••" />
            </div>
          </div>

          <div className="flex justify-between items-center px-1">
             <button type="button" onClick={handleResetPassword} className="text-[10px] font-black text-slate-500 hover:text-cyan-400 uppercase tracking-widest transition-colors">Esqueci minha senha</button>
             {refCode && <span className="text-[9px] font-black text-purple-400 uppercase tracking-widest">Ref: {refCode}</span>}
          </div>

          <button disabled={loading} className="btn-nexus w-full py-6 rounded-2xl flex items-center justify-center gap-4 active:scale-95 group">
            {loading ? <Loader2 className="animate-spin" size={24}/> : (
              <>
                <span className="uppercase font-black tracking-widest">Acessar Terminal</span>
                <Zap size={20} className="fill-current" />
              </>
            )}
          </button>
        </form>

        <p className="mt-8 text-[9px] text-center text-slate-700 font-bold uppercase tracking-widest leading-relaxed">
          Os dados de cada escritório são criptografados e isolados por núcleo de segurança.
        </p>
      </div>
    </div>
  );
};

