import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');
        if (p.status === 'blocked') { alert("Acesso suspenso."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-[#05010d]"><div className="w-12 h-12 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const contactSuperadmin = () => {
    const msg = encodeURIComponent(`Olá! Sou do escritório ${profile?.officeName} (${profile?.email}) e gostaria de liberar meu acesso ao Facindemais OS. Já realizei o pagamento.`);
    window.open(`https://wa.me/5511999999999?text=${msg}`, '_blank'); // Altere para o seu número real
  };

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-rose-500 rounded-3xl flex items-center justify-center shadow-lg border border-rose-400/50"><Lock size={40} className="text-white"/></div>
          <div className="max-w-md">
            <h2 className="text-3xl font-black text-white italic tracking-tighter uppercase mb-2">Limite de Teste Excedido</h2>
            <p className="text-slate-500 font-bold text-xs uppercase">Você atingiu {salesCount} vendas. Libere o acesso completo agora.</p>
          </div>
          <div className="nexus-card p-10 border-cyan-400 w-full max-w-lg bg-cyan-400/5">
            <p className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 italic">CHAVE PIX PARA LIBERAÇÃO</p>
            <div className="bg-black/60 p-5 rounded-2xl border border-white/10 font-mono text-white break-all mb-6 select-all cursor-pointer">giufarlosdias@hotmail.com</div>
            <p className="text-[10px] font-bold text-slate-500 uppercase">Envie o comprovante para liberação automática.</p>
          </div>

          <button onClick={contactSuperadmin} className="flex items-center gap-4 bg-[#25D366] text-white px-8 py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:scale-105 transition-all shadow-xl shadow-green-500/20">
             <MessageCircle size={24} /> Falar com Suporte de Pagamento
          </button>

          <button onClick={() => signOut(auth)} className="text-slate-700 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors">Encerrar Sessão</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Operacional" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-10 pointer-events-none"></div>
      <aside className="w-20 lg:w-72 border-r border-white/5 bg-[#0c0628]/50 backdrop-blur-xl flex flex-col p-6 z-20">
        <div className="flex items-center gap-4 mb-14 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg shadow-cyan-400/20 shrink-0"><Zap size={20} className="text-black"/></div>
          <div className="hidden lg:block"><span className="font-terminal font-black text-sm block glow-cyan uppercase">FACINDEMAIS</span><span className="text-[9px] font-black text-slate-500 tracking-widest uppercase">Nexus Core</span></div>
        </div>
        <nav className="flex-1 space-y-4">
          {isSuper ? (
            <><button onClick={()=>setView('MASTER_DASHBOARD')} className={`nav-btn ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard/></button><button onClick={()=>setView('OFFICE_MANAGEMENT')} className={`nav-btn ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2/></button></>
          ) : (
            <><button onClick={()=>setView('MY_HUB')} className={`nav-btn ${view==='MY_HUB'?'active':''}`}><Grid3X3/></button><button onClick={()=>setView('REFERRALS')} className={`nav-btn ${view==='REFERRALS'?'active':''}`}><Gift/></button></>
          )}
        </nav>
        <div className="pt-8 border-t border-white/5 space-y-4">
          <button onClick={() => setView('SETTINGS')} className={`nav-btn ${view === 'SETTINGS' ? 'active' : ''}`}><Settings/></button>
          <button onClick={() => signOut(auth)} className="nav-btn text-rose-500 hover:bg-rose-500/10"><LogOut/></button>
        </div>
      </aside>
      <main className="flex-1 overflow-y-auto p-8 lg:p-12 relative z-10 custom-scrollbar">{renderView()}</main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/firebase';
import { UserProfile } from '../types';
import { 
  Building2, Ban, Trash2, CheckCircle, 
  ShieldAlert, Search, DollarSign, Clock, AlertTriangle 
} from 'lucide-react';

const OfficeManagement: React.FC = () => {
  const [offices, setOffices] = useState<UserProfile[]>([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    // Fix: use watchNetwork instead of non-existent watchAllOffices
    return dbService.watchNetwork((data) => setOffices(data as UserProfile[]));
  }, []);

  const toggleSubscription = async (uid: string, current: string) => {
    const next = current === 'PAID' ? 'EXPIRED' : 'PAID';
    if (confirm(`Confirmar alteração de mensalidade para ${next}?`)) {
      // Fix: use generic update method as updateSubscription is missing
      await dbService.update('users', uid, { subscriptionStatus: next });
    }
  };

  const toggleStatus = async (uid: string, current: string) => {
    const next = current === 'active' ? 'blocked' : 'active';
    if (confirm(`Deseja alterar o acesso do terminal para ${next.toUpperCase()}?`)) {
      // Fix: use generic update method as updateStatus is missing
      await dbService.update('users', uid, { status: next });
    }
  };

  const filtered = offices.filter(o => 
    o.email.toLowerCase().includes(search.toLowerCase()) || 
    o.officeName.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-12 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-4xl font-black text-white italic tracking-tighter glow-cyan leading-none uppercase">Terminais Operacionais</h2>
          <p className="text-slate-500 font-bold text-sm tracking-widest uppercase mt-4">Gestão de assinaturas e bloqueios de rede.</p>
        </div>
        <div className="bg-[#1a0a2e] p-2 rounded-2xl flex items-center gap-4 border border-white/5">
          <Search className="ml-4 text-slate-500" size={18} />
          <input 
            placeholder="Pesquisar terminal..." 
            className="bg-transparent border-0 outline-none p-4 text-white font-bold w-64"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="space-y-4">
        {filtered.map(office => (
          <div key={office.uid} className="glass-panel p-8 border border-white/5 flex items-center justify-between group hover:border-cyan-400/20 transition-all">
             <div className="flex items-center gap-8">
               <div className={`w-16 h-16 rounded-2xl flex items-center justify-center border transition-all ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.1)]' : 'bg-rose-500/10 border-rose-500/30 text-rose-400'}`}>
                 <Building2 size={32} />
               </div>
               <div>
                 <div className="flex items-center gap-4">
                   <h4 className="text-xl font-black text-white italic tracking-tight uppercase">{office.officeName}</h4>
                   <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-rose-500 text-white animate-pulse'}`}>
                     {office.subscriptionStatus === 'PAID' ? 'ASSINATURA ATIVA' : 'PENDENTE/EXPIRADO'}
                   </span>
                 </div>
                 <div className="flex items-center gap-4 mt-2">
                   <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{office.email}</p>
                   <span className="w-1 h-1 bg-slate-800 rounded-full"></span>
                   <p className="text-[10px] font-black text-cyan-400 uppercase tracking-widest flex items-center gap-2">
                     <Clock size={12} /> Expira em: {office.subscriptionExpiresAt?.toDate().toLocaleDateString()}
                   </p>
                 </div>
               </div>
             </div>

             <div className="flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all">
                <button 
                  onClick={() => toggleSubscription(office.uid, office.subscriptionStatus)}
                  className={`flex items-center gap-3 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${office.subscriptionStatus === 'PAID' ? 'bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white' : 'bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-black'}`}
                >
                  <DollarSign size={16}/> {office.subscriptionStatus === 'PAID' ? 'Suspender Pago' : 'Confirmar Pagamento'}
                </button>
                <button 
                  onClick={() => toggleStatus(office.uid, office.status)}
                  className={`p-3 rounded-xl transition-all ${office.status === 'active' ? 'bg-amber-500/10 text-amber-500 hover:bg-amber-500 hover:text-black' : 'bg-cyan-500/10 text-cyan-500 hover:bg-cyan-500 hover:text-black'}`}
                  title={office.status === 'active' ? 'Bloquear Acesso' : 'Liberar Acesso'}
                >
                  <Ban size={18}/>
                </button>
                <button 
                  // Fix: use generic del method as delOffice is missing
                  onClick={() => { if(confirm('Exclusão Permanente! Tem certeza?')) dbService.del('users', office.uid); }}
                  className="p-3 bg-white/5 text-slate-700 hover:bg-rose-600 hover:text-white rounded-xl transition-all"
                >
                  <Trash2 size={18}/>
                </button>
             </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="py-40 text-center flex flex-col items-center">
            <ShieldAlert size={80} className="text-white/5 mb-8" />
            <p className="text-slate-700 font-black uppercase tracking-[0.6em] italic">Nenhum terminal detectado no setor.</p>
          </div>
        )}
      </div>
    </div>
  );
};

