}

export type ViewState = 
  | 'MASTER_DASHBOARD' | 'OFFICE_MANAGEMENT' | 'MY_HUB' | 'PRODUCTS' | 'CUSTOMERS' 
  | 'ORDERS' | 'EXPENSES' | 'AI_INSIGHTS' | 'REFERRALS' | 'SETTINGS' | 'QUOTES'
  | 'SALES_HISTORY' | 'CALENDAR' | 'RECEIVABLES' | 'BACKUP' | 'COMPANY_SETTINGS';

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Gift, BrainCircuit, Settings, Grid3X3, 
  ShoppingCart, Lock, MessageCircle, FileText
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');
        if (p.status === 'blocked') { alert("Terminal Bloqueado por Segurança."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-16 h-16 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin box-glow-cyan"></div>
      <p className="mt-6 font-terminal text-[10px] text-cyan-400 uppercase tracking-[0.5em] animate-pulse">Sincronizando Nexus Core...</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const contactSuperadmin = () => {
    const msg = encodeURIComponent(`Olá! Sou do escritório ${profile?.officeName} (${profile?.email}) e gostaria de liberar meu acesso total ao Facindemais OS.`);
    window.open(`https://wa.me/5511999999999?text=${msg}`, '_blank');
  };

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-10 p-6 text-center animate-fade-in">
          <div className="w-24 h-24 bg-rose-500 rounded-[2rem] flex items-center justify-center shadow-lg border border-rose-400/50 box-glow-rose"><Lock size={48} className="text-white"/></div>
          <div className="max-w-md">
            <h2 className="text-4xl font-black text-white italic tracking-tighter uppercase mb-2 text-glow-rose">Limite Excedido</h2>
            <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Protocolo de Teste Finalizado. {salesCount}/3 Vendas Realizadas.</p>
          </div>
          <div className="nexus-card p-12 border-cyan-400/50 w-full max-w-lg bg-cyan-400/5 box-glow-cyan">
            <p className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.3em] mb-4 italic">CHAVE PIX OPERACIONAL</p>
            <div className="bg-black/80 p-6 rounded-2xl border border-white/10 font-mono text-white break-all mb-8 select-all cursor-pointer hover:border-cyan-400 transition-colors">giufarlosdias@hotmail.com</div>
            <button onClick={contactSuperadmin} className="flex items-center gap-4 bg-[#25D366] text-white w-full py-6 rounded-2xl font-black uppercase text-xs tracking-widest hover:scale-105 transition-all shadow-xl shadow-green-500/20">
               <MessageCircle size={24} /> Falar com Administrador
            </button>
          </div>
          <button onClick={() => signOut(auth)} className="text-slate-700 font-black uppercase text-[10px] tracking-[0.5em] hover:text-rose-500 transition-colors">Encerrar Sessão Segura</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Operacional" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>
      <aside className="w-24 lg:w-72 border-r border-white/5 bg-[#0c0628]/80 backdrop-blur-3xl flex flex-col p-6 z-20">
        <div className="flex items-center gap-5 mb-16 px-2 group">
          <div className="w-12 h-12 bg-cyan-400 rounded-2xl flex items-center justify-center shadow-lg shadow-cyan-400/20 shrink-0 group-hover:rotate-12 transition-transform box-glow-cyan"><Zap size={24} className="text-black fill-current"/></div>
          <div className="hidden lg:block"><span className="font-terminal font-black text-lg block text-glow-cyan tracking-tight">RADIANT OS</span><span className="text-[8px] font-black text-slate-500 tracking-[0.3em] uppercase opacity-60">Nexus v2.0</span></div>
        </div>
        <nav className="flex-1 space-y-6">
          {isSuper ? (
            <>
              <button onClick={()=>setView('MASTER_DASHBOARD')} className={`nav-btn ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard/></button>
              <button onClick={()=>setView('OFFICE_MANAGEMENT')} className={`nav-btn ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2/></button>
            </>
          ) : (
            <>
              <button onClick={()=>setView('MY_HUB')} className={`nav-btn ${view==='MY_HUB'?'active':''}`} title="Central Hub"><Grid3X3/></button>
              <button onClick={()=>setView('ORDERS')} className={`nav-btn ${view==='ORDERS'?'active':''}`} title="Vendas"><ShoppingCart/></button>
              <button onClick={()=>setView('QUOTES')} className={`nav-btn ${view==='QUOTES'?'active':''}`} title="Orçamentos"><FileText/></button>
              <button onClick={()=>setView('REFERRALS')} className={`nav-btn ${view==='REFERRALS'?'active':''}`} title="Indicações"><Gift/></button>
            </>
          )}
        </nav>
        <div className="pt-8 border-t border-white/5 space-y-6">
          <button onClick={() => setView('SETTINGS')} className={`nav-btn ${view === 'SETTINGS' ? 'active' : ''}`}><Settings/></button>
          <button onClick={() => signOut(auth)} className="nav-btn text-rose-500 hover:bg-rose-500/10"><LogOut/></button>
        </div>
      </aside>
      <main className="flex-1 overflow-y-auto p-8 lg:p-14 relative z-10 custom-scrollbar">{renderView()}</main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { FileText, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Calendar, FileType, Briefcase } from 'lucide-react';
