  quotes: Quote[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const QuotesView: React.FC<QuotesViewProps> = ({ quotes, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [items, setItems] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [validUntil, setValidUntil] = useState('');
  const [notes, setNotes] = useState('');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1', type: 'SERVICE' as any });

  const addItem = (product: Product) => {
    setItems(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const addManualItem = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha a descrição e o valor.");
    setItems(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: manualItem.type
    }]);
    setManualItem({ name: '', price: '', qty: '1', type: 'SERVICE' });
  };

  const shareQuote = (quote: Quote) => {
    const customer = customers.find(c => c.id === quote.customerId);
    const dateStr = new Date(quote.createdAt?.toDate()).toLocaleDateString('pt-BR');

    let msg = `*📄 ORÇAMENTO - ${profile.officeName}*\n`;
    msg += `------------------------------------------\n`;
    msg += `*Data:* ${dateStr}\n`;
    msg += `*Cliente:* ${quote.customerName}\n`;
    msg += `*Validade:* ${new Date(quote.validUntil).toLocaleDateString('pt-BR')}\n`;
    msg += `------------------------------------------\n\n`;

    msg += `*ITENS DA PROPOSTA:*\n`;
    quote.items.forEach(item => {
      msg += `• [${item.type}] ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });

    msg += `\n*TOTAL DA PROPOSTA: R$ ${quote.total.toFixed(2)}*\n\n`;
    if(quote.notes) msg += `*OBSERVAÇÕES:* ${quote.notes}\n`;
    msg += `------------------------------------------\n`;
    msg += `_Gerado por Radiant OS - Facindemais_`;

    const phone = customer?.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (items.length === 0 || !selectedCustomerId || !validUntil) return alert('Selecione cliente, itens e validade.');
    setIsProcessing(true);
    try {
      const total = items.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customer = customers.find(c => c.id === selectedCustomerId);

      const quoteData = {
        customerId: selectedCustomerId,
        customerName: customer?.name || 'CLIENTE',
        items,
        total,
        status: 'SENT',
        validUntil,
        notes
      };

      await dbService.add('quotes', userId, quoteData);
      setIsCreating(false);
      setItems([]);
      setSelectedCustomerId('');
      setValidUntil('');
      setNotes('');
    } catch (e) {
      alert('Erro ao salvar orçamento.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-24">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-purple leading-none uppercase">Orçamentos</h2>
           <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.4em] mt-4 opacity-60">Propostas de Mão de Obra e Materiais.</p>
        </div>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-10 py-5 rounded-2xl flex items-center gap-3 box-glow-purple" style={{background: 'linear-gradient(90deg, #bc13fe, #7a00ff)', boxShadow: '0 0 20px rgba(188, 19, 254, 0.4)'}}><Plus /> CRIAR PROPOSTA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          <div className="lg:col-span-2 space-y-8">
            <div className="nexus-card p-8 border-dashed border-2 border-purple-500/20">
              <h4 className="text-[10px] font-black text-purple-400 uppercase tracking-widest mb-6 flex items-center gap-3"><Briefcase size={16}/> Mão de Obra / Serviço Avulso</h4>
              <div className="flex flex-wrap gap-4">
                <input placeholder="Descrição do serviço ou item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 min-w-[200px] bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none focus:border-purple-400 transition-all" />
                <input placeholder="Preço" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-32 bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none focus:border-purple-400" />
                <select value={manualItem.type} onChange={e=>setManualItem({...manualItem, type: e.target.value as any})} className="bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none">
                  <option value="SERVICE">SERVIÇO</option>
                  <option value="PRODUCT">PRODUTO</option>
                  <option value="LABOR">MÃO DE OBRA</option>
                </select>
                <button onClick={addManualItem} className="bg-purple-500 text-white px-6 rounded-xl font-black hover:scale-105 transition-all shadow-lg shadow-purple-500/20"><Plus/></button>
              </div>
            </div>

            <div className="bg-[#0c0628]/80 p-6 rounded-3xl border border-white/5 flex items-center gap-4">
              <Search className="text-purple-400" />
              <input placeholder="Pesquisar catálogo de itens e peças..." className="bg-transparent flex-1 outline-none text-white font-bold text-lg" value={search} onChange={e => setSearch(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addItem(p)} className="nexus-card p-6 text-left border-white/5 hover:border-purple-500/50 transition-all group">
                   <p className="font-black text-white truncate uppercase mb-1 group-hover:text-purple-400">{p.name}</p>
                   <div className="flex justify-between items-end">
                      <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest">{p.type}</p>
                      <p className="text-purple-400 font-black text-xl">R$ {p.price.toFixed(2)}</p>
                   </div>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-10 h-fit sticky top-6 border-purple-500/30">
            <div className="flex justify-between items-center mb-10 pb-6 border-b border-white/5">
              <h3 className="font-terminal font-black text-lg text-glow-purple">PROPOSTA #000</h3>
              <button onClick={() => setIsCreating(false)} className="p-2 hover:bg-rose-500/10 rounded-lg transition-colors"><X className="text-slate-500 hover:text-rose-500"/></button>
            </div>

            <div className="space-y-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-purple-400 uppercase tracking-widest">Identidade do Cliente</label>
                <select required value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none focus:border-purple-400">
                  <option value="">SELECIONE UM CLIENTE</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-purple-400 uppercase tracking-widest">Validade da Proposta</label>
                <input type="date" value={validUntil} onChange={e => setValidUntil(e.target.value)} className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none focus:border-purple-400" />
              </div>

              <div className="space-y-3 max-h-[250px] overflow-y-auto pr-2 custom-scrollbar">
                {items.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center bg-white/5 p-4 rounded-2xl border border-white/5 group">
                    <div className="flex-1">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-tighter mb-1">{item.type}</div>
                      <div className="text-xs font-black text-white uppercase truncate">{item.nameAtTime}</div>
                    </div>
                    <div className="text-right ml-4">
                      <div className="text-purple-400 font-black text-sm">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</div>
                      <button onClick={() => setItems(prev => prev.filter((_, i) => i !== idx))} className="text-rose-500 mt-1 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={12}/></button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-purple-400 uppercase tracking-widest">Observações Técnicas</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder="Condições de pagamento, prazos de entrega..." className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white text-xs outline-none focus:border-purple-400 h-24 resize-none" />
              </div>

              <div className="pt-8 border-t border-white/5">
                <div className="flex justify-between items-end mb-8">
                   <span className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Valor Total</span>
                   <span className="text-4xl font-black text-white italic tracking-tighter text-glow-purple">R$ {items.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || items.length === 0} onClick={finalize} className="w-full bg-purple-600 text-white py-6 rounded-2xl font-black text-lg flex justify-center gap-4 hover:bg-purple-500 transition-all shadow-xl shadow-purple-600/30">
                  {isProcessing ? <Loader2 className="animate-spin"/> : <Zap className="fill-current"/>} GERAR PROPOSTA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           {quotes.map(q => (
             <div key={q.id} className="nexus-card p-10 group hover:border-purple-500/50 transition-all relative">
                <div className="absolute top-8 right-8 flex gap-3 opacity-0 group-hover:opacity-100 transition-all">
                   <button onClick={() => shareQuote(q)} className="p-3 bg-purple-500/10 text-purple-400 border border-purple-500/20 rounded-xl hover:bg-purple-500 hover:text-white transition-all"><Smartphone size={18}/></button>
                   <button onClick={() => dbService.del('quotes', q.id)} className="p-3 bg-rose-500/10 text-rose-500 border border-rose-500/20 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={18}/></button>
                </div>
                <div className="w-16 h-16 rounded-2xl bg-purple-500/10 border border-purple-500/20 flex items-center justify-center text-purple-400 mb-8 box-glow-purple">
                   <FileText size={32} />
                </div>
                <h4 className="font-black text-white text-xl uppercase tracking-tight mb-2 truncate">{q.customerName}</h4>
                <p className="text-purple-400 font-black text-3xl italic tracking-tighter mb-8">R$ {q.total.toFixed(2)}</p>
                <div className="flex justify-between items-center border-t border-white/5 pt-6">
                   <div>
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Status Rede</p>
                      <span className="px-3 py-1 bg-emerald-500/10 text-emerald-500 text-[8px] font-black rounded-lg border border-emerald-500/20 uppercase tracking-widest">Enviado</span>
                   </div>
                   <div className="text-right">
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Expira em</p>
                      <p className="text-[10px] font-black text-white uppercase">{new Date(q.validUntil).toLocaleDateString()}</p>
                   </div>
                </div>
             </div>
           ))}
           {quotes.length === 0 && (
             <div className="col-span-full py-40 text-center nexus-card border-dashed">
                <FileText size={64} className="text-white/5 mx-auto mb-8" />
                <p className="text-slate-700 font-black uppercase text-sm tracking-[0.5em] italic">Nenhuma proposta ativa no terminal.</p>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

export default QuotesView;

