import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, Cpu, CreditCard, Clock, ShoppingBag, User } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [status, setStatus] = useState<'PAID' | 'QUOTE'>('PAID');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      // Fix: Added missing 'type' property required by OrderItem interface
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha nome e valor.");
    // Fix: Added missing 'type' property required by OrderItem interface
    const newItem: OrderItem = {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    };
    setCart(prev => [...prev, newItem]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const generateWhatsAppReceipt = (orderData: any, customerObj?: Customer) => {
    const total = orderData.total;
    const dateStr = new Date().toLocaleDateString('pt-BR');

    let msg = `*📄 COMPROVANTE DE VENDA - ${profile.officeName}*\n`;
    msg += `------------------------------------------\n`;
    if(profile.phone) msg += `*📞 Contato:* ${profile.phone}\n`;
    if(profile.address) msg += `*📍 Endereço:* ${profile.address}\n`;
    msg += `------------------------------------------\n`;
    msg += `*🗓 Data:* ${dateStr}\n`;
    msg += `*👤 Cliente:* ${customerObj ? customerObj.name : 'Consumidor Final'}\n`;
    msg += `------------------------------------------\n\n`;

    msg += `*📦 ITENS:*\n`;
    orderData.items.forEach((item: any) => {
      msg += `• ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });

    msg += `\n*💰 TOTAL: R$ ${total.toFixed(2)}*\n`;
    msg += `*💳 FORMA:* ${orderData.paymentMethod}\n`;

    if (orderData.paymentMethod === 'PIX' && profile.pixKey) {
      msg += `\n*🔑 CHAVE PIX:* ${profile.pixKey}\n`;
    }

    if (orderData.paymentMethod === 'DEFERRED' && orderData.installments > 1) {
      msg += `\n*🗓 PARCELAMENTO:* \n`;
      const installmentValue = total / orderData.installments;
      for (let i = 1; i <= orderData.installments; i++) {
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + (i * 30));
        msg += `${i}ª: R$ ${installmentValue.toFixed(2)} (${dueDate.toLocaleDateString('pt-BR')})\n`;
      }
    }

    msg += `\n------------------------------------------\n`;
    msg += `_Obrigado! Gerado por Facindemais OS_`;

    const phone = customerObj?.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customerObj = customers.find(c => c.id === selectedCustomerId);

      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: status === 'QUOTE' ? 'QUOTE' : (paymentMethod === 'DEFERRED' ? 'PENDING' : 'PAID'),
        paymentMethod,
        installments: paymentMethod === 'DEFERRED' ? installments : 1
      };

      await dbService.add('orders', userId, orderData);
      generateWhatsAppReceipt(orderData, customerObj);

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setInstallments(1);
    } catch (e) {
      alert('Erro ao processar venda.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none">Vendas</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-4 rounded-2xl flex items-center gap-3"><Plus /> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-dashed border-2 border-cyan-400/20">
              <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2"><ShoppingBag size={14}/> Item Avulso</h4>
              <div className="flex gap-3">
                <input placeholder="Produto..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 bg-black/40 border border-white/5 p-3 rounded-xl text-white outline-none focus:border-cyan-400" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-24 bg-black/40 border border-white/5 p-3 rounded-xl text-white outline-none focus:border-cyan-400" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-xl font-black hover:scale-105 transition-all"><Plus/></button>
              </div>
            </div>

            <div className="bg-[#0c0628]/80 p-5 rounded-3xl border border-white/5 flex items-center gap-4">
              <Search className="text-cyan-400" />
              <input placeholder="Pesquisar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-lg" value={search} onChange={e => setSearch(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
              {filteredProducts.map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-5 text-left border-white/5 hover:border-cyan-400/50 transition-all">
                   <p className="font-black text-white truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-xl">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-8 h-fit sticky top-6 border-cyan-400/30">
            <div className="flex justify-between items-center mb-6 pb-4 border-b border-white/5">
              <h3 className="font-terminal font-black text-lg text-glow-cyan">CHECKOUT</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500 hover:text-rose-500"/></button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Cliente</label>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/5 p-4 rounded-xl text-white outline-none">
                  <option value="">CONSUMIDOR FINAL</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Pagamento</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => setPaymentMethod('PIX')} className={`p-3 rounded-xl border text-[9px] font-black ${paymentMethod === 'PIX' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>PIX</button>
                  <button onClick={() => setPaymentMethod('CASH')} className={`p-3 rounded-xl border text-[9px] font-black ${paymentMethod === 'CASH' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>DINHEIRO</button>
                  <button onClick={() => setPaymentMethod('DEFERRED')} className={`p-3 rounded-xl border text-[9px] font-black ${paymentMethod === 'DEFERRED' ? 'border-rose-500 text-rose-500 bg-rose-500/10' : 'border-white/5 text-slate-500'}`}>A PRAZO</button>
                  <button onClick={() => setPaymentMethod('CREDIT_CARD')} className={`p-3 rounded-xl border text-[9px] font-black ${paymentMethod === 'CREDIT_CARD' ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>CARTÃO</button>
                </div>
              </div>

              {paymentMethod === 'DEFERRED' && (
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-rose-500 uppercase">Parcelas</label>
                   <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full bg-black/40 border border-rose-500/20 p-3 rounded-xl text-white outline-none">
                     {[1,2,3,4,5,6,10,12].map(n => <option key={n} value={n}>{n}x</option>)}
                   </select>
                </div>
              )}

              <div className="max-h-[200px] overflow-y-auto space-y-2">
                {cart.map(item => (
                  <div key={item.productId} className="flex justify-between items-center bg-white/5 p-3 rounded-xl border border-white/5">
                    <div className="text-xs font-bold text-white uppercase truncate flex-1">{item.nameAtTime}</div>
                    <div className="text-cyan-400 font-black text-sm">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</div>
                    <button onClick={() => setCart(prev => prev.filter(i => i.productId !== item.productId))} className="ml-3 text-rose-500"><Trash2 size={14}/></button>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Total</span>
                   <span className="text-3xl font-black text-white italic tracking-tighter glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-2xl font-black text-lg flex justify-center gap-3">
                  {isProcessing ? <Loader2 className="animate-spin"/> : <Zap/>} FINALIZAR E ENVIAR
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="nexus-card overflow-x-auto">
           <table className="w-full text-left">
             <thead>
               <tr className="border-b border-white/5 bg-white/5">
                 <th className="px-6 py-5 text-[10px] font-black text-cyan-400 uppercase tracking-widest">ID Log</th>
                 <th className="px-6 py-5 text-[10px] font-black text-cyan-400 uppercase tracking-widest">Cliente</th>
                 <th className="px-6 py-5 text-[10px] font-black text-cyan-400 uppercase tracking-widest">Total</th>
                 <th className="px-6 py-5 text-right">Ação</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-white/5">
               {orders.map(o => (
                 <tr key={o.id} className="hover:bg-white/5">
                   <td className="px-6 py-5 font-mono text-[10px] text-slate-500">#{o.id.substring(0,6).toUpperCase()}</td>
                   <td className="px-6 py-5 font-black text-white text-sm uppercase">{customers.find(c => c.id === o.customerId)?.name || 'CONSUMIDOR'}</td>
                   <td className="px-6 py-5 font-black text-cyan-400">R$ {o.total.toFixed(2)}</td>
                   <td className="px-6 py-5 text-right flex justify-end gap-2">
                      <button onClick={()=>generateWhatsAppReceipt(o, customers.find(c=>c.id===o.customerId))} className="p-2 text-cyan-400 hover:bg-cyan-400/10 rounded-lg"><Smartphone size={16}/></button>
                      <button onClick={()=>dbService.del('orders', o.id)} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-lg"><Trash2 size={16}/></button>
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Gift, BrainCircuit, Settings, Grid3X3, 
  ShoppingCart, Lock, MessageCircle, FileText
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');
        if (p.status === 'blocked') { alert("Terminal Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-12 h-12 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin box-glow-cyan"></div>
      <p className="mt-4 font-terminal text-[9px] text-cyan-400 uppercase tracking-[0.4em] animate-pulse">Sincronizando Nexus...</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const contactSuperadmin = () => {
    const msg = encodeURIComponent(`Olá! Sou do escritório ${profile?.officeName} (${profile?.email}) e gostaria de liberar meu acesso ao Facindemais OS.`);
    window.open(`https://wa.me/5511999999999?text=${msg}`, '_blank');
  };

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full h-full lg:h-auto gap-2 lg:gap-6 px-4 lg:px-0">
      {isSuper ? (
        <>
          <button onClick={()=>setView('MASTER_DASHBOARD')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard size={24}/></button>
          <button onClick={()=>setView('OFFICE_MANAGEMENT')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2 size={24}/></button>
        </>
      ) : (
        <>
          <button onClick={()=>setView('MY_HUB')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={24}/></button>
          <button onClick={()=>setView('ORDERS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='ORDERS'?'active':''}`}><ShoppingCart size={24}/></button>
          <button onClick={()=>setView('QUOTES')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='QUOTES'?'active':''}`}><FileText size={24}/></button>
          <button onClick={()=>setView('REFERRALS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='REFERRALS'?'active':''}`}><Gift size={24}/></button>
        </>
      )}
      <div className="hidden lg:block w-full h-px bg-white/5 my-4"></div>
      <button onClick={() => setView('SETTINGS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view === 'SETTINGS' ? 'active' : ''}`}><Settings size={24}/></button>
      <button onClick={() => signOut(auth)} className="nav-btn p-3 lg:p-5 flex-1 lg:w-full text-rose-500 hover:bg-rose-500/10"><LogOut size={24}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-rose-500 rounded-3xl flex items-center justify-center shadow-lg box-glow-rose"><Lock size={32} className="text-white"/></div>
          <div className="max-w-md">
            <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter text-glow-rose">Limite Atingido</h2>
            <p className="text-slate-500 font-bold text-[9px] uppercase tracking-widest mt-2">Adquira a licença para continuar operando.</p>
          </div>
          <div className="nexus-card p-8 w-full max-w-sm bg-cyan-400/5 box-glow-cyan">
            <p className="text-[9px] font-black text-cyan-400 uppercase tracking-widest mb-4 italic">CHAVE PIX</p>
            <div className="bg-black/60 p-4 rounded-xl border border-white/5 font-mono text-white text-xs break-all mb-6 select-all">giufarlosdias@hotmail.com</div>
            <button onClick={contactSuperadmin} className="flex items-center justify-center gap-3 bg-[#25D366] text-white w-full py-4 rounded-xl font-black uppercase text-[10px] tracking-widest">
               <MessageCircle size={20} /> FALAR COM SUPORTE
            </button>
          </div>
          <button onClick={() => signOut(auth)} className="text-slate-700 font-black uppercase text-[9px] tracking-widest">Sair do Sistema</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Ativo" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

      {/* Sidebar Desktop */}
      <aside className="hidden lg:flex w-72 border-r border-white/5 bg-[#0c0628]/80 backdrop-blur-3xl flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-16 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg box-glow-cyan"><Zap size={20} className="text-black fill-current"/></div>
          <div><span className="font-terminal font-black text-lg block text-glow-cyan">RADIANT</span><span className="text-[8px] font-black text-slate-500 tracking-[0.3em] uppercase">v2.0</span></div>
        </div>
        <NavContent />
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-4 md:p-10 relative z-10 custom-scrollbar pb-24 lg:pb-10">
        {renderView()}
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-20 bg-[#0c0628]/95 backdrop-blur-3xl border-t border-white/5 flex items-center z-50">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ShoppingCart, Plus, Trash2, Search, X, Loader2, Zap, Smartphone, ShoppingBag } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type }];
    });
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    const newItem: OrderItem = {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    };
    setCart(prev => [...prev, newItem]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const generateWhatsAppReceipt = (orderData: any, customerObj?: Customer) => {
    const total = orderData.total;
    const dateStr = new Date().toLocaleDateString('pt-BR');
    let msg = `*📄 RECIBO - ${profile.officeName}*\n\n`;
    msg += `*Data:* ${dateStr}\n`;
    msg += `*Cliente:* ${customerObj ? customerObj.name : 'Venda Rápida'}\n`;
    msg += `--------------------------\n`;
    orderData.items.forEach((item: any) => {
      msg += `• ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });
    msg += `--------------------------\n`;
    msg += `*TOTAL: R$ ${total.toFixed(2)}*\n`;
    msg += `*PAGAMENTO:* ${orderData.paymentMethod}\n\n`;
    msg += `_Obrigado pela preferência!_`;

    const phone = customerObj?.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments: paymentMethod === 'DEFERRED' ? installments : 1
      };
      await dbService.add('orders', userId, orderData);
      generateWhatsAppReceipt(orderData, customers.find(c => c.id === selectedCustomerId));
      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5">
