}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type }];
    });
  };

  const updateQty = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    const newItem: OrderItem = {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    };
    setCart(prev => [...prev, newItem]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const generateWhatsAppReceipt = (orderData: any, customerObj?: Customer) => {
    const total = orderData.total;
    const dateStr = new Date().toLocaleDateString('pt-BR');
    let msg = `*📄 RECIBO - ${profile.officeName}*\n\n`;
    msg += `*Data:* ${dateStr}\n`;
    msg += `*Cliente:* ${customerObj ? customerObj.name : 'Venda Rápida'}\n`;
    msg += `--------------------------\n`;
    orderData.items.forEach((item: any) => {
      msg += `• ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });
    msg += `--------------------------\n`;
    msg += `*TOTAL: R$ ${total.toFixed(2)}*\n`;
    msg += `*PAGAMENTO:* ${orderData.paymentMethod} ${orderData.installments > 1 ? `(${orderData.installments}x)` : ''}\n\n`;
    msg += `_Obrigado pela preferência!_`;

    const phone = customerObj?.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments: installments
      };
      await dbService.add('orders', userId, orderData);
      generateWhatsAppReceipt(orderData, customers.find(c => c.id === selectedCustomerId));
      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setInstallments(1);
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5">
              <div className="flex gap-2">
                <input placeholder="Item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 bg-black/40 border border-white/5 p-3 rounded-lg text-white outline-none text-sm" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-20 bg-black/40 border border-white/5 p-3 rounded-lg text-white outline-none text-sm" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-lg font-black"><Plus/></button>
              </div>
            </div>

            <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex items-center gap-3">
              <Search className="text-cyan-400" size={18}/>
              <input placeholder="Filtrar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[300px] overflow-y-auto pr-1">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-4 text-left border-white/5 hover:border-cyan-400/30">
                   <p className="font-black text-white text-[10px] truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-sm mt-1">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-6 lg:p-8 h-fit border-cyan-400/30">
            <div className="flex justify-between items-center mb-6 border-b border-white/5 pb-4">
              <h3 className="font-terminal font-black text-sm text-glow-cyan uppercase">Resumo Checkout</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500"/></button>
            </div>
            <div className="space-y-6">
              <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-xs">
                <option value="">CONSUMIDOR FINAL</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
              </select>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-xs">
                  {[1,2,3,4,5,6,10,12,18,24].map(n => <option key={n} value={n}>{n}x</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-2">
                {['PIX', 'CASH', 'CREDIT_CARD', 'DEFERRED'].map(m => (
                  <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-3 rounded-lg border text-[8px] font-black ${paymentMethod === m ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>{m}</button>
                ))}
              </div>

              <div className="max-h-[150px] overflow-y-auto space-y-2">
                {cart.map((item, idx) => (
                  <div key={idx} className="flex flex-col bg-white/5 p-3 rounded-lg">
                    <div className="flex justify-between text-[10px] font-bold mb-2">
                      <span className="text-white truncate flex-1 uppercase">{item.nameAtTime}</span>
                      <button onClick={() => setCart(cart.filter((_,i)=>i!==idx))} className="text-rose-500"><Trash2 size={12}/></button>
                    </div>
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-2">
                          <button onClick={() => updateQty(item.productId, -1)} className="p-1 bg-white/5 rounded text-white"><Minus size={10}/></button>
                          <span className="text-cyan-400 font-black text-xs">{item.quantity}</span>
                          <button onClick={() => updateQty(item.productId, 1)} className="p-1 bg-white/5 rounded text-white"><Plus size={10}/></button>
                       </div>
                       <span className="text-white font-black text-xs">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Total</span>
                   <span className="text-3xl font-black text-white italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-xl font-black text-[12px] flex justify-center gap-2">
                  {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>} FINALIZAR VENDA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {orders.map(o => (
             <div key={o.id} className="nexus-card p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 group">
                <div>
                   <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest">#{o.id.substring(0,6)} • {o.paymentMethod} {o.installments && o.installments > 1 ? `(${o.installments}x)` : ''}</p>
                   <p className="text-lg font-black text-white italic tracking-tight mt-1 uppercase">
                     {customers.find(c => c.id === o.customerId)?.name || 'Venda Rápida'}
                   </p>
                </div>
                <div className="flex items-center gap-6 w-full sm:w-auto justify-between border-t sm:border-t-0 border-white/5 pt-4 sm:pt-0">
                   <p className="text-2xl font-black text-cyan-400 italic tracking-tighter text-glow-cyan">R$ {o.total.toFixed(2)}</p>
                   <div className="flex gap-2">
                      <button onClick={()=>generateWhatsAppReceipt(o, customers.find(c=>c.id===o.customerId))} className="p-3 bg-cyan-400/10 text-cyan-400 rounded-xl"><Smartphone size={18}/></button>
                      <button onClick={()=>dbService.del('orders', o.id)} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl"><Trash2 size={18}/></button>
                   </div>
                </div>
             </div>
           ))}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState } from 'react';
import { FileText, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, Calendar, FileType, Briefcase, User, Download } from 'lucide-react';
import { Quote, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface QuotesViewProps {
  quotes: Quote[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const QuotesView: React.FC<QuotesViewProps> = ({ quotes, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [items, setItems] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [installments, setInstallments] = useState(1);
  const [validUntil, setValidUntil] = useState('');
  const [notes, setNotes] = useState('');
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1', type: 'SERVICE' as any });

  const addItem = (product: Product) => {
    setItems(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type as any }];
    });
  };

  const updateQty = (id: string, delta: number) => {
    setItems(prev => prev.map(item => {
      if (item.productId === id) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const addManualItem = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha a descrição e o valor.");
    setItems(prev => [...prev, {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: manualItem.type
    }]);
    setManualItem({ name: '', price: '', qty: '1', type: 'SERVICE' });
  };

  const generatePDFAndShare = (quote: Quote) => {
    // Simulação de PDF através de uma página limpa para impressão
    const customerName = quote.customerId === 'GUEST' ? (quote as any).guestName : quote.customerName;
    const customerPhone = (quote as any).guestPhone || '';

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      const html = `
        <html>
        <head>
          <title>Orçamento #${quote.id}</title>
          <style>
            body { font-family: sans-serif; padding: 40px; color: #333; }
            .header { border-bottom: 2px solid #000; padding-bottom: 20px; margin-bottom: 30px; }
            .office-name { font-size: 24px; font-weight: bold; }
            .items-table { width: 100%; border-collapse: collapse; margin-top: 20px; }
            .items-table th, .items-table td { border-bottom: 1px solid #ddd; padding: 12px; text-align: left; }
            .total-row { font-size: 20px; font-weight: bold; text-align: right; margin-top: 30px; }
            .notes { margin-top: 40px; font-style: italic; color: #666; border-top: 1px solid #eee; padding-top: 20px; }
          </style>
        </head>
        <body onload="window.print()">
          <div class="header">
            <div class="office-name">${profile.officeName}</div>
            <div>${profile.address || ''}</div>
            <div>Contato: ${profile.phone || ''}</div>
          </div>
          <h2>ORÇAMENTO #${quote.id.substring(0,8).toUpperCase()}</h2>
          <p><strong>Cliente:</strong> ${customerName}</p>
          <p><strong>Data:</strong> ${new Date().toLocaleDateString()}</p>
          <p><strong>Validade:</strong> ${new Date(quote.validUntil).toLocaleDateString()}</p>

          <table class="items-table">
            <thead>
              <tr><th>Item</th><th>Tipo</th><th>Qtd</th><th>Unit</th><th>Total</th></tr>
            </thead>
            <tbody>
              ${quote.items.map(i => `
                <tr>
                  <td>${i.nameAtTime}</td>
                  <td>${i.type}</td>
                  <td>${i.quantity}</td>
                  <td>R$ ${i.priceAtTime.toFixed(2)}</td>
                  <td>R$ ${(i.priceAtTime * i.quantity).toFixed(2)}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>

          <div class="total-row">TOTAL: R$ ${quote.total.toFixed(2)}</div>
          <p><strong>Parcelamento:</strong> ${ (quote as any).installments || 1 }x</p>

          <div class="notes">Obs: ${quote.notes || 'Nenhuma'}</div>
        </body>
        </html>
      `;
      printWindow.document.write(html);
      printWindow.document.close();
    }

    // WhatsApp envio
    let msg = `*📄 ORÇAMENTO - ${profile.officeName}*\n\n`;
    msg += `*Cliente:* ${customerName}\n`;
    msg += `*Total:* R$ ${quote.total.toFixed(2)}\n`;
    msg += `*Parcelas:* ${(quote as any).installments || 1}x\n`;
    msg += `*Validade:* ${new Date(quote.validUntil).toLocaleDateString()}\n\n`;
    msg += `_Solicite o PDF detalhado ou confira os itens acima._`;

    const cleanPhone = customerPhone.replace(/\D/g, '') || customers.find(c => c.id === quote.customerId)?.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${cleanPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const finalize = async () => {
    if (items.length === 0 || !validUntil) return alert('Selecione itens e validade.');
    if (!selectedCustomerId && !guestData.name) return alert('Identifique o cliente.');

    setIsProcessing(true);
    try {
      const total = items.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const customer = customers.find(c => c.id === selectedCustomerId);

      const quoteData = {
        customerId: selectedCustomerId || 'GUEST',
        customerName: customer?.name || guestData.name.toUpperCase(),
        guestName: guestData.name.toUpperCase(),
        guestPhone: guestData.phone,
        items,
        total,
        status: 'SENT',
        validUntil,
        notes,
        installments: installments
      };

      await dbService.add('quotes', userId, quoteData);
      setIsCreating(false);
      setItems([]);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setValidUntil('');
      setNotes('');
    } catch (e) { alert('Erro ao salvar.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-24">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-3xl lg:text-5xl font-black text-white italic tracking-tighter text-glow-purple leading-none uppercase">Orçamentos</h2>
           <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.4em] mt-4 opacity-80">Propostas Rápidas de Rede.</p>
        </div>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-8 py-4 rounded-2xl flex items-center gap-3 box-glow-purple text-[10px]" style={{background: 'linear-gradient(90deg, #bc13fe, #7a00ff)'}}><Plus /> NOVO ORÇAMENTO</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          <div className="lg:col-span-2 space-y-8">
            <div className="nexus-card p-6 border-dashed border-2 border-purple-500/30 bg-purple-500/5">
              <h4 className="text-[10px] font-black text-purple-400 uppercase tracking-widest mb-6 flex items-center gap-3"><User size={16}/> Dados do Cliente (Manual ou Seleção)</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                <input placeholder="Nome Completo do Cliente..." value={guestData.name} onChange={e=>setGuestData({...guestData, name: e.target.value})} className="p-4 rounded-xl outline-none bg-black/40 border border-white/5 text-white" />
                <input placeholder="WhatsApp para Envio..." value={guestData.phone} onChange={e=>setGuestData({...guestData, phone: e.target.value})} className="p-4 rounded-xl outline-none bg-black/40 border border-white/5 text-white" />
              </div>
              <p className="text-[9px] text-slate-500 font-black mb-4 uppercase">OU SELECIONE DA REDE</p>
              <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full p-4 rounded-xl text-xs bg-black/40 border border-white/5 text-white">
                  <option value="">NÃO SELECIONADO</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name.toUpperCase()}</option>)}
              </select>
            </div>

            <div className="nexus-card p-6 border-dashed border-2 border-purple-500/30 bg-purple-500/5">
              <h4 className="text-[10px] font-black text-purple-400 uppercase tracking-widest mb-6 flex items-center gap-3"><Briefcase size={16}/> Item Avulso</h4>
              <div className="flex flex-wrap gap-4">
                <input placeholder="Descrição..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 min-w-[200px] p-4 rounded-xl outline-none" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-32 p-4 rounded-xl outline-none" />
                <button onClick={addManualItem} className="bg-purple-500 text-white px-8 rounded-xl font-black shadow-lg shadow-purple-500/40"><Plus/></button>
              </div>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addItem(p)} className="nexus-card p-6 text-left border-white/5 hover:border-purple-500/50 transition-all">
                   <p className="font-black text-white truncate uppercase mb-1 text-xs">{p.name}</p>
                   <p className="text-purple-400 font-black text-lg">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-8 h-fit border-purple-500/40 box-glow-purple">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-white/10">
              <h3 className="font-terminal font-black text-md text-glow-purple uppercase tracking-tight">Proposta</h3>
              <button onClick={() => setIsCreating(false)} className="text-slate-500"><X /></button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[9px] font-black text-purple-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full p-4 rounded-xl text-xs bg-black/40 border border-white/5 text-white">
                  {[1,2,3,4,5,6,10,12].map(n => <option key={n} value={n}>{n}x</option>)}
