                <div className="absolute top-6 right-6 flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                   <button onClick={() => generatePDFAndShare(q)} className="p-3 bg-purple-500/10 text-purple-400 rounded-xl hover:bg-purple-500 hover:text-white transition-all"><Download size={18}/></button>
                   <button onClick={() => dbService.del('quotes', q.id)} className="p-3 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={18}/></button>
                </div>
                <h4 className="font-black text-white text-lg uppercase tracking-tight mb-1 truncate">{q.customerName}</h4>
                <p className="text-purple-400 font-black text-2xl italic tracking-tighter mb-6 text-glow-purple">R$ {q.total.toFixed(2)}</p>
                <div className="flex justify-between items-center border-t border-white/10 pt-4">
                   <span className="text-[7px] font-black text-slate-500 uppercase">{ (q as any).installments || 1 }x Parcelas</span>
                   <p className="text-[9px] font-black text-slate-500 uppercase">Val: {new Date(q.validUntil).toLocaleDateString()}</p>
                </div>
             </div>
           ))}
        </div>
      )}
    </div>
  );
};

