        <form onSubmit={add} className="flex flex-wrap gap-4 w-full md:w-auto">
          <input value={name} onChange={e => setName(e.target.value)} placeholder="Item..." className="flex-1 bg-white/5 border border-white/10 rounded-xl px-5 py-3 text-sm outline-none focus:border-cyan-400" />
          <input value={price} onChange={e => setPrice(e.target.value)} type="number" placeholder="R$" className="w-20 bg-white/5 border border-white/10 rounded-xl px-5 py-3 text-sm outline-none focus:border-cyan-400" />
          <input value={stock} onChange={e => setStock(e.target.value)} type="number" placeholder="Qtd" title="Quantidade em Estoque" className="w-20 bg-white/5 border border-white/10 rounded-xl px-5 py-3 text-sm outline-none focus:border-cyan-400" />
          <button className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]">
            <Plus size={14}/> ADICIONAR
          </button>
        </form>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? <Loader2 className="animate-spin text-cyan-400 mx-auto" /> : items.map(p => (
