import React, { useState } from 'react';
import { updatePassword } from 'firebase/auth';
import { auth, dbService } from '../services/firebase';
import { Settings, Key, ShieldCheck, Loader2, Save, CheckCircle2, AlertTriangle, Cpu, Building2, Smartphone, MapPin, CreditCard, Image as ImageIcon, Upload } from 'lucide-react';
import { UserProfile } from '../types';

interface SettingsViewProps { profile: UserProfile; }

const SettingsView: React.FC<SettingsViewProps> = ({ profile }) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [companyData, setCompanyData] = useState({
    officeName: profile.officeName || '',
    phone: profile.phone || '',
    address: profile.address || '',
    pixKey: profile.pixKey || '',
    logoUrl: profile.logoUrl || ''
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isSavingProfile, setIsSavingProfile] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCompanyData({...companyData, logoUrl: reader.result as string});
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSavingProfile(true);
    try {
      await dbService.updateProfile(profile.uid, companyData);
      setMessage({ text: 'Perfil sincronizado!', type: 'success' });
    } catch (err) { setMessage({ text: 'Erro ao salvar.', type: 'error' }); } finally { setIsSavingProfile(false); }
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) return setMessage({ text: 'Divergência de chaves!', type: 'error' });
    setIsLoading(true);
    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setMessage({ text: 'Criptografia atualizada!', type: 'success' });
        setNewPassword(''); setConfirmPassword('');
      }
    } catch (err: any) { setMessage({ text: 'Erro na re-autenticação.', type: 'error' }); } finally { setIsLoading(false); }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div>
        <h2 className="text-3xl lg:text-5xl font-black text-white italic tracking-tighter text-glow-cyan uppercase">Configurações Nexus</h2>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-2 space-y-12">

          <div className="nexus-card p-8 lg:p-12 bg-gradient-to-br from-[#0c0628] to-black">
             <div className="flex items-center gap-6 mb-12">
                <div className="w-16 h-16 rounded-2xl bg-cyan-400/10 border border-cyan-400/30 flex items-center justify-center text-cyan-400">
                  <Building2 size={32} />
                </div>
                <h3 className="text-2xl font-black text-white italic uppercase">Perfil do Escritório</h3>
              </div>

              <form onSubmit={handleUpdateProfile} className="space-y-8">
                <div className="flex flex-col items-center gap-6 p-8 border-2 border-dashed border-white/5 rounded-3xl mb-8">
                   {companyData.logoUrl ? (
                     <img src={companyData.logoUrl} alt="Logo" className="w-32 h-32 object-contain rounded-2xl" />
                   ) : (
                     <div className="w-32 h-32 bg-white/5 rounded-2xl flex items-center justify-center text-slate-700"><ImageIcon size={48}/></div>
                   )}
                   <label className="cursor-pointer bg-white/5 px-6 py-3 rounded-xl border border-white/10 text-cyan-400 font-black text-[10px] uppercase flex items-center gap-3">
                      <Upload size={16}/> SELECIONAR LOGOTIPO
                      <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
                   </label>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest">Nome Comercial</label>
                    <input required type="text" value={companyData.officeName} onChange={e => setCompanyData({...companyData, officeName: e.target.value})}
                      className="w-full px-5 py-4 bg-black/40 border border-white/10 rounded-2xl text-white font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest">WhatsApp</label>
                    <input type="text" value={companyData.phone} onChange={e => setCompanyData({...companyData, phone: e.target.value})}
                      className="w-full px-5 py-4 bg-black/40 border border-white/10 rounded-2xl text-white font-bold" />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-400 uppercase tracking-widest">Chave PIX</label>
                  <input type="text" value={companyData.pixKey} onChange={e => setCompanyData({...companyData, pixKey: e.target.value})}
                    className="w-full px-5 py-4 bg-black/40 border border-rose-500/10 rounded-2xl text-white font-bold" />
                </div>

                <button disabled={isSavingProfile} type="submit" className="btn-radiant w-full py-6 rounded-2xl font-black text-lg flex items-center justify-center gap-4 active:scale-95 transition-all">
                  {isSavingProfile ? <Loader2 className="animate-spin" /> : <Save size={24} />}
                  SINCRONIZAR PERFIL
                </button>
              </form>
          </div>

          <div className="nexus-card p-8 lg:p-12">
             <div className="flex items-center gap-6 mb-12">
                <div className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-purple-400">
                  <Key size={32} />
                </div>
                <h3 className="text-2xl font-black text-white italic uppercase">Trocar Senha</h3>
              </div>
              <form onSubmit={handleChangePassword} className="space-y-8">
                <input required type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} placeholder="Nova Senha..." className="w-full px-8 py-5 bg-black/40 border border-white/5 rounded-2xl" />
                <input required type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Confirmar..." className="w-full px-8 py-5 bg-black/40 border border-white/5 rounded-2xl" />
                <button disabled={isLoading} type="submit" className="btn-nexus w-full py-6 rounded-2xl font-black text-lg">ATUALIZAR ACESSO</button>
              </form>
          </div>
        </div>

        <div className="space-y-10">
          <div className="nexus-card p-10 flex items-center gap-6">
            <ShieldCheck size={36} className="text-emerald-500" />
            <div><p className="text-white font-black text-lg uppercase italic">Proteção Nexus</p></div>
          </div>
          {message.text && (
            <div className={`p-6 rounded-2xl border font-black text-xs uppercase text-center ${message.type === 'error' ? 'bg-rose-500/10 text-rose-500 border-rose-500/30' : 'bg-emerald-400/10 text-emerald-400 border-emerald-400/30'}`}>
              {message.text}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Gift, BrainCircuit, Settings, Grid3X3, 
  ShoppingCart, Lock, MessageCircle, FileText, Calendar
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import CalendarView from './views/CalendarView';
import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        // Trava Super Admin
        const isMaster = u.email === "giufarlosdias@hotmail.com";
        if (isMaster && p.role !== 'super-admin') {
           await dbService.update('users', u.uid, { role: 'super-admin' });
           p.role = 'super-admin';
        }

        if (p.status === 'blocked') { alert("Terminal Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin' || p.role === 'super-admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="w-12 h-12 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin box-glow-cyan"></div>
      <p className="mt-4 font-terminal text-[9px] text-cyan-400 uppercase tracking-[0.4em] animate-pulse">Sincronizando Nexus...</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full h-full lg:h-auto gap-2 lg:gap-6 px-4 lg:px-0">
      {isSuper ? (
        <>
          <button onClick={()=>setView('MASTER_DASHBOARD')} title="Painel Global" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard size={24}/></button>
          <button onClick={()=>setView('OFFICE_MANAGEMENT')} title="Gestão Escritórios" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2 size={24}/></button>
          <button onClick={()=>setView('MY_HUB')} title="Visão de Operador" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={24}/></button>
        </>
      ) : (
        <>
          <button onClick={()=>setView('MY_HUB')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={24}/></button>
          <button onClick={()=>setView('ORDERS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='ORDERS'?'active':''}`}><ShoppingCart size={24}/></button>
          <button onClick={()=>setView('QUOTES')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='QUOTES'?'active':''}`}><FileText size={24}/></button>
          <button onClick={()=>setView('CALENDAR')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='CALENDAR'?'active':''}`}><Calendar size={24}/></button>
        </>
      )}
      <div className="hidden lg:block w-full h-px bg-white/5 my-4"></div>
      <button onClick={() => setView('SETTINGS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view === 'SETTINGS' ? 'active' : ''}`}><Settings size={24}/></button>
      <button onClick={() => signOut(auth)} className="nav-btn p-3 lg:p-5 flex-1 lg:w-full text-rose-500 hover:bg-rose-500/10"><LogOut size={24}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-rose-500 rounded-3xl flex items-center justify-center shadow-lg box-glow-rose"><Lock size={32} className="text-white"/></div>
          <h2 className="text-2xl font-black text-white uppercase italic">Limite Atingido</h2>
          <p className="text-slate-500 text-[10px] uppercase font-black">Contate o administrador para liberar seu terminal.</p>
          <button onClick={() => signOut(auth)} className="text-rose-500 font-black uppercase text-[10px] tracking-widest mt-10">Sair do Sistema</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      case 'CALENDAR': return <CalendarView />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Nexus" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

      <aside className="hidden lg:flex w-72 border-r border-white/5 bg-[#0c0628]/80 backdrop-blur-3xl flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-16 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg box-glow-cyan"><Zap size={20} className="text-black fill-current"/></div>
          <div><span className="font-terminal font-black text-lg block text-glow-cyan">RADIANT</span><span className="text-[8px] font-black text-slate-500 tracking-[0.3em] uppercase">v2.0</span></div>
        </div>
        <NavContent />
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-10 relative z-10 custom-scrollbar pb-24 lg:pb-10">
        {renderView()}
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-20 bg-[#0c0628]/95 backdrop-blur-3xl border-t border-white/5 flex items-center z-50">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
