  useEffect(() => {
    return dbService.watchNetwork((data) => {
      // Ordenar por data de criação ou nome para estabilidade
      const sorted = [...data].sort((a: any, b: any) => a.officeName.localeCompare(b.officeName));
      setOffices(sorted as UserProfile[]);
    });
  }, []);

  const toggleSubscription = async (uid: string, current: string) => {
    if (processingId) return;
    const next = current === 'PAID' ? 'EXPIRED' : 'PAID';
    if (confirm(`Alterar status de mensalidade do terminal para ${next}?`)) {
      setProcessingId(uid);
      try {
        await dbService.update('users', uid, { subscriptionStatus: next });
      } catch (e) {
        alert("Erro ao atualizar assinatura.");
      } finally {
        setProcessingId(null);
      }
    }
  };

  const toggleStatus = async (uid: string, current: string) => {
    if (processingId) return;
    const next = current === 'active' ? 'blocked' : 'active';
    if (confirm(`Confirmar ${next === 'blocked' ? 'BLOQUEIO' : 'DESBLOQUEIO'} de acesso?`)) {
      setProcessingId(uid);
      try {
        await dbService.update('users', uid, { status: next });
