      </div>

      <div className="space-y-4">
        {filtered.map(office => (
          <div key={office.uid} className={`nexus-card p-8 border border-white/5 flex flex-col lg:flex-row items-center justify-between gap-6 hover:border-orange-400/50 transition-all ${processingId === office.uid ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex items-center gap-8 w-full lg:w-auto">
               <div className={`w-16 h-16 rounded-2xl flex items-center justify-center border transition-all ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'bg-rose-500/10 border-rose-500/30 text-rose-400'}`}>
                 <Building2 size={32} />
               </div>
               <div>
                 <div className="flex items-center gap-4 flex-wrap">
                   <h4 className="text-xl font-black text-white italic tracking-tight uppercase">{office.officeName}</h4>
                   <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${office.subscriptionStatus === 'PAID' ? 'bg-emerald-500 text-black' : 'bg-rose-500 text-white animate-pulse'}`}>
                     {office.subscriptionStatus === 'PAID' ? 'ASSINATURA ATIVA' : 'EXPIRADO'}
                   </span>
                   {office.status === 'blocked' && (
                     <span className="bg-rose-600 text-white px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest">BLOQUEADO</span>
                   )}
                 </div>
                 <div className="flex items-center gap-4 mt-2">
