             </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="py-40 text-center flex flex-col items-center">
            <ShieldAlert size={80} className="text-white/5 mb-8" />
            <p className="text-slate-700 font-black uppercase tracking-[0.6em] italic">Nenhum terminal encontrado.</p>
          </div>
        )}
      </div>
    </div>
  );
};

