                <input required type="text" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="Ex: Operador Zero" />
