                  <input type="email" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="email@nexus.com" />
