              <div className="space-y-2">
                <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest ml-2">Localização Física</label>
                <textarea value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] h-32 resize-none text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="Coordenadas Nexus..." />
