             subscriptionStatus: 'PAID',
             status: 'active',
             subscriptionExpiresAt: Timestamp.fromDate(infiniteDate)
           });
           p.role = 'super-admin';
           p.subscriptionStatus = 'PAID';
           p.status = 'active';
        }

        if (p.status === 'blocked') { alert("Terminal Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin' || p.role === 'super-admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="relative">
        <div className="w-16 h-16 border-2 border-cyan-400/20 rounded-full"></div>
        <div className="absolute top-0 left-0 w-16 h-16 border-t-2 border-cyan-400 rounded-full animate-spin"></div>
        <Zap className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-cyan-400 animate-pulse" size={24}/>
      </div>
      <p className="mt-8 font-terminal text-[10px] text-cyan-400 uppercase tracking-[0.5em] animate-pulse">Sincronizando Nexus OS</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full h-full lg:h-auto gap-2 lg:gap-4 px-4 lg:px-0">
      {isSuper ? (
        <>
          <button onClick={()=>setView('MASTER_DASHBOARD')} title="Painel Global" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard size={22}/></button>
          <button onClick={()=>setView('OFFICE_MANAGEMENT')} title="Gestão Escritórios" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2 size={22}/></button>
          <button onClick={()=>setView('MY_HUB')} title="Visão de Operador" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={22}/></button>
        </>
      ) : (
        <>
          <button onClick={()=>setView('MY_HUB')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={22}/></button>
          <button onClick={()=>setView('ORDERS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='ORDERS'?'active':''}`}><ShoppingCart size={22}/></button>
          <button onClick={()=>setView('QUOTES')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='QUOTES'?'active':''}`}><FileText size={22}/></button>
          <button onClick={()=>setView('CALENDAR')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='CALENDAR'?'active':''}`}><Calendar size={22}/></button>
        </>
      )}
      <div className="hidden lg:block w-8 h-px bg-white/10 mx-auto my-4"></div>
      <button onClick={() => setView('SETTINGS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view === 'SETTINGS' ? 'active' : ''}`}><Settings size={22}/></button>
      <button onClick={() => signOut(auth)} className="nav-btn p-3 lg:p-5 flex-1 lg:w-full text-rose-500 hover:bg-rose-500/10"><LogOut size={22}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-rose-500 rounded-3xl flex items-center justify-center shadow-lg box-glow-rose"><Lock size={32} className="text-white"/></div>
          <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Terminal em Espera</h2>
          <p className="text-slate-500 text-[11px] uppercase font-black tracking-widest max-w-xs">Identificamos atividade pendente de regularização. Contate o administrador.</p>
          <button onClick={() => signOut(auth)} className="text-rose-500 font-black uppercase text-[10px] tracking-[0.5em] mt-10 hover:text-white transition-colors">Encerrar Sessão</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} orders={orders} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} profile={profile!} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      case 'CALENDAR': return <CalendarView />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Nexus" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-30 pointer-events-none"></div>

      <aside className="hidden lg:flex w-72 border-r border-white/5 bg-[#0c0628]/90 backdrop-blur-3xl flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-16 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg box-glow-cyan"><Zap size={20} className="text-black fill-current"/></div>
          <div><span className="font-terminal font-black text-lg block text-glow-cyan">RADIANT</span><span className="text-[8px] font-black text-slate-500 tracking-[0.4em] uppercase opacity-60">CORE 2.0.1</span></div>
        </div>
        <NavContent />
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-12 relative z-10 custom-scrollbar pb-24 lg:pb-12">
        {renderView()}
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-22 bg-[#0c0628]/95 backdrop-blur-3xl border-t border-white/10 flex items-center z-50 px-2 pb-2">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Plus, Search, Mail, Phone, MapPin, Edit2, Trash2, X, UserCheck, Loader2 } from 'lucide-react';
import { Customer, Order } from '../types';
import { dbService } from '../services/firebase';

interface CustomersViewProps {
  customers: Customer[];
  orders: Order[];
  userId: string;
}

const CustomersView: React.FC<CustomersViewProps> = ({ customers, orders, userId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '', address: '' });

  // Fusão automática: Pega os clientes cadastrados + clientes extraídos de vendas que não estão cadastrados
  const unifiedCustomers = useMemo(() => {
    const list = [...customers];

    orders.forEach(order => {
      const gName = (order as any).guestName;
      const gPhone = (order as any).guestPhone;

      if (gName && gName !== 'VENDA RÁPIDA') {
        const alreadyExists = list.some(c => 
          c.name.toLowerCase() === gName.toLowerCase() || 
          (c.phone && c.phone === gPhone)
        );

        if (!alreadyExists) {
          list.push({
            id: `venda-${order.id}`,
            userId: order.userId,
            name: gName,
            phone: gPhone,
            email: 'Origem: Venda PdV'
          } as Customer);
        }
      }
    });

    return list;
  }, [customers, orders]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (editingCustomer) await dbService.update('customers', editingCustomer.id, formData);
      else await dbService.add('customers', userId, formData);
      setIsModalOpen(false);
      setEditingCustomer(null);
      setFormData({ name: '', email: '', phone: '', address: '' });
    } catch (err) { alert("Erro ao salvar cliente."); } finally { setIsSaving(false); }
  };

  const filtered = unifiedCustomers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (c.phone && c.phone.includes(searchTerm))
  );

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-5xl font-black text-white tracking-tighter italic text-glow-cyan leading-none">Rede Nexus<span className="text-white">.</span></h2>
          <p className="text-slate-500 font-bold mt-4 text-xl tracking-wide uppercase opacity-70">Sincronização automática de vendas e cadastros.</p>
        </div>
        <button onClick={() => { setEditingCustomer(null); setIsModalOpen(true); }} className="btn-radiant px-10 py-5 rounded-[2.5rem] flex items-center gap-4 active:scale-95 transition-all">
          <Plus size={28} className="text-black" /> NOVA IDENTIDADE
        </button>
      </div>

      <div className="bg-[#0c0628]/80 p-8 rounded-[3rem] border-2 border-cyan-400/20 flex items-center gap-6 shadow-inner backdrop-blur-3xl focus-within:border-cyan-400 transition-all">
        <Search className="text-cyan-400/50" size={32} />
        <input 
          type="text" 
          placeholder="Localizar operador ou cliente na rede..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-black text-white placeholder:text-slate-700 text-2xl tracking-tight italic" 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filtered.map(customer => (
          <div key={customer.id} className="nexus-card p-10 group relative transition-all hover:scale-[1.03]">
            <div className="absolute top-8 right-8 flex gap-3 opacity-0 group-hover:opacity-100 transition-all">
              <button onClick={() => { setEditingCustomer(customer); setFormData({ name: customer.name, email: customer.email || '', phone: customer.phone || '', address: customer.address || '' }); setIsModalOpen(true); }} className="p-3 text-cyan-400 bg-cyan-400/10 border border-cyan-400/20 rounded-xl hover:bg-cyan-400 hover:text-black transition-all"><Edit2 size={18} /></button>
              {!customer.id.startsWith('venda-') && (
                <button onClick={() => { if(confirm('Excluir registro?')) dbService.del('customers', customer.id); }} className="p-3 text-rose-500 bg-rose-500/10 border border-rose-500/20 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={18} /></button>
              )}
            </div>
            <div className={`w-20 h-20 rounded-[1.8rem] bg-white/5 border-2 flex items-center justify-center font-terminal font-black text-4xl mb-8 group-hover:rotate-12 transition-transform shadow-[0_0_20px_rgba(0,243,255,0.1)] ${customer.id.startsWith('venda-') ? 'border-amber-400/40 text-amber-400' : 'border-cyan-400/20 text-cyan-400'}`}>
              {customer.name.charAt(0).toUpperCase()}
            </div>
            <h3 className="font-black text-white text-2xl mb-8 tracking-tighter text-glow-cyan italic">{customer.name}</h3>
            <div className="space-y-4">
              <div className="flex items-center gap-4 bg-black/40 p-4 rounded-2xl truncate text-[12px] font-black text-slate-400 border border-white/5 uppercase tracking-widest">
                <Mail size={18} className="text-cyan-400/50" /> {customer.email || 'NÃO DEFINIDO'}
              </div>
              <div className="flex items-center gap-4 bg-black/40 p-4 rounded-2xl text-[12px] font-black text-slate-400 border border-white/5 uppercase tracking-widest">
                <Phone size={18} className="text-cyan-400/50" /> {customer.phone || 'NÃO DEFINIDO'}
              </div>
              {customer.id.startsWith('venda-') && (
                <p className="text-[8px] font-black text-amber-500 uppercase tracking-[0.3em] mt-4">Identidade Capturada via PdV</p>
              )}
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-xl p-12 animate-fade-in border-cyan-400">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-3xl font-black text-white italic text-glow-cyan uppercase">{editingCustomer ? 'Modificar' : 'Nova'} Identidade</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-400 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>
            <form onSubmit={handleSave} className="space-y-8">
              <div className="space-y-2">
                <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest ml-2">Nome de Identificação</label>
                <input required type="text" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="Ex: Operador Zero" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest ml-2">Comunicação Digital</label>
                  <input type="email" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="email@nexus.com" />
                </div>
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest ml-2">Célula de Contato</label>
                  <input type="tel" value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="+55 (00) 00000" />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[11px] font-black text-cyan-400 uppercase tracking-widest ml-2">Localização Física</label>
                <textarea value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2.2rem] h-32 resize-none text-white font-bold placeholder:text-slate-700 outline-none focus:border-cyan-400 transition-all text-xl" placeholder="Coordenadas Nexus..." />
              </div>

              <button disabled={isSaving} type="submit" className="btn-radiant w-full py-8 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 mt-8">
                {isSaving ? <Loader2 className="animate-spin" size={28} /> : <UserCheck size={32} className="text-black" />}
                SINCRONIZAR IDENTIDADE
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomersView;

import React, { useState } from 'react';
import { Plus, WalletMinimal, Trash2, X, Loader2, Zap, MessageCircle, Calendar } from 'lucide-react';
import { Expense, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface ExpensesViewProps {
  expenses: Expense[];
  userId: string;
  profile: UserProfile;
}

const ExpensesView: React.FC<ExpensesViewProps> = ({ expenses, userId, profile }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({ description: '', amount: '', category: 'Operacional' });

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await dbService.add('expenses', userId, {
        description: formData.description,
        amount: parseFloat(formData.amount),
        category: formData.category
      });
      setIsModalOpen(false);
      setFormData({ description: '', amount: '', category: 'Operacional' });
    } catch (err) { alert("Erro ao salvar."); } finally { setIsSaving(false); }
  };

  const sendWeeklyReport = () => {
    const lastWeek = new Date();
    lastWeek.setDate(lastWeek.getDate() - 7);

    const recentExpenses = expenses.filter(e => {
        const date = e.createdAt?.toDate() || new Date();
        return date >= lastWeek;
    });

    if (recentExpenses.length === 0) return alert("Nenhum custo registrado nos últimos 7 dias.");

    const total = recentExpenses.reduce((s, e) => s + e.amount, 0);

    let msg = `*📊 RELATÓRIO SEMANAL DE SAÍDAS*\n`;
    msg += `*Terminal:* ${profile.officeName}\n`;
    msg += `*Período:* Últimos 7 dias\n`;
    msg += `--------------------------\n`;
    recentExpenses.forEach(e => {
        msg += `• ${e.description.toUpperCase()} - R$ ${e.amount.toFixed(2)}\n`;
    });
    msg += `--------------------------\n`;
    msg += `*DRENAGEM TOTAL: R$ ${total.toFixed(2)}*\n\n`;
    msg += `_Relatório gerado automaticamente pelo Nexus OS._`;

    const phone = profile.phone?.replace(/\D/g, '') || '';
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
        <div>
          <h2 className="text-4xl lg:text-5xl font-black text-white tracking-tighter italic text-glow-cyan leading-none">Fluxos de Saída<span className="text-white">.</span></h2>
          <p className="text-slate-500 font-bold mt-4 text-xs lg:text-xl tracking-wide uppercase opacity-70">Monitoramento responsivo de custos.</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <button onClick={sendWeeklyReport} className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 px-6 py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-500 hover:text-black transition-all text-[10px] uppercase tracking-widest">
            <MessageCircle size={18} /> Relatório Semanal
          </button>
          <button onClick={() => setIsModalOpen(true)} className="bg-rose-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-[0_0_30px_rgba(244,63,94,0.3)] hover:bg-rose-400 transition-all active:scale-95 text-[10px] uppercase tracking-widest">
            <Plus size={20} /> Registrar Custo
          </button>
        </div>
      </div>

      {/* Versão Desktop: Tabela */}
      <div className="hidden lg:block nexus-card overflow-hidden shadow-2xl border-white/5">
        <table className="w-full text-left min-w-[800px]">
          <thead>
            <tr className="bg-white/5">
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Descrição da Operação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Classificação</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60">Drenagem de Crédito</th>
              <th className="px-10 py-8 text-[11px] font-black text-cyan-400 uppercase tracking-widest opacity-60 text-right">Ação</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {expenses.map(exp => (
              <tr key={exp.id} className="hover:bg-white/5 transition-all group">
                <td className="px-10 py-10 font-black text-white text-2xl italic tracking-tighter">{exp.description}</td>
                <td className="px-10 py-10">
                  <span className="text-[10px] font-black px-5 py-2.5 rounded-2xl bg-white/5 text-slate-400 border border-white/10 uppercase tracking-[0.2em]">{exp.category}</span>
                </td>
                <td className="px-10 py-10 font-black text-rose-500 text-3xl tracking-tighter italic">R$ {exp.amount.toFixed(2)}</td>
                <td className="px-10 py-10 text-right">
                  <button onClick={() => { if(confirm('Excluir?')) dbService.del('expenses', exp.id) }} className="p-4 text-slate-500 hover:text-rose-500 hover:bg-rose-500/10 rounded-2xl transition-all opacity-0 group-hover:opacity-100"><Trash2 size={24} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Versão Mobile: Cards */}
      <div className="lg:hidden space-y-4">
        {expenses.map(exp => (
           <div key={exp.id} className="nexus-card p-6 border-white/5 space-y-4">
              <div className="flex justify-between items-start">
                 <div>
                    <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-1">{exp.category}</p>
                    <h4 className="text-xl font-black text-white italic">{exp.description}</h4>
                 </div>
                 <button onClick={() => { if(confirm('Excluir?')) dbService.del('expenses', exp.id) }} className="p-2 text-rose-500/30">
                    <Trash2 size={18}/>
                 </button>
              </div>
              <div className="flex justify-between items-center pt-4 border-t border-white/5">
                 <p className="text-[10px] font-bold text-slate-600 uppercase flex items-center gap-2">
                    <Calendar size={12}/> {exp.createdAt?.toDate().toLocaleDateString('pt-BR')}
                 </p>
                 <p className="text-2xl font-black text-rose-500 italic tracking-tighter">R$ {exp.amount.toFixed(2)}</p>
              </div>
           </div>
        ))}
      </div>

      {expenses.length === 0 && (
         <div className="py-40 text-center flex flex-col items-center">
            <div className="w-28 h-28 bg-white/5 rounded-[3rem] border-2 border-dashed border-white/10 flex items-center justify-center text-slate-700 mb-10">
              <WalletMinimal size={48} />
            </div>
            <p className="text-slate-500 font-black text-xl uppercase tracking-widest opacity-40 italic">Nenhuma saída detectada.</p>
         </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-xl p-8 lg:p-12 animate-fade-in border-rose-500/40">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-2xl lg:text-3xl font-black text-white italic text-rose-500 uppercase">Novo Registro de Custo</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-400 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>
            <form onSubmit={handleSave} className="space-y-6">
              <input required value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-bold placeholder:text-slate-700 outline-none focus:border-rose-500 transition-all text-xl" placeholder="Especificação do Gasto" />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Créditos R$</label>
                  <input required type="number" step="0.01" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-bold outline-none focus:border-rose-500 transition-all text-xl" />
                </div>
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-rose-500 uppercase tracking-widest ml-2">Protocolo</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-8 py-6 bg-black/60 border-2 border-white/5 rounded-[2rem] text-white font-black italic outline-none focus:border-rose-500 transition-all text-lg appearance-none">
                    <option className="bg-[#0c0628]">OPERACIONAL</option>
                    <option className="bg-[#0c0628]">MANUTENÇÃO</option>
                    <option className="bg-[#0c0628]">MARKETING</option>
                    <option className="bg-[#0c0628]">INFRAESTRUTURA</option>
                    <option className="bg-[#0c0628]">OUTROS</option>
                  </select>
                </div>
              </div>
              <button disabled={isSaving} type="submit" className="w-full bg-rose-500 text-white py-6 lg:py-8 rounded-[2rem] lg:rounded-[2.5rem] font-black text-lg lg:text-xl shadow-[0_0_40px_rgba(244,63,94,0.4)] hover:bg-rose-400 transition-all mt-8 flex items-center justify-center gap-4">
                {isSaving ? <Loader2 className="animate-spin" size={28} /> : <Zap size={28} className="fill-current" />}
                CONFIRMAR DRENAGEM
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExpensesView;

import React, { useState, useEffect } from 'react';
import { ShoppingCart, Plus, Minus, Trash2, Search, X, Loader2, Zap, Smartphone, User, Edit2, ChevronDown, ChevronUp, Calendar } from 'lucide-react';
import { Order, Product, Customer, OrderItem, UserProfile } from '../types';
import { dbService } from '../services/firebase';

interface OrdersViewProps {
  orders: Order[];
  products: Product[];
  customers: Customer[];
  userId: string;
  profile: UserProfile;
}

const OrdersView: React.FC<OrdersViewProps> = ({ orders, products, customers, userId, profile }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [guestData, setGuestData] = useState({ name: '', phone: '' });
  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED'>('PIX');
  const [installments, setInstallments] = useState(1);
  const [search, setSearch] = useState('');
  const [manualItem, setManualItem] = useState({ name: '', price: '', qty: '1' });
  const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);

  useEffect(() => {
    if (selectedCustomerId) {
      const c = customers.find(cust => cust.id === selectedCustomerId);
      if (c) {
        setGuestData({ name: c.name, phone: c.phone || '' });
      }
    } else {
      setGuestData({ name: '', phone: '' });
    }
  }, [selectedCustomerId, customers]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, quantity: 1, priceAtTime: product.price, nameAtTime: product.name, type: product.type }];
    });
  };

  const updateQty = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const addManualToCart = () => {
    if (!manualItem.name || !manualItem.price) return alert("Preencha dados do item.");
    const newItem: OrderItem = {
      productId: `manual-${Date.now()}`,
      quantity: parseInt(manualItem.qty),
      priceAtTime: parseFloat(manualItem.price),
      nameAtTime: manualItem.name.toUpperCase(),
      type: 'PRODUCT'
    };
    setCart(prev => [...prev, newItem]);
    setManualItem({ name: '', price: '', qty: '1' });
  };

  const generateWhatsAppReceipt = (orderData: any) => {
    const total = orderData.total;
    const dateStr = new Date().toLocaleDateString('pt-BR');
    const cName = orderData.guestName || 'Venda Rápida';

    let msg = `*📄 RECIBO - ${profile.officeName}*\n\n`;
    msg += `*Data:* ${dateStr}\n`;
    msg += `*Cliente:* ${cName}\n`;
    msg += `--------------------------\n`;
    orderData.items.forEach((item: any) => {
      msg += `• ${item.quantity}x ${item.nameAtTime} - R$ ${(item.priceAtTime * item.quantity).toFixed(2)}\n`;
    });
    msg += `--------------------------\n`;
    msg += `*TOTAL: R$ ${total.toFixed(2)}*\n`;
    msg += `*PAGAMENTO:* ${orderData.paymentMethod} ${orderData.installments > 1 ? `(${orderData.installments}x)` : ''}\n\n`;
    msg += `_Obrigado pela preferência!_`;

    const phone = orderData.guestPhone?.replace(/\D/g, '') || '';
    if (phone) window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
    else alert("Recibo gerado para: " + cName);
  };

  const finalize = async () => {
    if (cart.length === 0) return alert('Carrinho vazio.');
    setIsProcessing(true);
    try {
      const total = cart.reduce((acc, curr) => acc + (curr.priceAtTime * curr.quantity), 0);
      const orderData: any = {
        customerId: selectedCustomerId || 'GUEST',
        items: cart,
        total,
        status: 'PAID',
        paymentMethod,
        installments: installments,
        guestName: guestData.name.toUpperCase() || 'VENDA RÁPIDA',
        guestPhone: guestData.phone
      };

      await dbService.add('orders', userId, orderData);
      generateWhatsAppReceipt(orderData);

      setCart([]);
      setIsCreating(false);
      setSelectedCustomerId('');
      setGuestData({ name: '', phone: '' });
      setInstallments(1);
    } catch (e) { alert('Falha ao processar.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 lg:px-0">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl lg:text-4xl font-black text-white italic tracking-tighter text-glow-cyan">Vendas PdV</h2>
        {!isCreating && <button onClick={() => setIsCreating(true)} className="btn-radiant px-6 py-3 rounded-xl flex items-center gap-2 text-[10px]"><Plus size={16}/> NOVA VENDA</button>}
      </div>

      {isCreating ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="nexus-card p-6 border-cyan-400/20 bg-cyan-400/5 box-glow-orange">
              <div className="flex gap-2">
                <input placeholder="Item..." value={manualItem.name} onChange={e=>setManualItem({...manualItem, name: e.target.value})} className="flex-1 bg-black/40 border border-white/5 p-3 rounded-lg text-white outline-none text-sm" />
                <input placeholder="R$" type="number" value={manualItem.price} onChange={e=>setManualItem({...manualItem, price: e.target.value})} className="w-20 bg-black/40 border border-white/5 p-3 rounded-lg text-white outline-none text-sm" />
                <button onClick={addManualToCart} className="bg-cyan-400 text-black px-4 rounded-lg font-black"><Plus/></button>
              </div>
            </div>

            <div className="bg-white/5 p-4 rounded-2xl border border-white/5 flex items-center gap-3 box-glow-orange">
              <Search className="text-cyan-400" size={18}/>
              <input placeholder="Filtrar catálogo..." className="bg-transparent flex-1 outline-none text-white font-bold text-sm" value={search} onChange={e => setSearch(e.target.value)} />
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 max-h-[300px] overflow-y-auto pr-1">
              {products.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                <button key={p.id} onClick={() => addToCart(p)} className="nexus-card p-4 text-left border-white/5 hover:border-cyan-400/30 transition-all box-glow-orange">
                   <p className="font-black text-white text-[10px] truncate uppercase">{p.name}</p>
                   <p className="text-cyan-400 font-black text-sm mt-1">R$ {p.price.toFixed(2)}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="nexus-card p-6 lg:p-8 h-fit border-orange-400/30 box-glow-orange">
            <div className="flex justify-between items-center mb-6 border-b border-white/5 pb-4">
              <h3 className="font-terminal font-black text-sm text-glow-orange uppercase">Checkout</h3>
              <button onClick={() => setIsCreating(false)}><X className="text-slate-500"/></button>
            </div>
            <div className="space-y-6">

              <div className="space-y-4 bg-black/30 p-4 rounded-2xl border border-white/5">
                <p className="text-[9px] font-black text-orange-400 uppercase tracking-widest flex items-center gap-2"><Edit2 size={12}/> Dados do Cliente / Zap</p>
                <select value={selectedCustomerId} onChange={e => setSelectedCustomerId(e.target.value)} className="w-full bg-black/40 border border-white/10 p-3 rounded-xl text-white text-[10px] uppercase font-bold">
                  <option value="">-- CLIENTE AVULSO --</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>

                <div className="grid grid-cols-1 gap-3">
                  <input 
                    placeholder="NOME DO CLIENTE" 
                    value={guestData.name} 
                    onChange={e => setGuestData({...guestData, name: e.target.value})}
                    className="w-full bg-black/40 border border-white/10 p-3 rounded-xl text-white text-[10px] uppercase font-bold"
                  />
                  <input 
                    placeholder="WHATSAPP (DDD + NÚMERO)" 
                    value={guestData.phone} 
                    onChange={e => setGuestData({...guestData, phone: e.target.value})}
                    className="w-full bg-black/40 border border-white/10 p-3 rounded-xl text-white text-[10px] font-bold"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">Parcelas</label>
                <select value={installments} onChange={e => setInstallments(parseInt(e.target.value))} className="w-full bg-black/40 border border-white/10 p-4 rounded-xl text-white text-xs">
                  {[1,2,3,4,5,6,10,12,18,24].map(n => <option key={n} value={n}>{n}x</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-2">
                {['PIX', 'CASH', 'CREDIT_CARD', 'DEFERRED'].map(m => (
                  <button key={m} onClick={() => setPaymentMethod(m as any)} className={`p-3 rounded-lg border text-[8px] font-black ${paymentMethod === m ? 'border-cyan-400 text-cyan-400 bg-cyan-400/10' : 'border-white/5 text-slate-500'}`}>{m}</button>
                ))}
              </div>

              <div className="max-h-[150px] overflow-y-auto space-y-2">
                {cart.map((item, idx) => (
                  <div key={idx} className="flex flex-col bg-white/5 p-3 rounded-lg">
                    <div className="flex justify-between text-[10px] font-bold mb-2">
                      <span className="text-white truncate flex-1 uppercase">{item.nameAtTime}</span>
                      <button onClick={() => setCart(cart.filter((_,i)=>i!==idx))} className="text-rose-500"><Trash2 size={12}/></button>
                    </div>
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-2">
                          <button onClick={() => updateQty(item.productId, -1)} className="p-1 bg-white/5 rounded text-white"><Minus size={10}/></button>
                          <span className="text-cyan-400 font-black text-xs">{item.quantity}</span>
                          <button onClick={() => updateQty(item.productId, 1)} className="p-1 bg-white/5 rounded text-white"><Plus size={10}/></button>
                       </div>
                       <span className="text-white font-black text-xs">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                    </div>
                  </div>
                ))}
              </div>

              <div className="pt-6 border-t border-white/5">
                <div className="flex justify-between items-end mb-6">
                   <span className="text-slate-500 text-[10px] font-black uppercase">Total</span>
                   <span className="text-3xl font-black text-white italic text-glow-cyan">R$ {cart.reduce((s,i)=>s+(i.priceAtTime*i.quantity),0).toFixed(2)}</span>
                </div>
                <button disabled={isProcessing || cart.length === 0} onClick={finalize} className="btn-radiant w-full py-5 rounded-xl font-black text-[12px] flex justify-center gap-2">
                  {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>} FINALIZAR VENDA
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
           {orders.map(o => {
             const isExpanded = expandedOrderId === o.id;
             const installmentValue = o.total / (o.installments || 1);

             return (
               <div key={o.id} className="nexus-card overflow-hidden group border-white/5 box-glow-orange transition-all">
                  <div 
                    onClick={() => setExpandedOrderId(isExpanded ? null : o.id)}
                    className="p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 cursor-pointer hover:bg-white/5 transition-colors"
                  >
                    <div>
                      <p className="text-[8px] font-mono text-slate-500 uppercase tracking-widest">#{o.id.substring(0,6)} • {o.paymentMethod} {o.installments && o.installments > 1 ? `(${o.installments}x)` : ''}</p>
                      <p className="text-lg font-black text-white italic tracking-tight mt-1 uppercase">
                        {(o as any).guestName || 'Venda Rápida'}
                      </p>
                    </div>
                    <div className="flex items-center gap-6 w-full sm:w-auto justify-between border-t sm:border-t-0 border-white/5 pt-4 sm:pt-0">
                       <p className="text-2xl font-black text-cyan-400 italic tracking-tighter text-glow-cyan">R$ {o.total.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button onClick={(e)=>{e.stopPropagation(); generateWhatsAppReceipt(o)}} className="p-3 bg-cyan-400/10 text-cyan-400 rounded-xl"><Smartphone size={18}/></button>
                          {isExpanded ? <ChevronUp className="text-slate-500"/> : <ChevronDown className="text-slate-500"/>}
                       </div>
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-8 bg-black/30 border-t border-white/5 animate-fade-in space-y-8">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                          <div>
                             <h4 className="text-[10px] font-black text-cyan-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <ShoppingCart size={14}/> Itens da Venda
                             </h4>
                             <div className="space-y-3">
                                {o.items.map((item, idx) => (
                                  <div key={idx} className="flex justify-between items-center text-xs p-3 bg-white/5 rounded-xl border border-white/5">
                                     <span className="text-white font-bold uppercase">{item.quantity}x {item.nameAtTime}</span>
                                     <span className="text-slate-400 font-black">R$ {(item.priceAtTime * item.quantity).toFixed(2)}</span>
                                  </div>
                                ))}
                             </div>
                          </div>

                          <div>
                             <h4 className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <Calendar size={14}/> Plano de Recebimento
                             </h4>
                             <div className="space-y-2">
                                {Array.from({ length: o.installments || 1 }).map((_, idx) => {
                                  const dueDate = new Date(o.createdAt?.toDate() || new Date());
                                  dueDate.setMonth(dueDate.getMonth() + idx);
                                  return (
                                    <div key={idx} className="flex justify-between items-center text-[10px] p-3 bg-white/5 rounded-xl border border-white/5">
                                       <span className="text-slate-500 font-black uppercase">Parcela {idx + 1} • {dueDate.toLocaleDateString('pt-BR')}</span>
                                       <span className="text-white font-black tracking-tighter">R$ {installmentValue.toFixed(2)}</span>
                                    </div>
                                  );
                                })}
                             </div>
                          </div>
                       </div>

                       <div className="flex justify-end pt-4">
                          <button onClick={(e)=>{e.stopPropagation(); if(confirm('Excluir?')) dbService.del('orders', o.id)}} className="flex items-center gap-2 text-[9px] font-black text-rose-500 uppercase hover:text-white transition-colors">
                             <Trash2 size={14}/> Excluir Registro
                          </button>
                       </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>
      )}
    </div>
  );
};

export default OrdersView;

import React, { useState, useEffect } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, dbService } from '../services/firebase';
import { Zap, Loader2, KeyRound, Mail, AlertCircle, MessageCircle } from 'lucide-react';

const LoginView: React.FC = () => {
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [refCode, setRefCode] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('ref');
    if (code) setRefCode(code.toUpperCase());
  }, []);

  const handleResetPassword = async () => {
    if (!email) return setMessage({ text: 'Digite seu e-mail operacional primeiro.', type: 'error' });
    try {
      await dbService.resetPassword(email);
      setMessage({ text: 'Link de recuperação enviado ao seu e-mail.', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao enviar link. Verifique o e-mail.', type: 'error' });
    }
  };

  const openWhatsAppSupport = () => {
    // Encaminhamento Automático para o Super Admin (giufarlosdias@hotmail.com)
    const msg = encodeURIComponent("Olá SuperAdmin Nexus! Preciso de suporte imediato em meu terminal operante. Identificação: " + (email || "Não informado"));
    window.open(`https://wa.me/5511910688022?text=${msg}`, '_blank');
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ text: '', type: '' });
    try {
      await signInWithEmailAndPassword(auth, email, pass);
    } catch (err: any) {
      if (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential') {
        try {
          const cred = await createUserWithEmailAndPassword(auth, email, pass);
          await dbService.initProfile(cred.user.uid, email, refCode);
        } catch (regErr: any) {
          setMessage({ text: 'Falha ao inicializar núcleo operacional.', type: 'error' });
        }
      } else {
        setMessage({ text: 'Erro de autenticação de rede.', type: 'error' });
      }
    } finally { setLoading(false); }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-[#05010d] p-6 relative overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-30"></div>

      <div className="w-full max-w-sm nexus-card p-10 border border-white/5 shadow-2xl relative z-10 box-glow-orange">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-cyan-400 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-cyan-400/20 rotate-3">
            <Zap size={40} className="text-black" />
          </div>
          <h1 className="font-terminal font-black text-3xl text-glow-cyan tracking-tighter italic uppercase leading-none">Nexus Radiant</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-3">Sincronização de Dados v2.0</p>
        </div>

        {message.text && (
          <div className={`mb-6 p-4 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border ${message.type === 'error' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'}`}>
            <AlertCircle size={16} /> {message.text}
          </div>
        )}

        <form onSubmit={submit} className="space-y-5">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">ID Operador (E-mail)</label>
            <div className="relative">
              <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-cyan-400/30" size={18} />
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="operador@nexus.com" />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-1">Chave Mestra</label>
            <div className="relative">
              <KeyRound className="absolute left-5 top-1/2 -translate-y-1/2 text-cyan-400/30" size={18} />
              <input required type="password" value={pass} onChange={e => setPass(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-4 text-white font-bold outline-none focus:border-cyan-400 transition-all placeholder:text-slate-700" placeholder="••••••••" />
            </div>
          </div>

          <div className="flex flex-col gap-4 mt-6">
             <div className="flex justify-between items-center px-1">
                <button type="button" onClick={handleResetPassword} className="text-[10px] font-black text-slate-500 hover:text-cyan-400 uppercase tracking-widest transition-colors">Esqueci minha senha</button>
                <button type="button" onClick={openWhatsAppSupport} className="flex items-center gap-2 text-[10px] font-black text-emerald-500 hover:text-emerald-400 uppercase tracking-widest transition-all">
                  <MessageCircle size={14} /> Suporte Zap
                </button>
             </div>
             {refCode && <span className="text-center text-[9px] font-black text-purple-400 uppercase tracking-widest">Código de Convite: {refCode}</span>}
          </div>

          <button disabled={loading} className="btn-radiant w-full py-6 rounded-2xl flex items-center justify-center gap-4 active:scale-95 group mt-4">
            {loading ? <Loader2 className="animate-spin" size={24}/> : (
              <>
                <span className="uppercase font-black tracking-widest">Acessar Terminal</span>
                <Zap size={20} className="fill-current" />
              </>
            )}
          </button>
        </form>

        <p className="mt-8 text-[9px] text-center text-slate-700 font-bold uppercase tracking-widest leading-relaxed">
          Os dados de cada escritório são criptografados e isolados por núcleo de segurança.
        </p>
      </div>
    </div>
  );
};

