  email: string;
  role: 'super-admin' | 'admin';
  status: 'active' | 'blocked';
  subscriptionStatus: 'PAID' | 'EXPIRED' | 'TRIAL';
  officeName: string;
  phone?: string;
  address?: string;
  pixKey?: string;
  logoUrl?: string;
  createdAt: any;
  subscriptionExpiresAt: any;
  referralCode: string;
  referredBy?: string;
  lineage: {
    l1?: string;
    l2?: string;
    l3?: string;
  };
}

export interface Quote {
  id: string;
  userId: string;
  customerId: string;
  customerName: string;
  items: OrderItem[];
  total: number;
  status: 'DRAFT' | 'SENT' | 'APPROVED' | 'REJECTED';
  validUntil: string;
  notes?: string;
  createdAt: any;
}

export interface Product {
  id: string;
  userId: string;
  name: string;
  description?: string;
  imageUrl?: string;
  price: number;
  stock: number;
  type: 'PRODUCT' | 'SERVICE';
  createdAt?: any;
}

export interface Customer {
  id: string;
  userId: string;
  name: string;
  email?: string;
  phone?: string;
  address?: string;
}

export interface OrderItem {
  productId: string;
  quantity: number;
  priceAtTime: number;
  nameAtTime: string;
  type: 'PRODUCT' | 'SERVICE' | 'LABOR';
}

export interface Installment {
  id: string;
  value: number;
  status: 'PENDING' | 'PAID';
  dueDate: any;
}

export interface Order {
  id: string;
  userId: string;
  customerId: string;
  items: OrderItem[];
  total: number;
  status: 'PAID' | 'PENDING' | 'QUOTE';
  paymentMethod: 'PIX' | 'CREDIT_CARD' | 'CASH' | 'DEFERRED';
  installments?: number;
  installmentDetails?: Installment[];
  guestName?: string;
  guestPhone?: string;
  createdAt: any;
}

export interface Expense {
  id: string;
  userId: string;
  description: string;
  amount: number;
  category: string;
  createdAt: any;
}

export type ViewState = 
  | 'MASTER_DASHBOARD' | 'OFFICE_MANAGEMENT' | 'MY_HUB' | 'PRODUCTS' | 'CUSTOMERS' 
  | 'ORDERS' | 'EXPENSES' | 'AI_INSIGHTS' | 'REFERRALS' | 'SETTINGS' | 'QUOTES'
  | 'SALES_HISTORY' | 'CALENDAR' | 'RECEIVABLES' | 'BACKUP' | 'COMPANY_SETTINGS';

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Package, Search, Loader2, Upload, Share2, X, Image as ImageIcon, Smartphone } from 'lucide-react';
import { dbService } from '../services/firebase';
import { Product } from '../types';

const ProductsView: React.FC<{userId: string}> = ({ userId }) => {
  const [items, setItems] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [name, setName] = useState('');
  const [price, setPrice] = useState('');
  const [stock, setStock] = useState('0');
  const [description, setDescription] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    return dbService.sync('products', userId, (data) => {
      setItems(data as Product[]);
      setLoading(false);
    });
  }, [userId]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const add = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!name || !price) return;
    await dbService.add('products', userId, { 
      name, 
      description,
      imageUrl,
      price: parseFloat(price), 
      stock: parseInt(stock), 
      type: 'PRODUCT' 
    });
    setName(''); setPrice(''); setStock('0'); setDescription(''); setImageUrl('');
    setIsModalOpen(false);
  };

  const shareProduct = (p: Product) => {
    const msg = `*🛍️ CATÁLOGO: ${p.name.toUpperCase()}*\n\n` +
                `*Valor:* R$ ${p.price.toFixed(2)}\n` +
                `*Descrição:* ${p.description || 'Consultar detalhes'}\n` +
                `*Disponibilidade:* ${p.stock > 0 ? `${p.stock} unidades` : 'Sob encomenda'}\n\n` +
                `_Interessado? Entre em contato agora!_`;

    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const filtered = items.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
        <div>
          <h2 className="text-4xl lg:text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Catálogo Nexus</h2>
          <p className="text-slate-500 font-bold mt-4 text-sm tracking-widest uppercase opacity-70">Vitrine Digital de Alta Performance.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="btn-radiant px-10 py-5 rounded-[2.5rem] flex items-center gap-4 active:scale-95 transition-all text-sm font-black"
        >
          <Plus size={24}/> NOVO ITEM
        </button>
      </div>

      <div className="bg-[#0c0628]/80 p-8 rounded-[3rem] border-2 border-cyan-400/20 flex items-center gap-6 shadow-inner backdrop-blur-3xl focus-within:border-cyan-400 transition-all">
        <Search className="text-cyan-400/50" size={32} />
        <input 
          type="text" 
          placeholder="Localizar produto no catálogo..." 
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)} 
          className="flex-1 bg-transparent outline-none font-black text-white placeholder:text-slate-700 text-2xl tracking-tight italic" 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {loading ? (
          <div className="col-span-full py-20 flex justify-center"><Loader2 className="animate-spin text-cyan-400" size={48} /></div>
        ) : filtered.map(p => (
          <div key={p.id} className="nexus-card overflow-hidden group border-white/5 hover:border-cyan-400/30 transition-all flex flex-col">
            <div className="h-56 bg-white/5 relative overflow-hidden flex items-center justify-center border-b border-white/5">
              {p.imageUrl ? (
                <img src={p.imageUrl} alt={p.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
              ) : (
                <ImageIcon size={64} className="text-slate-800" />
              )}
              <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-all">
                <button 
                  onClick={() => shareProduct(p)}
                  className="p-3 bg-emerald-500 text-black rounded-xl hover:scale-110 transition-all shadow-lg"
                  title="Compartilhar no WhatsApp"
                >
                  <Share2 size={18}/>
                </button>
                <button 
                  onClick={() => dbService.del('products', p.id)}
                  className="p-3 bg-rose-500 text-white rounded-xl hover:scale-110 transition-all shadow-lg"
                  title="Remover"
                >
                  <Trash2 size={18}/>
                </button>
              </div>
              <div className="absolute bottom-4 left-4">
                 <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase ${p.stock > 0 ? 'bg-cyan-400 text-black' : 'bg-rose-600 text-white'}`}>
                   {p.stock > 0 ? `${p.stock} UN DISPONÍVEL` : 'ESGOTADO'}
                 </span>
              </div>
            </div>

            <div className="p-8 flex-1 flex flex-col justify-between">
              <div>
                <h3 className="text-xl font-black text-white uppercase italic tracking-tight mb-2 truncate text-glow-cyan">{p.name}</h3>
                <p className="text-slate-500 font-bold text-[10px] leading-relaxed line-clamp-2 uppercase tracking-widest mb-6">
                  {p.description || 'Sem descrição técnica.'}
                </p>
              </div>

              <div className="flex justify-between items-end border-t border-white/5 pt-6">
                 <div>
                    <p className="text-[9px] font-black text-slate-600 uppercase tracking-widest mb-1">Valor Unitário</p>
                    <p className="text-3xl font-black text-white italic tracking-tighter">R$ {p.price.toFixed(2)}</p>
                 </div>
                 <button onClick={() => shareProduct(p)} className="flex items-center gap-2 text-emerald-500 hover:text-emerald-400 transition-colors">
                    <Smartphone size={20}/>
                 </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
          <div className="nexus-card w-full max-w-2xl p-10 lg:p-12 animate-fade-in border-cyan-400/50 shadow-[0_0_80px_rgba(0,243,255,0.1)]">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-3xl font-black text-white italic text-glow-cyan uppercase">Novo Item de Catálogo</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-12 h-12 flex items-center justify-center bg-white/5 rounded-2xl text-slate-400 hover:text-rose-500 transition-colors"><X size={32} /></button>
            </div>

            <form onSubmit={add} className="space-y-8">
              <div className="flex flex-col md:flex-row gap-8">
                <div className="w-full md:w-48 h-48 bg-black/60 rounded-3xl border-2 border-dashed border-white/10 flex flex-col items-center justify-center relative overflow-hidden group">
                  {imageUrl ? (
                    <>
                      <img src={imageUrl} alt="Preview" className="w-full h-full object-cover" />
                      <button type="button" onClick={() => setImageUrl('')} className="absolute top-2 right-2 p-1 bg-rose-500 rounded-lg text-white opacity-0 group-hover:opacity-100 transition-all"><X size={14}/></button>
                    </>
                  ) : (
                    <>
                      <ImageIcon size={40} className="text-slate-700 mb-2"/>
                      <label className="cursor-pointer text-[8px] font-black text-cyan-400 uppercase tracking-widest bg-cyan-400/10 px-4 py-2 rounded-lg border border-cyan-400/20">
                        UPLOAD FOTO
                        <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
                      </label>
                    </>
                  )}
                </div>

                <div className="flex-1 space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-2">Título do Produto</label>
                    <input required value={name} onChange={e => setName(e.target.value)} className="w-full px-6 py-4 bg-black/60 border-2 border-white/5 rounded-2xl text-white font-bold outline-none focus:border-cyan-400" placeholder="Ex: SmartWatch Nexus X" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-2">Preço R$</label>
                      <input required type="number" step="0.01" value={price} onChange={e => setPrice(e.target.value)} className="w-full px-6 py-4 bg-black/60 border-2 border-white/5 rounded-2xl text-white font-bold outline-none focus:border-cyan-400" placeholder="0,00" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-2">Disponível</label>
                      <input type="number" value={stock} onChange={e => setStock(e.target.value)} className="w-full px-6 py-4 bg-black/60 border-2 border-white/5 rounded-2xl text-white font-bold outline-none focus:border-cyan-400" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-cyan-400 uppercase tracking-widest ml-2">Descrição / Especificações Técnicas</label>
                <textarea 
                  value={description} 
                  onChange={e => setDescription(e.target.value)} 
                  className="w-full px-6 py-4 bg-black/60 border-2 border-white/5 rounded-2xl text-white font-bold outline-none focus:border-cyan-400 h-32 resize-none" 
                  placeholder="Descreva as qualidades e diferenciais do seu produto..." 
                />
              </div>

              <button type="submit" className="btn-radiant w-full py-8 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 mt-8">
                <Plus size={32} className="text-black" /> SINCRONIZAR AO CATÁLOGO
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductsView;
